INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93177, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指控", "is_correct": true, "explanation": "正确：指控即说某人做了坏事，“卖假药”正是被指控的违法行为，符合句意。"}, {"text": "批准", "is_correct": false, "explanation": "语义：批准表示同意，与“卖假药”这种违法行为不符。"}, {"text": "推荐", "is_correct": false, "explanation": "语义：推荐是向人介绍好的东西，不能用于违法行为。"}, {"text": "报销", "is_correct": false, "explanation": "搭配：“报销”后接的是费用或开支，不能接“卖假药”。"}], "explanations": {"指控": "正确：指控即说某人做了坏事，“卖假药”正是被指控的违法行为，符合句意。", "批准": "语义：批准表示同意，与“卖假药”这种违法行为不符。", "推荐": "语义：推荐是向人介绍好的东西，不能用于违法行为。", "报销": "搭配：“报销”后接的是费用或开支，不能接“卖假药”。"}, "sentence_index": 6, "correct_answer": "指控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我指控明天会下雨。", "explanation": "这里应该用〈认为〉。指控是说某人做了坏事，对天气的判断不能用“指控”。"}, {"text": "他很会指控自己的情绪。", "explanation": "这里应该用〈控制〉。“指控”含有控告对方罪行的意思，管理情绪要用“控制”。"}, {"text": "老板指控员工工作认真。", "explanation": "这里应该用〈表扬〉。指控要说明对方做了坏事，对工作认真的员工应当表扬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93177, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店主指控了过他偷东西。", "corrected_sentence": "店主指控过他偷东西。", "error_description": "“指控”后用“过”表示经历，不能再加“了”；应说“指控过他偷东西”，“了过”连用是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93177, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板把指控我们泄露了秘密。", "corrected_sentence": "老板指控我们泄露了秘密。", "error_description": "“把”后须接被处置的对象，此句“把”后直接是动词“指控”，不合语法，应去掉“把”，说“老板指控我们泄露了秘密”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
