INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93179, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提名是说出一个人，请大家考虑选他。", "primary_collocate": null, "pronunciation": "tí míng", "ipa": "tʰi˧˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "谁当组长？我提名小明。", "target_word": "提名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她提名我当组长，我很高兴。", "target_word": "提名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家想选一个人，你想提名谁？", "target_word": "提名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我要提名最认真的小张。", "target_word": "提名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "班里选班长，有人提名了小红。", "target_word": "提名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站起来，提名老王当队长。", "target_word": "提名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以提名你信任的人，大家再投票。", "target_word": "提名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时，没有人提名自己的朋友。", "target_word": "提名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先提名，再让大家一起投票。", "target_word": "提名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上次选队长时，他提名过我，我没有同意。", "target_word": "提名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提名了", "label": "体标"}, {"form": "提名过", "label": "体标"}, {"form": "提名者", "label": "复合"}], "register": "中性", "sense_fingerprint": "提名：开口说出某个人的名字，请大家考虑选他", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c5916a-9e2c-4e57-852e-1ec8e059930b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93179, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "提名", "is_correct": true, "explanation": "提名（tí míng）：开口说出某人的名字，请大家考虑选他。"}, {"text": "黎明", "is_correct": false, "explanation": "lí míng 与 tí míng 只有声母不同（l 与 t），声调相同（都是第二声）。意思是天快亮的时候。"}, {"text": "齐名", "is_correct": false, "explanation": "qí míng 与 tí míng 只有声母不同（q 与 t），声调相同（都是第二声）。意思是名望相当、并称于世。"}, {"text": "实名", "is_correct": false, "explanation": "shí míng 与 tí míng 只有声母不同（sh 与 t），声调相同（都是第二声）。意思是用真实姓名。"}], "explanations": {"提名": "提名（tí míng）：开口说出某人的名字，请大家考虑选他。", "黎明": "lí míng 与 tí míng 只有声母不同（l 与 t），声调相同（都是第二声）。意思是天快亮的时候。", "齐名": "qí míng 与 tí míng 只有声母不同（q 与 t），声调相同（都是第二声）。意思是名望相当、并称于世。", "实名": "shí míng 与 tí míng 只有声母不同（sh 与 t），声调相同（都是第二声）。意思是用真实姓名。"}, "sentence_index": null, "correct_answer": "提名"}, "level_3": {"options": [{"text": "提名", "is_correct": true, "explanation": "提名：说出某人的名字，请大家考虑选他，与“谁当组长”的提问相符。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指出错误，与“谁当组长”的提问无关，不能回答这个问题。"}, {"text": "赶走", "is_correct": false, "explanation": "语义：“赶走”表示驱逐，与选组长的语境完全矛盾。"}, {"text": "逮捕", "is_correct": false, "explanation": "搭配：“逮捕”的施事须是执法人员，与“谁当组长”的选举语境不搭配。"}], "explanations": {"提名": "提名：说出某人的名字，请大家考虑选他，与“谁当组长”的提问相符。", "批评": "语义：“批评”是指出错误，与“谁当组长”的提问无关，不能回答这个问题。", "赶走": "语义：“赶走”表示驱逐，与选组长的语境完全矛盾。", "逮捕": "搭配：“逮捕”的施事须是执法人员，与“谁当组长”的选举语境不搭配。"}, "sentence_index": 0, "correct_answer": "提名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我提名了周五去公园的路线。", "explanation": "这里应该用〈建议〉。提名指向大家提出候选人，不用于提出出行路线，提出意见要用“建议”。"}, {"text": "我提名了明天班会的地点。", "explanation": "这里应该用〈决定〉。提名是提出候选人，不用于确定地点，确定地点要用“决定”。"}, {"text": "我提名你考上了大学。", "explanation": "这里应该用〈祝贺〉。提名指提出候选人，不用于为别人的成就表示庆贺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93179, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提名", "is_correct": true, "explanation": "提名：提出你信任的人作为候选人，之后大家再投票，与句意相符。"}, {"text": "解雇", "is_correct": false, "explanation": "语义：“解雇”是辞退工作，与“大家再投票”的选举语境相矛盾。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的宾语是语言或文字，不能接“你信任的人”。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”是亲密的身体动作，与“大家再投票”的选举程序毫无关系。"}], "explanations": {"提名": "提名：提出你信任的人作为候选人，之后大家再投票，与句意相符。", "解雇": "语义：“解雇”是辞退工作，与“大家再投票”的选举语境相矛盾。", "翻译": "搭配：“翻译”的宾语是语言或文字，不能接“你信任的人”。", "拥抱": "语义：“拥抱”是亲密的身体动作，与“大家再投票”的选举程序毫无关系。"}, "sentence_index": 6, "correct_answer": "提名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想提名参加比赛。", "explanation": "这里应该用〈报名〉。提名是提出候选人，不用于表示自己申请参加活动。"}, {"text": "我向他提名，希望他原谅我。", "explanation": "这里应该用〈道歉〉。提名不能表示向人认错，希望对方原谅要用“道歉”。"}, {"text": "我向大家提名帮忙。", "explanation": "这里应该用〈请求〉。提名指提出候选人，不用于请大家帮忙，请人帮忙要用“请求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93179, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我提名了小红了当课代表。", "corrected_sentence": "我提名了小红当课代表。", "error_description": "“提名”后已有“了”，宾语“小红”之后不能再加“了”。正确说法是“我提名了小红当课代表”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93179, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一起提名一位了新组长。", "corrected_sentence": "我们一起提名一位新组长。", "error_description": "“了”不能插在数量短语“一位”和修饰语“新”之间，删去即可。正确说法：“我们一起提名一位新组长。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
