INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93180, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在评选前，提出可供选举的候选人名字。", "primary_collocate": null, "pronunciation": "tí míng", "ipa": "tʰi˧˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "老师提名小王当班长。", "target_word": "提名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家提名了三位候选人。", "target_word": "提名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他提名小李当学生会主席。", "target_word": "提名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "选举前，公司提名了两位新经理。", "target_word": "提名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁来提名下一位主席，请先举手。", "target_word": "提名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想提名王老师参加优秀教师的评选。", "target_word": "提名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议上，李明提名张华当新的负责人。", "target_word": "提名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们都提名她当代表。", "target_word": "提名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位老人曾经提名过很多年轻的作家。", "target_word": "提名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "委员会提名了三个人，下周再投票选出一位。", "target_word": "提名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提名了", "label": "体标"}, {"form": "提名过", "label": "体标"}, {"form": "提名人", "label": "复合"}], "register": "正式", "sense_fingerprint": "提名：在选举或评选之前，正式提出候选人的名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c5916a-9e2c-4e57-852e-1ec8e059930b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93180, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "提名", "is_correct": true, "explanation": "提名（tí míng）：在评选或选举前正式提出候选人的名字。"}, {"text": "黎明", "is_correct": false, "explanation": "lí míng 与 tí míng 只有声母不同（l 与 t），声调相同（都是第二声）。意思是天快亮的时候。"}, {"text": "齐名", "is_correct": false, "explanation": "qí míng 与 tí míng 只有声母不同（q 与 t），声调相同（都是第二声）。意思是名望相当、并称于世。"}, {"text": "实名", "is_correct": false, "explanation": "shí míng 与 tí míng 只有声母不同（sh 与 t），声调相同（都是第二声）。意思是用真实姓名。"}], "explanations": {"提名": "提名（tí míng）：在评选或选举前正式提出候选人的名字。", "黎明": "lí míng 与 tí míng 只有声母不同（l 与 t），声调相同（都是第二声）。意思是天快亮的时候。", "齐名": "qí míng 与 tí míng 只有声母不同（q 与 t），声调相同（都是第二声）。意思是名望相当、并称于世。", "实名": "shí míng 与 tí míng 只有声母不同（sh 与 t），声调相同（都是第二声）。意思是用真实姓名。"}, "sentence_index": null, "correct_answer": "提名"}, "level_3": {"options": [{"text": "提名", "is_correct": true, "explanation": "提名：在选举或评选前提出候选人，与“让小王当班长”的句意相符。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”针对过错或缺点，不能用来指任命小王担任班长。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是场所或物品，不能用来指让小王担任班长。"}, {"text": "学习", "is_correct": false, "explanation": "搭配：“学习”的宾语是知识或技能，不能接“小王当班长”这样的任职安排。"}], "explanations": {"提名": "提名：在选举或评选前提出候选人，与“让小王当班长”的句意相符。", "批评": "语义：“批评”针对过错或缺点，不能用来指任命小王担任班长。", "打扫": "语义：“打扫”的对象是场所或物品，不能用来指让小王担任班长。", "学习": "搭配：“学习”的宾语是知识或技能，不能接“小王当班长”这样的任职安排。"}, "sentence_index": 0, "correct_answer": "提名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我向朋友提名这本书，你一定要看看。", "explanation": "这里应该用〈推荐〉。提名只用于评选中提出候选人，不用于向朋友推荐图书。"}, {"text": "我来向大家提名一下我的新朋友。", "explanation": "这里应该用〈介绍〉。提名不表示向大家引见某人，那是“介绍”的用法。"}, {"text": "我提名了明天见面的时间。", "explanation": "这里应该用〈约定〉。提名只用于评选中提出候选人，不用于商定见面时间，商定时间要用“约定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提名", "is_correct": true, "explanation": "提名：在会议上提出候选人，与“让张华当新的负责人”的句意相符。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：“推翻”针对决定或结论，不能用来指让张华担任负责人。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：“辞退”是解雇的意思，与“当新的负责人”的任职义正好相反。"}, {"text": "拜访", "is_correct": false, "explanation": "搭配：“拜访”的宾语是人或地点，不能接“张华当新的负责人”这样的兼语结构。"}], "explanations": {"提名": "提名：在会议上提出候选人，与“让张华当新的负责人”的句意相符。", "推翻": "语义：“推翻”针对决定或结论，不能用来指让张华担任负责人。", "辞退": "语义：“辞退”是解雇的意思，与“当新的负责人”的任职义正好相反。", "拜访": "搭配：“拜访”的宾语是人或地点，不能接“张华当新的负责人”这样的兼语结构。"}, "sentence_index": 6, "correct_answer": "提名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师提名了他的努力。", "explanation": "这里应该用〈表扬〉。提名只能指向候选人，不能用来褒扬某人的努力。"}, {"text": "经理提名了新的规定。", "explanation": "这里应该用〈宣布〉。提名指提出候选人，不用于公布规定。"}, {"text": "老板提名了下周的会议时间。", "explanation": "这里应该用〈提议〉。提名只用于评选中提出候选人，不用于提出会议时间，提出安排要用“提议”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家提名了他了当班长。", "corrected_sentence": "大家提名了他当班长。", "error_description": "“提名”后已经有“了”，宾语“他”之后不能再加“了”。正确说法是“大家提名了他当班长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们提名我了做代表。", "corrected_sentence": "他们提名了我做代表。", "error_description": "“了”应紧跟动词“提名”，表示动作完成，应说“提名了我”，不能放在宾语“我”的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93181, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "担心", "is_correct": true, "explanation": "担心与放心意思相反：放心是不再忧虑，担心是心里忧虑。"}, {"text": "完成", "is_correct": false, "explanation": "完成与“放心”没有反义关系，不是这个义项的反义词。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论与“放心”没有反义关系，二者意义无对立。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行与“放心”没有反义关系，二者无法构成对立。"}], "correct_answer": "担心", "explanations": {"担心": "担心与放心意思相反：放心是不再忧虑，担心是心里忧虑。", "完成": "完成与“放心”没有反义关系，不是这个义项的反义词。", "讨论": "讨论与“放心”没有反义关系，二者意义无对立。", "旅行": "旅行与“放心”没有反义关系，二者无法构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93181, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "担心", "is_correct": true, "explanation": "担心与放心意思相反：放心是不再忧虑，担心是心里忧虑。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭与“放心”没有反义关系，二者意义无对立。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步与“放心”没有反义关系，不构成对立。"}, {"text": "搬家", "is_correct": false, "explanation": "搬家与“放心”没有反义关系，二者无法构成对立。"}], "correct_answer": "担心", "explanations": {"担心": "担心与放心意思相反：放心是不再忧虑，担心是心里忧虑。", "吃饭": "吃饭与“放心”没有反义关系，二者意义无对立。", "跑步": "跑步与“放心”没有反义关系，不构成对立。", "搬家": "搬家与“放心”没有反义关系，二者无法构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93181, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "放心是心里不担心了。", "primary_collocate": null, "pronunciation": "fàng xīn", "ipa": "faŋ˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "你放心，我一定按时到。", "target_word": "放心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听到她的声音，妈妈才放心了。", "target_word": "放心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说会打电话，我这才放心。", "target_word": "放心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说手术很顺利，请大家放心。", "target_word": "放心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作交给他，你完全可以放心。", "target_word": "放心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到家后请给我发个短信，让我放心。", "target_word": "放心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子第一次一个人坐飞机，妈妈一直不放心。", "target_word": "放心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说考试不难，让大家放心。", "target_word": "放心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把钥匙交给邻居后，这才放心，出了门。", "target_word": "放心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查过了，说你的病不严重，你可以放心了。", "target_word": "放心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放心了", "label": "体标"}, {"form": "放了心", "label": "体标"}, {"form": "放下心来", "label": "复合"}], "register": "中性", "sense_fingerprint": "放心：对人或事不再担心，心里踏实下来（动作或变化）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c5916a-9e2c-4e57-852e-1ec8e059930b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93181, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放心", "is_correct": true, "explanation": "正确：“放心”表示不再担心，与后句“我一定按时到”的保证相呼应。"}, {"text": "担心", "is_correct": false, "explanation": "语义：“担心”表示忧虑，与“我一定按时到”的保证语气相反；劝慰时应说“别担心”。"}, {"text": "小心", "is_correct": false, "explanation": "语义：“小心”是提醒对方留神，与“我一定按时到”的保证意思不合。"}, {"text": "放手", "is_correct": false, "explanation": "语义：“放手”指松开手，与“按时到”的语境无关。"}], "explanations": {"放心": "正确：“放心”表示不再担心，与后句“我一定按时到”的保证相呼应。", "担心": "语义：“担心”表示忧虑，与“我一定按时到”的保证语气相反；劝慰时应说“别担心”。", "小心": "语义：“小心”是提醒对方留神，与“我一定按时到”的保证意思不合。", "放手": "语义：“放手”指松开手，与“按时到”的语境无关。"}, "sentence_index": 0, "correct_answer": "放心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "过马路的时候，你一定要放心，别东张西望。", "explanation": "这里应该用〈小心〉。放心表示不再担心，不能用来提醒对方注意安全，过马路要说“小心”。"}, {"text": "这位老师很放心，一进教室就大声训斥学生。", "explanation": "这里应该用〈严厉〉。放心表示心里安定，不能用来形容老师对学生的严厉态度。"}, {"text": "操作这台机器时，你必须放心，不能马虎。", "explanation": "这里应该用〈谨慎〉。放心表示不再担心，不能要求人在操作机器时“放心”，这里应保持谨慎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93181, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放心", "is_correct": true, "explanation": "正确：“不放心”表示妈妈仍然牵挂，“放心”的否定形式在这里正确。"}, {"text": "关心", "is_correct": false, "explanation": "语义：“关心”表示在意，“妈妈一直不关心”与妈妈对孩子的牵挂相反。"}, {"text": "感动", "is_correct": false, "explanation": "语义：“感动”指心里受触动，与妈妈一直挂念孩子的语境不合。"}, {"text": "回避", "is_correct": false, "explanation": "语义：“回避”是躲开，与妈妈一直挂念孩子的语境不合。"}], "explanations": {"放心": "正确：“不放心”表示妈妈仍然牵挂，“放心”的否定形式在这里正确。", "关心": "语义：“关心”表示在意，“妈妈一直不关心”与妈妈对孩子的牵挂相反。", "感动": "语义：“感动”指心里受触动，与妈妈一直挂念孩子的语境不合。", "回避": "语义：“回避”是躲开，与妈妈一直挂念孩子的语境不合。"}, "sentence_index": 6, "correct_answer": "放心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上楼梯时，你要放心，别摔倒。", "explanation": "这里应该用〈留神〉。放心表示不再担心，不能用来提醒对方脚下留神。"}, {"text": "他一遇到困难就放心，不愿再试一次。", "explanation": "这里应该用〈放弃〉。放心表示心里不再担心，不能用来表示不再坚持。"}, {"text": "他一听到打雷就放心，躲进被子里不出来。", "explanation": "这里应该用〈害怕〉。放心表示心里不担心，不能用来表示被雷声吓到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93181, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我跟你放心，让你一个人去。", "corrected_sentence": "我对你放心，让你一个人去。", "error_description": "错误：“跟你放心”，引出对象的介词用错。正确：“对你放心”，“放心”的对象要用“对”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93181, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子到家了，我这才放心着。", "corrected_sentence": "孩子到家了，我这才放心了。", "error_description": "错误：“放心着”，持续态“着”用错。正确：“放心了”，到家后心情一下子安定，是完成的变化，要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
