INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93182, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心情安定，没有忧虑。", "primary_collocate": null, "pronunciation": "fàng xīn", "ipa": "faŋ˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "把孩子交给她，我很放心。", "target_word": "放心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的水很干净，喝着放心。", "target_word": "放心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有你在身边，我心里特别放心。", "target_word": "放心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈做的饭，大家吃得很放心。", "target_word": "放心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一位让人放心的医生。", "target_word": "放心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做事认真，大家都很放心。", "target_word": "放心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车检查过了，开着很放心。", "target_word": "放心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在安全的小区里，爸妈觉得很放心。", "target_word": "放心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说他已经到家了，我才睡得放心。", "target_word": "放心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子还没回家，妈妈心里一点也不放心，睡不好。", "target_word": "放心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不放心", "label": "否定"}, {"form": "放心地", "label": "状语"}, {"form": "放心了", "label": "体标"}], "register": "中性", "sense_fingerprint": "放心：形容心里安定、没有忧虑的状态，常说很放心、让人放心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c5916a-9e2c-4e57-852e-1ec8e059930b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放心", "is_correct": true, "explanation": "正确：“很放心”表示心里安定、没有忧虑，与“把孩子交给她”的信任相符。"}, {"text": "粗心", "is_correct": false, "explanation": "语义：“粗心”指做事不仔细，与“把孩子交给她”所表达的信任相反。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描写身材，不能用来说明心里的感受。"}, {"text": "小气", "is_correct": false, "explanation": "语义：“小气”指吝啬，与托付孩子的语境无关。"}], "explanations": {"放心": "正确：“很放心”表示心里安定、没有忧虑，与“把孩子交给她”的信任相符。", "粗心": "语义：“粗心”指做事不仔细，与“把孩子交给她”所表达的信任相反。", "胖": "体貌：“胖”描写身材，不能用来说明心里的感受。", "小气": "语义：“小气”指吝啬，与托付孩子的语境无关。"}, "sentence_index": 0, "correct_answer": "放心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他长得很放心，大家都说他很英俊。", "explanation": "这里应该用〈英俊〉。放心形容心里安定，不能用来描写外貌。"}, {"text": "这个女孩很放心，说话时总是低着头、不敢看人。", "explanation": "这里应该用〈害羞〉。放心表示心里安定，不能用来形容一个人羞怯的样子。"}, {"text": "这孩子很放心，上课总爱捣乱。", "explanation": "这里应该用〈调皮〉。放心表示心里安定，不能用来形容孩子淘气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放心", "is_correct": true, "explanation": "正确：“开着很放心”表示车经过检查，开起来让人安心，与句意一致。"}, {"text": "危险", "is_correct": false, "explanation": "语义：“危险”表示有安全隐患，与“检查过了”的语境相反。"}, {"text": "难看", "is_correct": false, "explanation": "体貌：“难看”描写外观，不能用来说明开车时的感受。"}, {"text": "精彩", "is_correct": false, "explanation": "搭配：“精彩”多用于表演、比赛，不用来描述驾驶的感受。"}], "explanations": {"放心": "正确：“开着很放心”表示车经过检查，开起来让人安心，与句意一致。", "危险": "语义：“危险”表示有安全隐患，与“检查过了”的语境相反。", "难看": "体貌：“难看”描写外观，不能用来说明开车时的感受。", "精彩": "搭配：“精彩”多用于表演、比赛，不用来描述驾驶的感受。"}, "sentence_index": 6, "correct_answer": "放心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一听到笑话就放心，笑得停不下来。", "explanation": "这里应该用〈开心〉。放心表示不再担心，不能用来形容因笑话而高兴的样子。"}, {"text": "这孩子很放心，每天在院子里大喊大叫。", "explanation": "这里应该用〈活泼〉。放心表示心里安定，不能用来形容孩子跑跳喧闹的样子。"}, {"text": "他拿着玻璃杯走路，很放心，生怕摔了。", "explanation": "这里应该用〈小心〉。放心表示不再担心，与“生怕摔了”的谨慎心理矛盾，这里应该用〈小心〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "把钥匙交给老张，我很很放心。", "corrected_sentence": "把钥匙交给老张，我很放心。", "error_description": "错误：“很很放心”，程度副词“很”重复。正确：“很放心”，程度副词只用一个“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "知道他平安到达，我才睡放心。", "corrected_sentence": "知道他平安到达，我才睡得放心。", "error_description": "错误：“睡放心”，动词与补语之间漏掉了“得”。正确：“睡得放心”，动词和补语“放心”之间要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
