INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93183, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "断是一整条东西分成了两段。", "primary_collocate": null, "pronunciation": "duàn", "ipa": "tu̯an˥˩", "syllable_count": 1, "sentences": [{"text": "绳子太旧，一拉就断了。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，树枝断了。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的铅笔断了，你有笔吗？", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根线太细，很容易断。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "筷子断成了两段。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，旗杆断了。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿断过一次，现在好了。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风筝线断了，风筝飞走了。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绳子从中间断成了两段。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服的带子断了，我想换一条。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "断了", "label": "体标"}, {"form": "断过", "label": "体标"}, {"form": "折断", "label": "复合"}, {"form": "斷", "label": "繁体"}], "register": "口语", "sense_fingerprint": "长条的东西断成两截", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c5916a-9e2c-4e57-852e-1ec8e059930b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93183, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "断", "is_correct": true, "explanation": "断（duàn）指长条的东西分开，是本题的目标词。"}, {"text": "短", "is_correct": false, "explanation": "duǎn（第三声）与 duàn（第四声）声调不同，意思是长度小。"}, {"text": "端", "is_correct": false, "explanation": "duān（第一声）与 duàn 声调不同，意思是端点、端正。"}, {"text": "乱", "is_correct": false, "explanation": "luàn 与 duàn 声母不同（l/d），声调相同，意思是混乱。"}, {"text": "钻", "is_correct": false, "explanation": "zuàn 与 duàn 声母不同（z/d），声调相同，意思是钻研、钻孔。"}], "explanations": {"断": "断（duàn）指长条的东西分开，是本题的目标词。", "短": "duǎn（第三声）与 duàn（第四声）声调不同，意思是长度小。", "端": "duān（第一声）与 duàn 声调不同，意思是端点、端正。", "乱": "luàn 与 duàn 声母不同（l/d），声调相同，意思是混乱。", "钻": "zuàn 与 duàn 声母不同（z/d），声调相同，意思是钻研、钻孔。"}, "sentence_index": null, "correct_answer": "断"}, "level_3": {"options": [{"text": "断", "is_correct": true, "explanation": "断：绳子受拉力后分开，符合「一拉就断了」的语境。"}, {"text": "写", "is_correct": false, "explanation": "语义：「写」与「绳子」「一拉」的情境毫不相干，句子说不通。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：「撕」多用于纸、布，不说绳子被撕断。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」与拉绳子的动作和绳子的状态无关。"}], "explanations": {"断": "断：绳子受拉力后分开，符合「一拉就断了」的语境。", "写": "语义：「写」与「绳子」「一拉」的情境毫不相干，句子说不通。", "撕": "搭配：「撕」多用于纸、布，不说绳子被撕断。", "唱": "语义：「唱」与拉绳子的动作和绳子的状态无关。"}, "sentence_index": 0, "correct_answer": "断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张报纸断了一个角。", "explanation": "这里应该用〈撕〉。纸张被撕掉一角要说撕，断用于长条的东西分开，不用于报纸。"}, {"text": "他断了一块豆腐。", "explanation": "这里应该用〈切〉。切豆腐要说切，断用于长条的东西分开，不用于豆腐。"}, {"text": "玻璃杯断了。", "explanation": "这里应该用〈碎〉。玻璃杯破裂要说碎，断用于长条的东西，不用于杯子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93183, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "断", "is_correct": true, "explanation": "断（duàn）指长条的东西分开，是本题的目标词。"}, {"text": "算", "is_correct": false, "explanation": "suàn（算）与 duàn 声母不同（s/d），声调相同，意思是计算。"}, {"text": "窜", "is_correct": false, "explanation": "cuàn（窜）与 duàn 声母不同（c/d），声调相同，意思是逃窜、乱跑。"}, {"text": "蛋", "is_correct": false, "explanation": "dàn（蛋）比 duàn 少了 u 音，声调相同，意思是鸡蛋。"}, {"text": "顿", "is_correct": false, "explanation": "dùn（顿）比 duàn 少了 a 音，声调相同，意思是一顿、停顿。"}], "explanations": {"断": "断（duàn）指长条的东西分开，是本题的目标词。", "算": "suàn（算）与 duàn 声母不同（s/d），声调相同，意思是计算。", "窜": "cuàn（窜）与 duàn 声母不同（c/d），声调相同，意思是逃窜、乱跑。", "蛋": "dàn（蛋）比 duàn 少了 u 音，声调相同，意思是鸡蛋。", "顿": "dùn（顿）比 duàn 少了 a 音，声调相同，意思是一顿、停顿。"}, "sentence_index": null, "correct_answer": "断"}, "level_3": {"options": [{"text": "断", "is_correct": true, "explanation": "断过：腿骨断裂过一次，符合「腿断过一次，现在好了」的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指进食，不能用于腿的受伤经历。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的对象是液体，不说「腿喝过」。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：「戴」用于帽子、眼镜等，不说「腿戴过」。"}], "explanations": {"断": "断过：腿骨断裂过一次，符合「腿断过一次，现在好了」的语境。", "吃": "语义：「吃」指进食，不能用于腿的受伤经历。", "喝": "搭配：「喝」的对象是液体，不说「腿喝过」。", "戴": "搭配：「戴」用于帽子、眼镜等，不说「腿戴过」。"}, "sentence_index": 6, "correct_answer": "断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服断了一个洞。", "explanation": "这里应该用〈破〉。衣服破洞要说破，断指长条的东西分开，不用于衣服上的洞。"}, {"text": "他断了那个盘子。", "explanation": "这里应该用〈摔〉。盘子摔碎要说摔，断用于绳、线等长条的东西，不用于盘子。"}, {"text": "工人断了那栋旧房子。", "explanation": "这里应该用〈拆〉。拆用于房屋等建筑，断指长条的东西断开，不用于房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把绳子断了。", "corrected_sentence": "他把绳子弄断了。", "error_description": "「断」表示自己断开，作不及物动词，不能直接放进「把」字句作谓语。前面要加「弄」，说「把绳子弄断了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条裤子的带子被断了，我想换一条。", "corrected_sentence": "这条裤子的带子断了，我想换一条。", "error_description": "「断」表示东西自己断裂，是不及物用法，不用「被」字句。应说「带子断了」，不说「带子被断了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93184, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "连", "is_correct": true, "explanation": "连（连接）与「断」构成反义关系，断了的联系可以重新连上。"}, {"text": "跑", "is_correct": false, "explanation": "跑与「断」没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑与「断」没有反义关系。"}, {"text": "站", "is_correct": false, "explanation": "站与「断」没有反义关系。"}], "correct_answer": "连", "explanations": {"连": "连（连接）与「断」构成反义关系，断了的联系可以重新连上。", "跑": "跑与「断」没有反义关系。", "笑": "笑与「断」没有反义关系。", "站": "站与「断」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93184, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "连", "is_correct": true, "explanation": "连（连接）与「断开」构成反义关系，断开的铁链可以连起来。"}, {"text": "吃", "is_correct": false, "explanation": "吃与「断」没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "睡与「断」没有反义关系。"}, {"text": "坐", "is_correct": false, "explanation": "坐与「断」没有反义关系。"}], "correct_answer": "连", "explanations": {"连": "连（连接）与「断开」构成反义关系，断开的铁链可以连起来。", "吃": "吃与「断」没有反义关系。", "睡": "睡与「断」没有反义关系。", "坐": "坐与「断」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93184, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "长形的东西分成几段；中断。", "primary_collocate": null, "pronunciation": "duàn", "ipa": "tu̯an˥˩", "syllable_count": 1, "sentences": [{"text": "这根木头断成了三段。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话突然断了，我没听完。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网断了，视频看不了。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩的联系早就断了。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里下大雨，路断了。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的来往断了好几年。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条铁链断成了几段。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机信号断了，我听不到你。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雪以后，这里的电断了两天。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长绳断成了好几段。", "target_word": "断", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "断了", "label": "体标"}, {"form": "断过", "label": "体标"}, {"form": "断开", "label": "复合"}, {"form": "斷", "label": "繁体"}], "register": "口语", "sense_fingerprint": "长形物断成几段；联系、信号等中断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c5916a-9e2c-4e57-852e-1ec8e059930b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93184, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "断", "is_correct": true, "explanation": "断（duàn）指长形的东西分成几段，是本题的目标词。"}, {"text": "短", "is_correct": false, "explanation": "duǎn（第三声）与 duàn（第四声）声调不同，意思是长度小。"}, {"text": "端", "is_correct": false, "explanation": "duān（第一声）与 duàn 声调不同，意思是端点、端正。"}, {"text": "乱", "is_correct": false, "explanation": "luàn 与 duàn 声母不同（l/d），声调相同，意思是混乱。"}, {"text": "钻", "is_correct": false, "explanation": "zuàn 与 duàn 声母不同（z/d），声调相同，意思是钻研、钻孔。"}], "explanations": {"断": "断（duàn）指长形的东西分成几段，是本题的目标词。", "短": "duǎn（第三声）与 duàn（第四声）声调不同，意思是长度小。", "端": "duān（第一声）与 duàn 声调不同，意思是端点、端正。", "乱": "luàn 与 duàn 声母不同（l/d），声调相同，意思是混乱。", "钻": "zuàn 与 duàn 声母不同（z/d），声调相同，意思是钻研、钻孔。"}, "sentence_index": null, "correct_answer": "断"}, "level_3": {"options": [{"text": "断", "is_correct": true, "explanation": "断成：木头被折断后分成几段，符合「断成了三段」的语境。"}, {"text": "写", "is_correct": false, "explanation": "语义：「写」不能使木头分成几段，句子说不通。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」多用于食物，不说「煮成三段」的木头。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」与木头分段的情况毫不相干。"}], "explanations": {"断": "断成：木头被折断后分成几段，符合「断成了三段」的语境。", "写": "语义：「写」不能使木头分成几段，句子说不通。", "煮": "搭配：「煮」多用于食物，不说「煮成三段」的木头。", "唱": "语义：「唱」与木头分段的情况毫不相干。"}, "sentence_index": 0, "correct_answer": "断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天断了一本书。", "explanation": "这里应该用〈读〉。读书要说读，断指长形的东西分开或联系、信号中断，不用于书。"}, {"text": "这段时间断成了三段。", "explanation": "这里应该用〈分〉。时间分段要说分，断用于绳、木头等长形的实物，不用于抽象的时间。"}, {"text": "他断了灯。", "explanation": "这里应该用〈关〉。关灯要说关，断指东西断裂或联系中断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93184, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "断", "is_correct": true, "explanation": "断（duàn）指长形的东西分成几段，是本题的目标词。"}, {"text": "算", "is_correct": false, "explanation": "suàn（算）与 duàn 声母不同（s/d），声调相同，意思是计算。"}, {"text": "窜", "is_correct": false, "explanation": "cuàn（窜）与 duàn 声母不同（c/d），声调相同，意思是逃窜、乱跑。"}, {"text": "蛋", "is_correct": false, "explanation": "dàn（蛋）比 duàn 少了 u 音，声调相同，意思是鸡蛋。"}, {"text": "顿", "is_correct": false, "explanation": "dùn（顿）比 duàn 少了 a 音，声调相同，意思是一顿、停顿。"}], "explanations": {"断": "断（duàn）指长形的东西分成几段，是本题的目标词。", "算": "suàn（算）与 duàn 声母不同（s/d），声调相同，意思是计算。", "窜": "cuàn（窜）与 duàn 声母不同（c/d），声调相同，意思是逃窜、乱跑。", "蛋": "dàn（蛋）比 duàn 少了 u 音，声调相同，意思是鸡蛋。", "顿": "dùn（顿）比 duàn 少了 a 音，声调相同，意思是一顿、停顿。"}, "sentence_index": null, "correct_answer": "断"}, "level_3": {"options": [{"text": "断", "is_correct": true, "explanation": "断成：铁链被拉断后分成几段，符合「那条铁链断成了几段」的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指进食，不能用于铁链。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的对象是液体，不说「喝成几段」。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：「戴」用于帽子、眼镜等，不说「戴成几段」。"}], "explanations": {"断": "断成：铁链被拉断后分成几段，符合「那条铁链断成了几段」的语境。", "吃": "语义：「吃」指进食，不能用于铁链。", "喝": "搭配：「喝」的对象是液体，不说「喝成几段」。", "戴": "搭配：「戴」用于帽子、眼镜等，不说「戴成几段」。"}, "sentence_index": 6, "correct_answer": "断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨师断了一块猪肉。", "explanation": "这里应该用〈切〉。切肉要说切，断用于绳、线等长形的东西，不用于肉。"}, {"text": "他断了几块石头。", "explanation": "这里应该用〈搬〉。搬石头要说搬，断指长形的东西分成几段或联系中断，不用于搬运石头。"}, {"text": "他断了一杯水。", "explanation": "这里应该用〈倒〉。倒水要说倒，断用于长形的东西分成几段，不用于水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根竹子断了成三段。", "corrected_sentence": "这根竹子断成了三段。", "error_description": "「断成」是结果补语结构，「了」应放在「成」之后，说「断成了三段」，不能插在「断」和「成」之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那根粗铁链被断成了几段。", "corrected_sentence": "那根粗铁链断成了几段。", "error_description": "「断成」表示铁链自己断开，是不及物结构，不用「被」字句。应说「铁链断成了几段」，不说「被断成」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
