INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93186, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93186, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "科举时代会试的第一名。", "primary_collocate": null, "pronunciation": "huì yuán", "ipa": "xuei˥˩ yɛn˧˥", "syllable_count": 2, "sentences": [{"text": "科举时代，会试第一名叫会元。", "target_word": "会元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考完会试，人们都叫他会元。", "target_word": "会元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明朝有一位会元，后来当了宰相。", "target_word": "会元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会元再考殿试，还可能成为状元。", "target_word": "会元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他中了会元，全家都很高兴。", "target_word": "会元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会试，会元是一个南方人。", "target_word": "会元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会元是会试的第一名，不是殿试的第一名。", "target_word": "会元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那年的会元来自江苏。", "target_word": "会元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先中了会元，后来又中了状元。", "target_word": "会元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，这位会元从小就爱读书。", "target_word": "会元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "會元", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "科举时代会试的第一名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de94bd89-19e3-4337-868c-ae9af5a910e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会元", "is_correct": true, "explanation": "会元：科举时代会试的第一名，与句意相符。"}, {"text": "探花", "is_correct": false, "explanation": "语义：探花是殿试第三名，与“会试第一名”不符。"}, {"text": "举人", "is_correct": false, "explanation": "语义：举人是乡试中式的人，不是会试第一名。"}, {"text": "考场", "is_correct": false, "explanation": "搭配：“叫”后要接人的称呼，不能说“叫考场”。"}], "explanations": {"会元": "会元：科举时代会试的第一名，与句意相符。", "探花": "语义：探花是殿试第三名，与“会试第一名”不符。", "举人": "语义：举人是乡试中式的人，不是会试第一名。", "考场": "搭配：“叫”后要接人的称呼，不能说“叫考场”。"}, "sentence_index": 0, "correct_answer": "会元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我见过一条会元。", "explanation": "这里应该用〈位〉。会元指人，不能用“条”，“条”多用于细长的东西。"}, {"text": "他是今年的高考会元。", "explanation": "这里应该用〈状元〉。现代高考第一名称状元，会元指古代会试的第一名。"}, {"text": "他在辩论赛里拿了会元。", "explanation": "这里应该用〈冠军〉。会元专指古代会试的第一名，现代比赛的第一名要说“冠军”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会元", "is_correct": true, "explanation": "会元：会试的第一名，与句中两个限定相符。"}, {"text": "状元", "is_correct": false, "explanation": "语义：状元是殿试的第一名，与“不是殿试的第一名”矛盾。"}, {"text": "榜眼", "is_correct": false, "explanation": "语义：榜眼是殿试的第二名，与“会试的第一名”不符。"}, {"text": "考生", "is_correct": false, "explanation": "搭配：“考生”指参加考试的人，不是名次的称号，不能作“是……第一名”的主语。"}], "explanations": {"会元": "会元：会试的第一名，与句中两个限定相符。", "状元": "语义：状元是殿试的第一名，与“不是殿试的第一名”矛盾。", "榜眼": "语义：榜眼是殿试的第二名，与“会试的第一名”不符。", "考生": "搭配：“考生”指参加考试的人，不是名次的称号，不能作“是……第一名”的主语。"}, "sentence_index": 6, "correct_answer": "会元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她是我们学校的会元。", "explanation": "这里应该用〈团员〉。团员指团组织的成员，会元专指古代会试的第一名。"}, {"text": "他是班里的会元。", "explanation": "这里应该用〈尖子〉。尖子指某方面特别出色的人，会元专指古代会试的第一名。"}, {"text": "他是乐团的会元。", "explanation": "这里应该用〈首席〉。首席指乐团中的领奏者，会元不能用于乐团的职位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "清朝有一只会元，后来做了翰林。", "corrected_sentence": "清朝有一位会元，后来做了翰林。", "error_description": "错误：“一只会元”。正确：“一位会元”。会元指人，量词用“位”，“只”多用于动物或物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生说，他将来一定能中了会元。", "corrected_sentence": "先生说，他将来一定能中会元。", "error_description": "错误：“中了会元”。正确：“中会元”。将来的事尚未发生，不能用“了”表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
