INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93187, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "气氛是在一个地方，大家感觉到的样子。", "primary_collocate": null, "pronunciation": "qì fēn", "ipa": "tɕʰi˥˩ fən˥", "syllable_count": 2, "sentences": [{"text": "教室里的气氛很轻松。", "target_word": "气氛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "开会的时候，大家都不说话，气氛有点紧张。", "target_word": "气氛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们一起吃饭，气氛特别热闹。", "target_word": "气氛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他讲了一个笑话，办公室的气氛一下子好了。", "target_word": "气氛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的气氛很好，同事们互相帮助。", "target_word": "气氛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个人吵架以后，家里的气氛很沉闷。", "target_word": "气氛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师笑着走进来，课堂气氛马上轻松了。", "target_word": "气氛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队输了比赛，更衣室里的气氛很低沉。", "target_word": "气氛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想让聚会的气氛更友好一点。", "target_word": "气氛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一进门，就感觉到气氛不对。", "target_word": "气氛", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种气氛", "label": "量词"}, {"form": "氣氛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一群人在某处共同感受到的整体状态，如轻松、紧张", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2534af2a-1516-45ed-a22b-20f025827a87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93187, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "气氛", "is_correct": true, "explanation": "气氛：某个场合或一群人共同感受到的整体状态。"}, {"text": "七分", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，意思是十分之七。"}, {"text": "七份", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，fèn（第四声）与 fēn（第一声）声调也不同，意思是七份。"}, {"text": "计分", "is_correct": false, "explanation": "jì 与 qì 声母不同，意思是计算分数。"}, {"text": "气愤", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，意思是生气、愤怒。"}], "explanations": {"气氛": "气氛：某个场合或一群人共同感受到的整体状态。", "七分": "qī（第一声）与 qì（第四声）声调不同，意思是十分之七。", "七份": "qī（第一声）与 qì（第四声）声调不同，fèn（第四声）与 fēn（第一声）声调也不同，意思是七份。", "计分": "jì 与 qì 声母不同，意思是计算分数。", "气愤": "fèn（第四声）与 fēn（第一声）声调不同，意思是生气、愤怒。"}, "sentence_index": null, "correct_answer": "气氛"}, "level_3": {"options": [{"text": "气氛", "is_correct": true, "explanation": "气氛：教室里大家感受到的状态，可以说“很轻松”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不能“很轻松”，与句子的意思不合。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“轻松”一般形容气氛、心情，不说“温度很轻松”。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是物体，不能是“很轻松”的。"}], "explanations": {"气氛": "气氛：教室里大家感受到的状态，可以说“很轻松”。", "桌子": "语义：桌子是物品，不能“很轻松”，与句子的意思不合。", "温度": "搭配：“轻松”一般形容气氛、心情，不说“温度很轻松”。", "黑板": "语义：黑板是物体，不能是“很轻松”的。"}, "sentence_index": 0, "correct_answer": "气氛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天的气氛很好。", "explanation": "这里应该用〈心情〉。气氛指某个场合或一群人的整体感受，个人的情绪要用心情。"}, {"text": "教室里有一张热闹的气氛。", "explanation": "这里应该用〈种〉。气氛是抽象的感受，不能用“张”计量，“张”用于纸张、桌子等平面物品。"}, {"text": "他脸上的气氛很紧张。", "explanation": "这里应该用〈表情〉。气氛指场合的整体感受，描写脸上的神情要用表情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "气氛", "is_correct": true, "explanation": "气氛：课堂里大家共同感受到的状态，可以“马上轻松了”。"}, {"text": "桌椅", "is_correct": false, "explanation": "语义：桌椅是物品，不能“马上轻松了”，与句意矛盾。"}, {"text": "分数", "is_correct": false, "explanation": "搭配：“轻松”不用来形容分数，“课堂分数轻松了”不合适。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯是物件，不会“轻松”，与“课堂”后的描述不相合。"}], "explanations": {"气氛": "气氛：课堂里大家共同感受到的状态，可以“马上轻松了”。", "桌椅": "语义：桌椅是物品，不能“马上轻松了”，与句意矛盾。", "分数": "搭配：“轻松”不用来形容分数，“课堂分数轻松了”不合适。", "灯": "语义：灯是物件，不会“轻松”，与“课堂”后的描述不相合。"}, "sentence_index": 6, "correct_answer": "气氛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间的气氛有三米高。", "explanation": "这里应该用〈高度〉。气氛是人群或场合的感受，不能说有多高，表示高矮要说高度。"}, {"text": "这个药的气氛很苦。", "explanation": "这里应该用〈味道〉。气氛是感受，不能用来形容苦味。"}, {"text": "屋子里有一台气氛。", "explanation": "这里应该用〈种〉。台用于机器等实体物件，气氛是抽象感受，不能用“台”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议室里有一只热烈的气氛。", "corrected_sentence": "会议室里有一种热烈的气氛。", "error_description": "“气氛”是抽象的感受，量词应用“种”。这里错在量词“只”，“只”多用于动物或成对的物品，不能用来数气氛，应改为“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个房间里充满了轻松地气氛。", "corrected_sentence": "这个房间里充满了轻松的气氛。", "error_description": "“轻松”修饰名词“气氛”，应用结构助词“的”。这里错在“地”，“地”一般用于修饰动词，应改为“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
