INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93188, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个场合中给人的特殊的感受或情调。", "primary_collocate": null, "pronunciation": "qì fēn", "ipa": "tɕʰi˥˩ fən˥", "syllable_count": 2, "sentences": [{"text": "节日的气氛越来越浓了。", "target_word": "气氛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "餐厅里的灯光很柔和，很有浪漫的气氛。", "target_word": "气氛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "街上挂满红灯笼，充满了过年的气氛。", "target_word": "气氛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼上的音乐让现场气氛很温馨。", "target_word": "气氛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "圣诞节快到了，商店里都有节日气氛。", "target_word": "气氛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛现场的气氛很热烈，观众都站起来了。", "target_word": "气氛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡馆有种安静的气氛，适合看书。", "target_word": "气氛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯一关，蜡烛亮了，生日的气氛一下子浓了起来。", "target_word": "气氛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古老的小城有一种特别的气氛。", "target_word": "气氛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用鲜花和音乐布置出了喜庆的气氛。", "target_word": "气氛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种气氛", "label": "量词"}, {"form": "氣氛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "节日、婚礼、餐厅等特定场合带给人的特别情调", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2534af2a-1516-45ed-a22b-20f025827a87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93188, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "气氛", "is_correct": true, "explanation": "气氛：某个场合给人的特殊的感受或情调。"}, {"text": "七分", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，意思是十分之七。"}, {"text": "七份", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，fèn（第四声）与 fēn（第一声）声调也不同，意思是七份。"}, {"text": "计分", "is_correct": false, "explanation": "jì 与 qì 声母不同，意思是计算分数。"}, {"text": "气愤", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，意思是生气、愤怒。"}], "explanations": {"气氛": "气氛：某个场合给人的特殊的感受或情调。", "七分": "qī（第一声）与 qì（第四声）声调不同，意思是十分之七。", "七份": "qī（第一声）与 qì（第四声）声调不同，fèn（第四声）与 fēn（第一声）声调也不同，意思是七份。", "计分": "jì 与 qì 声母不同，意思是计算分数。", "气愤": "fèn（第四声）与 fēn（第一声）声调不同，意思是生气、愤怒。"}, "sentence_index": null, "correct_answer": "气氛"}, "level_3": {"options": [{"text": "气氛", "is_correct": true, "explanation": "气氛：节日里带来的情调，可以“越来越浓”。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“浓”不用来形容雨，不说“雨越来越浓”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能“越来越浓”，与句意矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能“越来越浓”，与句意矛盾。"}], "explanations": {"气氛": "气氛：节日里带来的情调，可以“越来越浓”。", "雨": "搭配：“浓”不用来形容雨，不说“雨越来越浓”。", "房子": "语义：房子不能“越来越浓”，与句意矛盾。", "桌子": "语义：桌子不能“越来越浓”，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "气氛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新郎今天的气氛很好。", "explanation": "这里应该用〈心情〉。气氛指场合的整体感受，个人的心情要用心情。"}, {"text": "婚礼现场有一根气氛。", "explanation": "这里应该用〈种〉。气氛是抽象感受，不能用“根”计量，“根”用于细长的物体。"}, {"text": "音乐的气氛很大。", "explanation": "这里应该用〈音量〉。气氛不能用“大”来形容，声音的大小要说音量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "气氛", "is_correct": true, "explanation": "气氛：咖啡馆里给人的安静情调，适合看书。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“安静”形容声音或环境，不说“安静的温度”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能是“安静”的，与句意不合。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮品，不能说“安静的咖啡”，与“适合看书”的意思不符。"}], "explanations": {"气氛": "气氛：咖啡馆里给人的安静情调，适合看书。", "温度": "搭配：“安静”形容声音或环境，不说“安静的温度”。", "价格": "语义：价格不能是“安静”的，与句意不合。", "咖啡": "语义：咖啡是饮品，不能说“安静的咖啡”，与“适合看书”的意思不符。"}, "sentence_index": 6, "correct_answer": "气氛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片田野的气氛很便宜。", "explanation": "这里应该用〈价格〉。气氛是场合的感受，不能用“便宜”来说，商品的价钱要说价格。"}, {"text": "这碗汤的气氛很咸。", "explanation": "这里应该用〈味道〉。气氛是感受，不能用来形容咸味。"}, {"text": "这首歌的气氛很响亮。", "explanation": "这里应该用〈声音〉。气氛不能用“响亮”来形容，声音响亮要说声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街上到处都弥漫着一颗喜庆的气氛。", "corrected_sentence": "街上到处都弥漫着一种喜庆的气氛。", "error_description": "“气氛”是抽象的感受，量词应用“种”。这里错在量词“颗”，“颗”用于粒状的小东西，不能用来数气氛，应改为“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春节快到了，街上的气氛越来越厚了。", "corrected_sentence": "春节快到了，街上的气氛越来越浓了。", "error_description": "形容节日“气氛”加深，要说“浓”（或“浓厚”）。这里错在单用“厚”，“厚”形容物体的厚度，不能单独形容气氛，应改为“浓”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93189, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "产生", "is_correct": true, "explanation": "正确：“产生”与“消除”相对，指使事物出现，意思正好相反。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系：“游泳”是体育活动，与“消除”不构成反义。"}, {"text": "学习", "is_correct": false, "explanation": "无反义关系：“学习”指获取知识，与去掉不好事物的“消除”不构成反义。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：“散步”是一种休闲活动，与“消除”不构成反义。"}], "correct_answer": "产生", "explanations": {"产生": "正确：“产生”与“消除”相对，指使事物出现，意思正好相反。", "游泳": "无反义关系：“游泳”是体育活动，与“消除”不构成反义。", "学习": "无反义关系：“学习”指获取知识，与去掉不好事物的“消除”不构成反义。", "散步": "无反义关系：“散步”是一种休闲活动，与“消除”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93189, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "产生", "is_correct": true, "explanation": "正确：“产生”与“消除”相对，指使事物出现，意思正好相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：“唱歌”是文娱活动，与“消除”不构成反义。"}, {"text": "跳舞", "is_correct": false, "explanation": "无反义关系：“跳舞”是身体活动，与“消除”不构成反义。"}, {"text": "呼吸", "is_correct": false, "explanation": "无反义关系：“呼吸”是生理动作，与“消除”不构成反义。"}], "correct_answer": "产生", "explanations": {"产生": "正确：“产生”与“消除”相对，指使事物出现，意思正好相反。", "唱歌": "无反义关系：“唱歌”是文娱活动，与“消除”不构成反义。", "跳舞": "无反义关系：“跳舞”是身体活动，与“消除”不构成反义。", "呼吸": "无反义关系：“呼吸”是生理动作，与“消除”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93189, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "消除是把不好的东西去掉。", "primary_collocate": null, "pronunciation": "xiāo chú", "ipa": "ɕjɑʊ̯˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "洗个热水澡能消除一天的疲劳。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们谈了很久，终于消除了误会。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药水可以消除衣服上的污渍。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话消除了我心里的紧张。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开窗户通风，可以消除房间里的异味。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说了几句，消除了大家的顾虑。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们及时消除了路上的危险。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多听听音乐，能消除压力。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的解释消除了病人的疑虑。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行帮我消除了心里的烦恼。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "消除了", "label": "完成体"}, {"form": "消除过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把不好的东西去掉：消除疲劳、误会、紧张", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '323a0647-864a-43f9-9cfa-c61cbd356ead') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93189, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消除", "is_correct": true, "explanation": "正确：“消除”表示去掉疲劳，与洗澡能解乏的语境相符。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”是变多，与洗澡后疲劳减少的意思相反。"}, {"text": "散发", "is_correct": false, "explanation": "搭配：“散发”多用于气味、热量，不能说散发疲劳。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”的对象是乐趣、生活，不能说享受疲劳。"}], "explanations": {"消除": "正确：“消除”表示去掉疲劳，与洗澡能解乏的语境相符。", "增加": "语义：“增加”是变多，与洗澡后疲劳减少的意思相反。", "散发": "搭配：“散发”多用于气味、热量，不能说散发疲劳。", "享受": "搭配：“享受”的对象是乐趣、生活，不能说享受疲劳。"}, "sentence_index": 0, "correct_answer": "消除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们终于消除了这个节日。", "explanation": "这里应该用〈过〉。节日要用“过”；消除用于去掉误会、紧张这类不好的情况。"}, {"text": "他们终于消除了桌上的书。", "explanation": "这里应该用〈清理〉。清理用于把桌上的杂物收拾干净；消除用于去掉误会、紧张等不好的情况，书不是不好的东西，不能用消除。"}, {"text": "消防员消除了大火。", "explanation": "这里应该用〈扑灭〉。大火要用扑灭，消除用于误会、紧张、隐患这类抽象的不好事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93189, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消除", "is_correct": true, "explanation": "正确：“消除”与“及时”搭配，表示及时去掉路上的危险。"}, {"text": "制造", "is_correct": false, "explanation": "语义：“制造”是造出来，与“及时”以及工人处理危险的意图相反。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是风景、作品，不能说欣赏危险。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”的对象是人或事物的优点，不能说赞美危险。"}], "explanations": {"消除": "正确：“消除”与“及时”搭配，表示及时去掉路上的危险。", "制造": "语义：“制造”是造出来，与“及时”以及工人处理危险的意图相反。", "欣赏": "搭配：“欣赏”的对象是风景、作品，不能说欣赏危险。", "赞美": "搭配：“赞美”的对象是人或事物的优点，不能说赞美危险。"}, "sentence_index": 6, "correct_answer": "消除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司消除了那个员工。", "explanation": "这里应该用〈开除〉。消除用于不好的事物，不能用于人；公司辞退员工要用开除。"}, {"text": "我们消除了那个新花瓶。", "explanation": "这里应该用〈搬走〉。消除只用于去掉误会、隐患等不好的情况，新花瓶不是不好的东西，要说搬走。"}, {"text": "他们消除了明天的会议。", "explanation": "这里应该用〈取消〉。会议、计划要用取消，消除只用于去掉不好的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们终于消除了过那次误会。", "corrected_sentence": "我们终于消除了那次误会。", "error_description": "错误在于“消除了过”同时用了“了”和“过”，两者不能连用；这里说的是终于完成的事，应删去“过”，说“终于消除了那次误会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把路上的危险消除。", "corrected_sentence": "工人们把路上的危险消除了。", "error_description": "错误在于“把”字句中动词“消除”后缺少“了”等成分，句子不完整；应为“把路上的危险消除了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93190, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "产生", "is_correct": true, "explanation": "正确：“产生”与“消除”相对，指使事物出现，意思正好相反。"}, {"text": "跳舞", "is_correct": false, "explanation": "无反义关系：“跳舞”是身体活动，与“消除”不构成反义。"}, {"text": "呼吸", "is_correct": false, "explanation": "无反义关系：“呼吸”是生理动作，与“消除”不构成反义。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系：“游泳”是体育活动，与“消除”不构成反义。"}], "correct_answer": "产生", "explanations": {"产生": "正确：“产生”与“消除”相对，指使事物出现，意思正好相反。", "跳舞": "无反义关系：“跳舞”是身体活动，与“消除”不构成反义。", "呼吸": "无反义关系：“呼吸”是生理动作，与“消除”不构成反义。", "游泳": "无反义关系：“游泳”是体育活动，与“消除”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93190, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "产生", "is_correct": true, "explanation": "正确：“产生”与“消除”相对，指使事物出现，意思正好相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：“唱歌”是文娱活动，与“消除”不构成反义。"}, {"text": "学习", "is_correct": false, "explanation": "无反义关系：“学习”指获取知识，与“消除”不构成反义。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：“散步”是一种休闲活动，与“消除”不构成反义。"}], "correct_answer": "产生", "explanations": {"产生": "正确：“产生”与“消除”相对，指使事物出现，意思正好相反。", "唱歌": "无反义关系：“唱歌”是文娱活动，与“消除”不构成反义。", "学习": "无反义关系：“学习”指获取知识，与“消除”不构成反义。", "散步": "无反义关系：“散步”是一种休闲活动，与“消除”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93190, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使不好的事物不再存在。", "primary_collocate": null, "pronunciation": "xiāo chú", "ipa": "ɕjɑʊ̯˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "政府想消除城市里的污染。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要消除对别人的偏见。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这副耳机可以消除外面的噪音。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校一直在努力消除安全隐患。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友的陪伴消除了我的孤独。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家想办法消除贫富差距。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件可以消除照片里的杂物。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "慢慢地，他消除了对水的恐惧。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用新的方法消除了脸上的痘印。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打扫干净，消除了厨房里的细菌。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "消除了", "label": "完成体"}, {"form": "消除过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "使不好的事物不再存在：消除污染、偏见、隐患", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '323a0647-864a-43f9-9cfa-c61cbd356ead') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消除", "is_correct": true, "explanation": "正确：“消除”表示使污染不再存在，符合政府想治理污染的意图。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”使污染变多，与政府想治理污染的意图相反。"}, {"text": "散布", "is_correct": false, "explanation": "搭配：“散布”多用于消息、谣言，不能和“污染”搭配。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是风景、艺术作品，不能说欣赏污染。"}], "explanations": {"消除": "正确：“消除”表示使污染不再存在，符合政府想治理污染的意图。", "增加": "语义：“增加”使污染变多，与政府想治理污染的意图相反。", "散布": "搭配：“散布”多用于消息、谣言，不能和“污染”搭配。", "欣赏": "搭配：“欣赏”的对象是风景、艺术作品，不能说欣赏污染。"}, "sentence_index": 0, "correct_answer": "消除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们消除了这项纪录。", "explanation": "这里应该用〈打破〉。纪录要用打破，消除只用于去掉不好的事物。"}, {"text": "政府消除了空气质量。", "explanation": "这里应该用〈改善〉。空气质量要用改善，消除不能用于质量这类抽象的好坏状况。"}, {"text": "我终于消除了这本书。", "explanation": "这里应该用〈看完〉。读书要说看完；书不是不好的东西，不能用消除。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消除", "is_correct": true, "explanation": "正确：“消除”表示去掉照片里的杂物，符合软件的用途。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：“拍摄”的对象是人或景物，不能说拍摄照片里已有的杂物。"}, {"text": "制作", "is_correct": false, "explanation": "语义：“制作”是做出新东西，照片里的杂物已经存在，与“消除”的语境不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说唱杂物。"}], "explanations": {"消除": "正确：“消除”表示去掉照片里的杂物，符合软件的用途。", "拍摄": "搭配：“拍摄”的对象是人或景物，不能说拍摄照片里已有的杂物。", "制作": "语义：“制作”是做出新东西，照片里的杂物已经存在，与“消除”的语境不符。", "唱": "搭配：“唱”的对象是歌曲，不能说唱杂物。"}, "sentence_index": 6, "correct_answer": "消除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察消除了那起案件。", "explanation": "这里应该用〈侦破〉。案件要用侦破；消除用于去掉不好的事物，不用于办案。"}, {"text": "他消除了那支蜡烛。", "explanation": "这里应该用〈熄灭〉。蜡烛、火要用熄灭，消除用于去掉不好的事物。"}, {"text": "工人消除了那座桥。", "explanation": "这里应该用〈拆除〉。拆除用于把桥梁、房屋等建筑拆掉；消除用于去掉误会、隐患等不好的情况，不用于建筑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府把城市里的污染消除。", "corrected_sentence": "政府把城市里的污染消除了。", "error_description": "错误在于“把”字句中动词“消除”后缺少“了”等成分，句子不完整；应为“把城市里的污染消除了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们已经消除了过厨房里的细菌。", "corrected_sentence": "他们已经消除过厨房里的细菌。", "error_description": "错误在于“消除了过”同时用了完成体“了”和经历体“过”，两者不能并用；应为“已经消除过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
