INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93192, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "没有人。", "primary_collocate": null, "pronunciation": "wú rén", "ipa": "u˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "教室里无人。", "target_word": "无人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜里街上无人。", "target_word": "无人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "门口无人看守。", "target_word": "无人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我敲了很久，屋里无人回答。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末的办公室里无人。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山路很长，路上无人经过。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个时候店里无人，很安静。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喊了几声，四周无人。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车站里无人等车。", "target_word": "无人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电话响了很久，家里无人接。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "无人：没有人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8d98bf-ca56-4497-b80d-a8800a5dfbfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93192, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无人", "is_correct": true, "explanation": "正确：无人（wú rén）指没有人，是这个义项的本义。"}, {"text": "五人", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是五个人。"}, {"text": "误人", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是耽误别人。"}, {"text": "武人", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是习武的人。"}], "explanations": {"无人": "正确：无人（wú rén）指没有人，是这个义项的本义。", "五人": "wǔ（第三声）与 wú（第二声）声调不同，意思是五个人。", "误人": "wù（第四声）与 wú（第二声）声调不同，意思是耽误别人。", "武人": "wǔ（第三声）与 wú（第二声）声调不同，意思是习武的人。"}, "sentence_index": null, "correct_answer": "无人"}, "level_3": {"options": [{"text": "无效", "is_correct": false, "explanation": "语义：“无效”指没有效力，不能用来描述教室的状况。"}, {"text": "无人", "is_correct": true, "explanation": "正确：“无人”说教室里没有人，符合“教室里”的场所语境。"}, {"text": "无价", "is_correct": false, "explanation": "搭配：“无价”多用于珍贵的东西，不能用来形容教室这样的地点。"}, {"text": "无限", "is_correct": false, "explanation": "语义：“无限”指没有限度，与“教室里”的场所语境不合。"}], "explanations": {"无效": "语义：“无效”指没有效力，不能用来描述教室的状况。", "无人": "正确：“无人”说教室里没有人，符合“教室里”的场所语境。", "无价": "搭配：“无价”多用于珍贵的东西，不能用来形容教室这样的地点。", "无限": "语义：“无限”指没有限度，与“教室里”的场所语境不合。"}, "sentence_index": 0, "correct_answer": "无人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老师是无人的。", "explanation": "这里应该用〈孤单〉。“无人”指没有人在场，或设备无人操作，不能用来形容人；形容一个人没有陪伴要用“孤单”。"}, {"text": "这只猫是无人的。", "explanation": "这里应该用〈无主〉。“无人”指没有人在场，不指动物没有主人；没有主人要说“无主”。"}, {"text": "这个孩子是无人的。", "explanation": "这里应该用〈孤儿〉。“无人”不能用来说明人的身份；没有父母的孩子要说“孤儿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喧闹", "is_correct": false, "explanation": "语义：“喧闹”指声音很大，与后面的“很安静”矛盾。"}, {"text": "无人", "is_correct": true, "explanation": "正确：“无人”说店里没有人，与“很安静”一致。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指人多、有声音，与“很安静”互相矛盾。"}, {"text": "拥挤", "is_correct": false, "explanation": "搭配：“拥挤”说人多，不能与“很安静”同时描述同一个地方。"}], "explanations": {"喧闹": "语义：“喧闹”指声音很大，与后面的“很安静”矛盾。", "无人": "正确：“无人”说店里没有人，与“很安静”一致。", "热闹": "语义：“热闹”指人多、有声音，与“很安静”互相矛盾。", "拥挤": "搭配：“拥挤”说人多，不能与“很安静”同时描述同一个地方。"}, "sentence_index": 6, "correct_answer": "无人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是家里无人的孩子，很懂事。", "explanation": "这里应该用〈独生子〉。“无人”指没有人在场，不能用来说明家庭关系；只有一个孩子要说“独生子”。"}, {"text": "这个村子里无人的老人很多。", "explanation": "这里应该用〈孤寡〉。“无人”指没有人在场，不能说人没有亲人；无人照顾的老人要说“孤寡老人”。"}, {"text": "这把伞是无人的，在门口放了一个星期。", "explanation": "这里应该用〈无主〉。“无人”指没有人或没有人做某事，不能说东西没有主人；没有主人的东西要说“无主”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
