INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93193, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "登陆是从船上走到陆地上。", "primary_collocate": null, "pronunciation": "dēng lù", "ipa": "tɤŋ˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "船靠岸了，客人开始登陆。", "target_word": "登陆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们从小船登陆海岛。", "target_word": "登陆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "探险队终于在小岛上登陆了。", "target_word": "登陆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海浪太大，船员不能登陆。", "target_word": "登陆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们乘船登陆了这座海岛。", "target_word": "登陆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边登陆后，先找水喝。", "target_word": "登陆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登陆前，船长让大家排好队。", "target_word": "登陆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船停了，第一批游客已经登陆了。", "target_word": "登陆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘小船想在北边的海滩登陆。", "target_word": "登陆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们等天亮再登陆海岛。", "target_word": "登陆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "登陆了", "label": "体标"}, {"form": "登陆过", "label": "体标"}, {"form": "登陆舰", "label": "复合"}, {"form": "登陸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从船上走到陆地上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb942baf-2f2e-4d1b-8c28-1bbea51ff9ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93193, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "登陆", "is_correct": true, "explanation": "正确：船靠岸后客人上岸，符合“登陆”从船上走到陆地的意思。"}, {"text": "起航", "is_correct": false, "explanation": "语义：“起航”指船离开港口出发，与“船靠岸了”的情境相反。"}, {"text": "登机", "is_correct": false, "explanation": "搭配：“登机”指乘客上飞机，不能用于船只靠岸的情境。"}, {"text": "出站", "is_correct": false, "explanation": "搭配：“出站”用于车站，与码头和船只不搭配。"}], "explanations": {"登陆": "正确：船靠岸后客人上岸，符合“登陆”从船上走到陆地的意思。", "起航": "语义：“起航”指船离开港口出发，与“船靠岸了”的情境相反。", "登机": "搭配：“登机”指乘客上飞机，不能用于船只靠岸的情境。", "出站": "搭配：“出站”用于车站，与码头和船只不搭配。"}, "sentence_index": 0, "correct_answer": "登陆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "乘客们在车站登陆，各自回家。", "explanation": "这里应该用〈下车〉。登陆指从船上到陆地，乘客在车站下车要说下车。"}, {"text": "他推开门，登陆了房间。", "explanation": "这里应该用〈走进〉。登陆只用于从水上上岸，不能用于进入房间。"}, {"text": "小鸟飞到树上，登陆了树枝。", "explanation": "这里应该用〈停在〉。登陆只指人或船从水面上岸，鸟落在树枝上不能说登陆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93193, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "登陆", "is_correct": true, "explanation": "正确：船长在登陆前让大家排队，符合“登陆”从船上上岸的意思。"}, {"text": "出院", "is_correct": false, "explanation": "语义：“出院”指病人离开医院，与船长指挥大家排队的语境不符。"}, {"text": "挂号", "is_correct": false, "explanation": "搭配：“挂号”是在医院办理的手续，不能与船长指挥排队搭配。"}, {"text": "退学", "is_correct": false, "explanation": "语义：“退学”指学生离开学校，与船长的指令无关。"}], "explanations": {"登陆": "正确：船长在登陆前让大家排队，符合“登陆”从船上上岸的意思。", "出院": "语义：“出院”指病人离开医院，与船长指挥大家排队的语境不符。", "挂号": "搭配：“挂号”是在医院办理的手续，不能与船长指挥排队搭配。", "退学": "语义：“退学”指学生离开学校，与船长的指令无关。"}, "sentence_index": 6, "correct_answer": "登陆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下课以后，学生们登陆了宿舍。", "explanation": "这里应该用〈回到〉。登陆只指从船上到陆地，不能用于回到宿舍。"}, {"text": "孩子终于登陆了，大家都松了口气。", "explanation": "这里应该用〈入睡〉。登陆不能用于形容孩子睡着。"}, {"text": "他们穿过了森林，登陆了村子。", "explanation": "这里应该用〈来到〉。登陆不能用于在陆地上穿越森林后到达村子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93193, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "船员没有登陆了。", "corrected_sentence": "船员没有登陆。", "error_description": "错误形式：“没有登陆了”。正确形式：“没有登陆”。原因：用“没有”否定已发生或未发生的动作时，句末不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93193, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天他们登陆过海岛。", "corrected_sentence": "明天他们登陆海岛。", "error_description": "错误形式：“登陆过”。正确形式：“登陆”。原因：“过”表示过去的经历，不能和表示将来的“明天”一起用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
