INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93195, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "秘书长是一个大团体里管事的重要的人。", "primary_collocate": null, "pronunciation": "mì shū zhǎng", "ipa": "mi˥˩ ʂu˥ ʈʂɑŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "秘书长今天要主持大会。", "target_word": "秘书长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的秘书长是一位老先生。", "target_word": "秘书长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了十年秘书长。", "target_word": "秘书长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秘书长请大家先坐下。", "target_word": "秘书长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，秘书长给每个人发了材料。", "target_word": "秘书长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个协会的秘书长工作很忙。", "target_word": "秘书长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想去见一下秘书长。", "target_word": "秘书长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的秘书长对大家都很客气。", "target_word": "秘书长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秘书长说，明天下午开会。", "target_word": "秘书长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秘书长在台上讲了十分钟话。", "target_word": "秘书长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副秘书长", "label": "复合"}, {"form": "秘書長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大团体里管事的重要的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb942baf-2f2e-4d1b-8c28-1bbea51ff9ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93195, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秘书长", "is_correct": true, "explanation": "正确：秘书长是大团体里管事的重要人物，能够主持大会。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子是物品，不能主持大会。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物件，不能主持大会。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“主持大会”的主语必须是人，“花”不能主持大会。"}], "explanations": {"秘书长": "正确：秘书长是大团体里管事的重要人物，能够主持大会。", "杯子": "语义：杯子是物品，不能主持大会。", "窗户": "语义：窗户是物件，不能主持大会。", "花": "搭配：“主持大会”的主语必须是人，“花”不能主持大会。"}, "sentence_index": 0, "correct_answer": "秘书长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我请了一位私人秘书长帮我整理资料。", "explanation": "这里应该用〈助理〉。秘书长指大团体里管事的重要负责人，给个人做事的私人助理不能称为秘书长。"}, {"text": "我们班的秘书长每天负责收作业。", "explanation": "这里应该用〈班长〉。秘书长指大团体里管事的重要负责人，班级的负责人应说班长。"}, {"text": "我们乐队的秘书长每天带领大家排练。", "explanation": "这里应该用〈领队〉。秘书长负责大团体的日常事务，不带队排练；带队的人应说领队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93195, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秘书长", "is_correct": true, "explanation": "正确：秘书长是人，可以作为“去见”的对象。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能作为“去见”的对象。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会和人见面，句子说不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“去见一下”后面要接人，“空气”不能作为见面的对象。"}], "explanations": {"秘书长": "正确：秘书长是人，可以作为“去见”的对象。", "桌子": "语义：桌子是家具，不能作为“去见”的对象。", "石头": "语义：石头不会和人见面，句子说不通。", "空气": "搭配：“去见一下”后面要接人，“空气”不能作为见面的对象。"}, "sentence_index": 6, "correct_answer": "秘书长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家小店的秘书长每天很早开门。", "explanation": "这里应该用〈店长〉。秘书长指大团体里管事的重要负责人，小店的负责人不这样称呼。"}, {"text": "我们村的秘书长很热心，常帮大家解决问题。", "explanation": "这里应该用〈村长〉。秘书长用于大型组织，村里的负责人应说村长。"}, {"text": "这次演习由部队秘书长指挥。", "explanation": "这里应该用〈司令〉。秘书长负责大团体的日常事务，不指挥部队作战；指挥部队的人应说司令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93195, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们选了一只新的秘书长。", "corrected_sentence": "我们选了一位新的秘书长。", "error_description": "量词错误：“秘书长”指人，应用量词“位”，不能用“只”。应改为“一位新的秘书长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93195, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她秘书长。", "corrected_sentence": "她是秘书长。", "error_description": "缺少系词：名词作谓语时要加“是”，应说“她是秘书长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7107b31-8fc7-4fd6-a9d1-020d059188d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
