INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93197, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "按月是每个月都这样做一次。", "primary_collocate": null, "pronunciation": "àn yuè", "ipa": "an˥˩ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "我们按月交房租。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司按月给工人发钱。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按月把钱寄给妈妈。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杂志按月送到家里。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校按月让学生检查身体。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子的钱可以按月还。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的水费是按月交的。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸按月给我一百块钱。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆按月买新书。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师按月给我们开一次会。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每个月做一次，放在动词前面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e91c0d-146f-4be2-97f8-2129581fbe82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93197, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每天", "is_correct": false, "explanation": "语义：每天指按日计算，与按月的周期付款相冲突。"}, {"text": "按月", "is_correct": true, "explanation": "按月表示每个月一次，与定期交房租相合，是正确答案。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔表示不固定的少数次，与定期交房租不合。"}, {"text": "逐年", "is_correct": false, "explanation": "搭配：逐年多用于说变化、增长，不与“交房租”搭配。"}], "explanations": {"每天": "语义：每天指按日计算，与按月的周期付款相冲突。", "按月": "按月表示每个月一次，与定期交房租相合，是正确答案。", "偶尔": "语义：偶尔表示不固定的少数次，与定期交房租不合。", "逐年": "搭配：逐年多用于说变化、增长，不与“交房租”搭配。"}, "sentence_index": 0, "correct_answer": "按月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们按月刷牙。", "explanation": "这里应该用〈每天〉。按月表示每个月一次，刷牙是每天都要做的事，不能用按月。"}, {"text": "他按月下班。", "explanation": "这里应该用〈准时〉。按月表示每个月一次，不表示在规定的时间下班。"}, {"text": "他的飞机按月到达了。", "explanation": "这里应该用〈按时〉。按月表示每个月一次，不能用来说飞机到达的时间准不准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93197, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天天", "is_correct": false, "explanation": "语义：天天指每天，与水费的月周期不合。"}, {"text": "往往", "is_correct": false, "explanation": "语法：往往表示一般规律，不能用在“是……的”中说明交费的方式。"}, {"text": "按月", "is_correct": true, "explanation": "按月表示每个月一次，与水费的缴纳周期相合，是正确答案。"}, {"text": "逐日", "is_correct": false, "explanation": "搭配：逐日多用于累计、变化，不说“交水费”。"}], "explanations": {"天天": "语义：天天指每天，与水费的月周期不合。", "往往": "语法：往往表示一般规律，不能用在“是……的”中说明交费的方式。", "按月": "按月表示每个月一次，与水费的缴纳周期相合，是正确答案。", "逐日": "搭配：逐日多用于累计、变化，不说“交水费”。"}, "sentence_index": 6, "correct_answer": "按月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我按月回了他的电话。", "explanation": "这里应该用〈立即〉。按月表示每个月一次，不能表示马上做某事。"}, {"text": "天按月下雨了。", "explanation": "这里应该用〈突然〉。按月表示每个月一次，不能表示事情忽然发生。"}, {"text": "他们按月结婚了。", "explanation": "这里应该用〈已经〉。按月表示每个月一次，结婚只发生一次，不能用按月。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93197, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家商店每按月进货。", "corrected_sentence": "这家商店按月进货。", "error_description": "错误：“按月”本身已表示“每个月”，前面不能再加“每”。正确：应说“按月进货”，不加“每”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93197, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校按月了检查身体。", "corrected_sentence": "学校按月检查身体。", "error_description": "错误：“按月”与动词“检查”之间多加了“了”。正确：“按月”直接修饰动词，中间不加“了”，应说“按月检查身体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
