INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93198, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "依照月份；每月（做某事）。", "primary_collocate": null, "pronunciation": "àn yuè", "ipa": "an˥˩ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他的工资是按月发的。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们按月付水电费。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会员按月收费。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以按月付钱，不用一次给完。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行按月把利息寄给客户。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王按月存一千块钱。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机费按月算，不按天算。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她按月去医院检查。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司按月开会，不按周开会。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报纸按月出版。", "target_word": "按月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "依照月份来做，以月为单位计算或进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e91c0d-146f-4be2-97f8-2129581fbe82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93198, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天天", "is_correct": false, "explanation": "语义：天天指每天，与工资的月周期不合。"}, {"text": "按月", "is_correct": true, "explanation": "按月表示每个月一次，与工资发放的周期相合，是正确答案。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔表示不固定，与定期发工资不合。"}, {"text": "逐年", "is_correct": false, "explanation": "搭配：逐年多用于说变化、增长，不说“发工资”。"}], "explanations": {"天天": "语义：天天指每天，与工资的月周期不合。", "按月": "按月表示每个月一次，与工资发放的周期相合，是正确答案。", "偶尔": "语义：偶尔表示不固定，与定期发工资不合。", "逐年": "搭配：逐年多用于说变化、增长，不说“发工资”。"}, "sentence_index": 0, "correct_answer": "按月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天按月到了学校。", "explanation": "这里应该用〈准时〉。按月表示每个月一次，不表示按规定时间到达。"}, {"text": "我按月洗澡。", "explanation": "这里应该用〈每天〉。按月表示每个月一次，洗澡是每天的习惯，不能说按月。"}, {"text": "火车按月到站了。", "explanation": "这里应该用〈按时〉。按月表示以月为单位，不表示准时到站。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每天", "is_correct": false, "explanation": "语义：每天与后半句“不按天算”相矛盾。"}, {"text": "按月", "is_correct": true, "explanation": "按月与后半句“不按天算”相对，表示以月为单位，是正确答案。"}, {"text": "立即", "is_correct": false, "explanation": "语义：立即表示马上，与按周期计算的手机费不合。"}, {"text": "逐日", "is_correct": false, "explanation": "搭配：逐日多用于累计、变化，不说“手机费逐日算”。"}], "explanations": {"每天": "语义：每天与后半句“不按天算”相矛盾。", "按月": "按月与后半句“不按天算”相对，表示以月为单位，是正确答案。", "立即": "语义：立即表示马上，与按周期计算的手机费不合。", "逐日": "搭配：逐日多用于累计、变化，不说“手机费逐日算”。"}, "sentence_index": 6, "correct_answer": "按月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按月站起来了。", "explanation": "这里应该用〈立刻〉。按月表示每个月一次，不能表示马上做某个动作。"}, {"text": "他按月哭了。", "explanation": "这里应该用〈突然〉。按月表示每个月一次，不能表示忽然发生的事。"}, {"text": "我们按月吃午饭。", "explanation": "这里应该用〈每天〉。按月表示每个月一次，吃午饭是每天的事，不能说按月。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他按月了发工资。", "corrected_sentence": "他按月发工资。", "error_description": "错误：“按月”与动词“发”之间多加了“了”。正确：“按月”直接修饰动词，中间不加“了”，应说“按月发工资”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本杂志每按月出版。", "corrected_sentence": "这本杂志按月出版。", "error_description": "错误：“按月”前多加了“每”，“按月”本身已表示每个月，二者不能同用。正确：应说“按月出版”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
