INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93201, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与“振兴”没有反义关系。"}, {"text": "衰落", "is_correct": true, "explanation": "“衰落”指地方逐渐衰弱、不再兴盛，与“振兴”意思相反。"}, {"text": "修改", "is_correct": false, "explanation": "“修改”指改动文字或计划，与“振兴”没有反义关系。"}, {"text": "放弃", "is_correct": false, "explanation": "“放弃”指不再坚持某事，与“振兴”没有反义关系。"}], "correct_answer": "衰落", "explanations": {"参加": "“参加”指加入某项活动，与“振兴”没有反义关系。", "衰落": "“衰落”指地方逐渐衰弱、不再兴盛，与“振兴”意思相反。", "修改": "“修改”指改动文字或计划，与“振兴”没有反义关系。", "放弃": "“放弃”指不再坚持某事，与“振兴”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93201, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "振兴是让变差的地方重新变好变强。", "primary_collocate": null, "pronunciation": "zhèn xīng", "ipa": "ʈʂən˥˩ ɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "他们想振兴这个小镇的经济。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府正在振兴老工业区。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人回到农村，想振兴自己的家乡。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条老街多年没人管，现在政府想振兴它。", "target_word": "振兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用旅游来振兴这座旧城。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家希望振兴这个越来越穷的村子。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地方以前很有名，后来变差了，我们要振兴它。", "target_word": "振兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新工厂的建成，帮助振兴了整个地区。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有留住年轻人，才能振兴这座城市。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他回到家乡，决心振兴那里的农业。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "振兴了", "label": "体标"}, {"form": "振兴过", "label": "体标"}, {"form": "振興", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "振兴：让衰落的地方重新变好变强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59d0d08a-d19a-4f5d-af3f-425b4714631c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93201, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "振兴", "is_correct": true, "explanation": "振兴（zhèn xīng）是本题答案，意思是让衰落的地方重新兴盛。"}, {"text": "震惊", "is_correct": false, "explanation": "zhèn jīng 与 zhèn xīng 只有声母不同（j 与 x），意思是震惊。"}, {"text": "震醒", "is_correct": false, "explanation": "zhèn xǐng 的 xǐng（第三声）与 xīng（第一声）声调不同，意思是震动后醒来。"}, {"text": "阵形", "is_correct": false, "explanation": "zhèn xíng 的 xíng（第二声）与 xīng（第一声）声调不同，意思是队伍排列的形式。"}], "explanations": {"振兴": "振兴（zhèn xīng）是本题答案，意思是让衰落的地方重新兴盛。", "震惊": "zhèn jīng 与 zhèn xīng 只有声母不同（j 与 x），意思是震惊。", "震醒": "zhèn xǐng 的 xǐng（第三声）与 xīng（第一声）声调不同，意思是震动后醒来。", "阵形": "zhèn xíng 的 xíng（第二声）与 xīng（第一声）声调不同，意思是队伍排列的形式。"}, "sentence_index": null, "correct_answer": "振兴"}, "level_3": {"options": [{"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是地点、展览等，不能说“参观经济”。"}, {"text": "振兴", "is_correct": true, "explanation": "振兴与“经济”搭配，指使经济重新兴盛，符合“想”的意图。"}, {"text": "摘", "is_correct": false, "explanation": "语义：“摘”指采下果实、花草，经济不能被摘。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象是人或活动，不能说“欢迎经济”。"}], "explanations": {"参观": "搭配：“参观”的对象是地点、展览等，不能说“参观经济”。", "振兴": "振兴与“经济”搭配，指使经济重新兴盛，符合“想”的意图。", "摘": "语义：“摘”指采下果实、花草，经济不能被摘。", "欢迎": "搭配：“欢迎”的对象是人或活动，不能说“欢迎经济”。"}, "sentence_index": 0, "correct_answer": "振兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震后，政府正在振兴这座被毁的房子。", "explanation": "这里应该用〈重建〉。振兴用于地区、行业、事业的重新兴盛，被毁的房子是具体的建筑，要用“重建”。"}, {"text": "他每天锻炼，想振兴自己的健康。", "explanation": "这里应该用〈增强〉。振兴指使衰落的地方或事业重新变好，身体并没有变差，锻炼是为了让身体更强，要用“增强”。"}, {"text": "工人正在振兴这台坏掉的机器。", "explanation": "这里应该用〈修复〉。振兴指使地方或事业重新兴盛，具体的机器坏了要用“修复”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93201, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能用于地方，说“煮它”不通。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”用于马、自行车等，不能用于地方，说“骑它”不通。"}, {"text": "振兴", "is_correct": true, "explanation": "振兴指使变差的地方重新变好、兴盛起来，与“变差了”相呼应，是此处唯一合适的动词。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”的对象是人或动物，地方不能被喂养。"}], "explanations": {"煮": "语义：“煮”的对象是食物，不能用于地方，说“煮它”不通。", "骑": "搭配：“骑”用于马、自行车等，不能用于地方，说“骑它”不通。", "振兴": "振兴指使变差的地方重新变好、兴盛起来，与“变差了”相呼应，是此处唯一合适的动词。", "喂": "语义：“喂”的对象是人或动物，地方不能被喂养。"}, "sentence_index": 6, "correct_answer": "振兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校想振兴每一个学生。", "explanation": "此句把“振兴”用作“使人振作起来”的意思，与本词条“使衰落的地方、事业重新变好”不符，振兴的对象不能是人。"}, {"text": "这项改革振兴了全公司的利润。", "explanation": "此句把“振兴”用作“使数量增长”的意思，与本词条不符，振兴只用于地区、行业、事业的重新兴盛，不用于利润等数量。"}, {"text": "这台旧电脑运行很慢，我们想振兴它的速度。", "explanation": "这里应该用〈提高〉。振兴用于地区、行业、事业，机器的运行速度要用“提高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市长想振兴了这个村子的经济。", "corrected_sentence": "市长想振兴这个村子的经济。", "error_description": "错误：“振兴”后多了“了”。“想”表示打算，句子说的是还没有发生的打算，不能用表示完成的“了”，应去掉“了”，说“市长想振兴这个村子的经济”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇的经济终于振兴下来了。", "corrected_sentence": "这个小镇的经济终于振兴起来了。", "error_description": "错误：补语用错。“下来”多表示由上往下或固定下来，与“振兴”向上变好的意思不合；应用趋向补语“起来”，表示由弱变强、开始兴盛，说“振兴起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93202, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": false, "explanation": "“保护”指使人或物免受伤害，与“振兴”没有反义关系。"}, {"text": "衰败", "is_correct": true, "explanation": "“衰败”指事业或地方由兴盛转为衰落，与“振兴”意思相反。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指探讨问题、弄清情况，与“振兴”没有反义关系。"}, {"text": "拒绝", "is_correct": false, "explanation": "“拒绝”指不接受，与“振兴”没有反义关系。"}], "correct_answer": "衰败", "explanations": {"保护": "“保护”指使人或物免受伤害，与“振兴”没有反义关系。", "衰败": "“衰败”指事业或地方由兴盛转为衰落，与“振兴”意思相反。", "研究": "“研究”指探讨问题、弄清情况，与“振兴”没有反义关系。", "拒绝": "“拒绝”指不接受，与“振兴”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93202, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "参与", "is_correct": false, "explanation": "“参与”指加入某项活动，与“振兴”没有反义关系。"}, {"text": "衰退", "is_correct": true, "explanation": "“衰退”指行业或经济由兴旺转为萎缩，与“振兴”意思相反。"}, {"text": "检查", "is_correct": false, "explanation": "“检查”指察看、核对，与“振兴”没有反义关系。"}, {"text": "忘记", "is_correct": false, "explanation": "“忘记”指不再记得，与“振兴”没有反义关系。"}], "correct_answer": "衰退", "explanations": {"参与": "“参与”指加入某项活动，与“振兴”没有反义关系。", "衰退": "“衰退”指行业或经济由兴旺转为萎缩，与“振兴”意思相反。", "检查": "“检查”指察看、核对，与“振兴”没有反义关系。", "忘记": "“忘记”指不再记得，与“振兴”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93202, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大力发展，使兴盛起来。", "primary_collocate": null, "pronunciation": "zhèn xīng", "ipa": "ʈʂən˥˩ ɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "国家大力支持振兴农村教育。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要努力学习，振兴中华。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府出了新办法来振兴经济。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师们希望振兴当地的文化。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个计划的目标是振兴乡村。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想用一生的力量振兴民族工业。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些年，各地都在想办法振兴旅游业。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家制定了振兴东北的新计划。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了振兴体育，学校建了新球场。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要振兴一个行业，先要培养人才。", "target_word": "振兴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "振兴了", "label": "体标"}, {"form": "振兴过", "label": "体标"}, {"form": "振興", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "振兴：大力发展，使事业或地区兴盛起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59d0d08a-d19a-4f5d-af3f-425b4714631c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93202, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "振兴", "is_correct": true, "explanation": "振兴（zhèn xīng）是本题答案，意思是大力发展，使事业或地区兴盛起来。"}, {"text": "震惊", "is_correct": false, "explanation": "zhèn jīng 与 zhèn xīng 只有声母不同（j 与 x），意思是震惊。"}, {"text": "震醒", "is_correct": false, "explanation": "zhèn xǐng 的 xǐng（第三声）与 xīng（第一声）声调不同，意思是震动后醒来。"}, {"text": "阵形", "is_correct": false, "explanation": "zhèn xíng 的 xíng（第二声）与 xīng（第一声）声调不同，意思是队伍排列的形式。"}], "explanations": {"振兴": "振兴（zhèn xīng）是本题答案，意思是大力发展，使事业或地区兴盛起来。", "震惊": "zhèn jīng 与 zhèn xīng 只有声母不同（j 与 x），意思是震惊。", "震醒": "zhèn xǐng 的 xǐng（第三声）与 xīng（第一声）声调不同，意思是震动后醒来。", "阵形": "zhèn xíng 的 xíng（第二声）与 xīng（第一声）声调不同，意思是队伍排列的形式。"}, "sentence_index": null, "correct_answer": "振兴"}, "level_3": {"options": [{"text": "反对", "is_correct": false, "explanation": "语义：“大力支持”与“反对”意思矛盾。"}, {"text": "振兴", "is_correct": true, "explanation": "振兴与“农村教育”搭配，指大力发展，使其兴盛起来，与“大力支持”一致。"}, {"text": "取消", "is_correct": false, "explanation": "语义：“大力支持”与“取消”意思矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“教育”搭配，也与“大力支持”的语境不合。"}], "explanations": {"反对": "语义：“大力支持”与“反对”意思矛盾。", "振兴": "振兴与“农村教育”搭配，指大力发展，使其兴盛起来，与“大力支持”一致。", "取消": "语义：“大力支持”与“取消”意思矛盾。", "吃": "搭配：“吃”不能与“教育”搭配，也与“大力支持”的语境不合。"}, "sentence_index": 0, "correct_answer": "振兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生正在治疗他，希望振兴他的身体。", "explanation": "这里应该用〈恢复〉。振兴用于地区、行业、事业，人的身体要用“恢复”。"}, {"text": "学校要振兴学生的良好习惯。", "explanation": "这里应该用〈培养〉。振兴用于地区、行业、事业，良好习惯要用“培养”。"}, {"text": "工人正在振兴这座古桥。", "explanation": "这里应该用〈修复〉。振兴的对象是地区、事业，具体的桥梁损坏后要用“修复”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93202, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于枝叶、头发等，不能用于行业，说“修剪旅游业”不通。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”用于马、自行车等，不能用于行业。"}, {"text": "振兴", "is_correct": true, "explanation": "振兴与“旅游业”搭配，指使行业重新兴盛，符合“想办法”的语境。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”的对象是人或动物，旅游业不能被喂养。"}], "explanations": {"修剪": "搭配：“修剪”用于枝叶、头发等，不能用于行业，说“修剪旅游业”不通。", "骑": "搭配：“骑”用于马、自行车等，不能用于行业。", "振兴": "振兴与“旅游业”搭配，指使行业重新兴盛，符合“想办法”的语境。", "喂": "语义：“喂”的对象是人或动物，旅游业不能被喂养。"}, "sentence_index": 6, "correct_answer": "振兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想振兴这次考试的成绩。", "explanation": "这里应该用〈提高〉。振兴用于地区、行业、事业，考试成绩等水平要用“提高”。"}, {"text": "公司今年想振兴员工的人数。", "explanation": "这里应该用〈增加〉。振兴不用于人数等数量，员工人数要用“增加”。"}, {"text": "这家店太小了，老板想振兴这家店的规模。", "explanation": "这里应该用〈扩大〉。振兴用于地区、行业、事业的兴盛，店铺的规模、范围要用“扩大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村民们正在振兴了这个村子的文化。", "corrected_sentence": "村民们正在振兴这个村子的文化。", "error_description": "错误：“振兴”后多了“了”。“正在”表示动作正在进行，不能与表示完成的“了”同用，应去掉“了”，说“村民们正在振兴这个村子的文化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年，各地的旅游业都慢慢振兴下来了。", "corrected_sentence": "这些年，各地的旅游业都慢慢振兴起来了。", "error_description": "错误：补语“下来”应改为“起来”。“振兴起来”表示由弱变强、开始兴盛，“振兴下来”的说法不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
