INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93203, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93203, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "经济活动是人们买东西、卖东西、做东西的事。", "primary_collocate": null, "pronunciation": "jīng jì huó dòng", "ipa": "tɕiŋ˥ tɕi˥˩ xuo˧˥ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "买东西、卖东西都是经济活动。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂做东西，也是一种经济活动。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场里每天都有很多经济活动。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开商店是常见的经济活动。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，经济活动特别多。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城的经济活动慢慢多起来了。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨时，街上的经济活动少了。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们在市场里进行经济活动。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民卖菜也是经济活动。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的经济活动主要是种茶和卖茶。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "經濟活動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人们买东西、卖东西、做东西的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de94bd89-19e3-4337-868c-ae9af5a910e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93203, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经济活动", "is_correct": true, "explanation": "正确。“经济活动”指买东西、卖东西、做东西等事情，与句意一致。"}, {"text": "运动", "is_correct": false, "explanation": "语义：买东西、卖东西不是体育锻炼，“运动”与句意不合。"}, {"text": "节日", "is_correct": false, "explanation": "语义：买卖是日常行为，不是节日，句意不合。"}, {"text": "经济状况", "is_correct": false, "explanation": "搭配：“状况”指一种状态，不能说“买东西、卖东西都是状况”，“都是”后面应接表示活动的词。"}], "explanations": {"经济活动": "正确。“经济活动”指买东西、卖东西、做东西等事情，与句意一致。", "运动": "语义：买东西、卖东西不是体育锻炼，“运动”与句意不合。", "节日": "语义：买卖是日常行为，不是节日，句意不合。", "经济状况": "搭配：“状况”指一种状态，不能说“买东西、卖东西都是状况”，“都是”后面应接表示活动的词。"}, "sentence_index": 0, "correct_answer": "经济活动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在操场上进行经济活动，跑了三圈。", "explanation": "“经济活动”指生产、买卖等经济行为，不指体育锻炼，用来描述跑步不合适。"}, {"text": "我们村有一座重要的经济活动。", "explanation": "这里应该用〈项〉。“经济活动”的量词是“项”，“座”用于山、楼等，不能修饰它。"}, {"text": "他的大学专业是经济活动。", "explanation": "这里应该用〈经济学〉。经济学指学科，经济活动指经济行为，不能作专业名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93203, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济活动", "is_correct": true, "explanation": "正确。下大雨时，街上的买卖、做事等活动减少，与句意一致。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“街上的历史”不是随下雨而增减的事物，与句意不合。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“少”多用于数量，“年龄”不能说“街上的年龄少了”。"}, {"text": "道德", "is_correct": false, "explanation": "语义：道德不会因为下大雨而在街上减少，与句意不合。"}], "explanations": {"经济活动": "正确。下大雨时，街上的买卖、做事等活动减少，与句意一致。", "历史": "语义：“街上的历史”不是随下雨而增减的事物，与句意不合。", "年龄": "搭配：“少”多用于数量，“年龄”不能说“街上的年龄少了”。", "道德": "语义：道德不会因为下大雨而在街上减少，与句意不合。"}, "sentence_index": 6, "correct_answer": "经济活动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府出台了这项经济活动，规定大家要遵守。", "explanation": "这里应该用〈经济政策〉。“出台”的对象是政策、规定，“经济活动”指人们的经济行为，不能出台。"}, {"text": "他是我们村最有名的经济活动。", "explanation": "语义：“经济活动”指行为，不指人，不能说“他是……经济活动”。"}, {"text": "茶叶买卖是我们村的一颗经济活动。", "explanation": "这里应该用〈项〉。“经济活动”的量词是“项”，“颗”用于小而圆的东西，不能修饰它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村有三只经济活动。", "corrected_sentence": "我们村有三项经济活动。", "error_description": "量词错误：“经济活动”应用量词“项”，“只”用于动物或成对的物品，不能修饰“经济活动”。应改为“三项经济活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们正在进行了经济活动。", "corrected_sentence": "他们正在进行经济活动。", "error_description": "时态错误：“正在”表示动作正在进行，不能与表示完成的“了”连用。应删去“了”，写作“他们正在进行经济活动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
