INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93204, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们生产、分配、交换和消费物品与服务的活动。", "primary_collocate": null, "pronunciation": "jīng jì huó dòng", "ipa": "tɕiŋ˥ tɕi˥˩ xuo˧˥ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "生产和消费都是重要的经济活动。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要管理国家的经济活动。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济活动包括生产、分配、交换和消费。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争会影响一个国家的经济活动。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络让经济活动变得更方便了。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的经济活动很活跃。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的经济活动要遵守法律。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业是最早的经济活动之一。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们讲讲身边的经济活动。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济活动多了，人们的收入也高了。", "target_word": "经济活动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "經濟活動", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "生产、分配、交换和消费物品与服务的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de94bd89-19e3-4337-868c-ae9af5a910e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93204, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经济活动", "is_correct": true, "explanation": "正确。“经济活动”指生产、分配、交换和消费等行为，与句意一致。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：生产和消费不是比赛，“比赛”与句意不合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是生产和消费，句中说的是经济行为，与“天气”不合。"}, {"text": "勾当", "is_correct": false, "explanation": "语域：“勾当”含贬义，与“重要的”这种中性评价不合。"}], "explanations": {"经济活动": "正确。“经济活动”指生产、分配、交换和消费等行为，与句意一致。", "比赛": "语义：生产和消费不是比赛，“比赛”与句意不合。", "天气": "语义：天气不是生产和消费，句中说的是经济行为，与“天气”不合。", "勾当": "语域：“勾当”含贬义，与“重要的”这种中性评价不合。"}, "sentence_index": 0, "correct_answer": "经济活动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司只有一条经济活动。", "explanation": "这里应该用〈项〉。“经济活动”的量词是“项”，“条”用于细长的东西，不能修饰它。"}, {"text": "他大学学的是经济活动。", "explanation": "这里应该用〈经济学〉。经济学是学科，经济活动是经济行为，不能作所学的专业。"}, {"text": "学生们在教室里做经济活动，练习写字。", "explanation": "“经济活动”指经济行为，不指练习写字这类学习活动，句中用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济活动", "is_correct": true, "explanation": "正确。公司的经济活动须遵守法律，与句意一致。"}, {"text": "季节", "is_correct": false, "explanation": "语义：季节是自然的时间段，不是公司需要遵守法律的事务，句意不合。"}, {"text": "节气", "is_correct": false, "explanation": "语义：节气与公司经营无关，放在句中句意不合。"}, {"text": "晚霞", "is_correct": false, "explanation": "语义：晚霞是天空的景象，不是公司需要遵守法律的事务，句意不合。"}], "explanations": {"经济活动": "正确。公司的经济活动须遵守法律，与句意一致。", "季节": "语义：季节是自然的时间段，不是公司需要遵守法律的事务，句意不合。", "节气": "语义：节气与公司经营无关，放在句中句意不合。", "晚霞": "语义：晚霞是天空的景象，不是公司需要遵守法律的事务，句意不合。"}, "sentence_index": 6, "correct_answer": "经济活动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府制定了经济活动，人们的收入也高了。", "explanation": "这里应该用〈经济政策〉。“制定”的对象是政策、规定，“经济活动”不能被制定。"}, {"text": "这个经济活动是我最好的朋友。", "explanation": "语义：“经济活动”指行为，不指人，不能说它是“朋友”。"}, {"text": "那边有一台经济活动。", "explanation": "这里应该用〈项〉。“经济活动”的量词是“项”，“台”不能用来修饰它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府正在管理这几只经济活动。", "corrected_sentence": "政府正在管理这几项经济活动。", "error_description": "量词错误：“经济活动”的量词应为“项”，“只”不能用于这个名词。应把“这几只经济活动”改为“这几项经济活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一颗经济活动很重要。", "corrected_sentence": "这一项经济活动很重要。", "error_description": "量词错误：“经济活动”应用量词“项”，“颗”用于小而圆的东西，不能修饰它。应把“这一颗经济活动”改为“这一项经济活动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
