INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93205, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "担当是把一件事接过来，自己负责做好。", "primary_collocate": null, "pronunciation": "dān dāng", "ipa": "tan˥ taŋ˥", "syllable_count": 2, "sentences": [{"text": "这件事我来担当，你放心吧。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他愿意担当这次活动的组织工作。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁愿意担当这次联欢会的策划工作？", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她担当了小组的记录工作。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个任务太难，他一个人担当不了。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这出戏里担当主角。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我担当这次比赛的后勤工作。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他担当过三年的财务工作。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家这件事，由哥哥担当。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他主动担当起了做饭的工作。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "擔當", "label": "繁体"}, {"form": "担当了", "label": "体标"}, {"form": "担当过", "label": "体标"}, {"form": "担当着", "label": "体标"}], "register": "中性", "sense_fingerprint": "接下某项任务或职务并负责做好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5582003f-0fa5-4559-bf80-a34613800f6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93205, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担当", "is_correct": true, "explanation": "“担当”表示接下这件事并负责，与“你放心吧”的承诺语气相符。"}, {"text": "害怕", "is_correct": false, "explanation": "搭配：“我来害怕”不成话，“来”后需接主动承担的动作，“害怕”是心理状态。"}, {"text": "躲避", "is_correct": false, "explanation": "搭配：“躲避”多接危险、困难，不说“这件事我来躲避”来表示承接任务。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”是设法不去做，与“你放心吧”的保证相矛盾。"}], "explanations": {"担当": "“担当”表示接下这件事并负责，与“你放心吧”的承诺语气相符。", "害怕": "搭配：“我来害怕”不成话，“来”后需接主动承担的动作，“害怕”是心理状态。", "躲避": "搭配：“躲避”多接危险、困难，不说“这件事我来躲避”来表示承接任务。", "逃避": "语义：“逃避”是设法不去做，与“你放心吧”的保证相矛盾。"}, "sentence_index": 0, "correct_answer": "担当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他担当了老师送的礼物。", "explanation": "这里应该用〈收下〉。担当的对象是任务或责任，礼物应说“收下”。"}, {"text": "这项实验已经担当了三天。", "explanation": "这里应该用〈进行〉。担当的主语须是能承担任务的人，不能用来描述实验持续的过程。"}, {"text": "我担当了三本书。", "explanation": "这里应该用〈借〉。担当的宾语须是任务或职务，书籍是实物，不能用“担当”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93205, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "担当", "is_correct": true, "explanation": "“担当”表示接下后勤任务并负责，与“老师让我”的安排相符。"}, {"text": "抗拒", "is_correct": false, "explanation": "语义：“抗拒”是拒不接受，与“老师让我”的指派相悖。"}, {"text": "回避", "is_correct": false, "explanation": "搭配：“回避”多接问题、话题，不说“回避后勤工作”。"}, {"text": "躲藏", "is_correct": false, "explanation": "搭配：“躲藏”是不及物动词，不能带“后勤工作”这样的宾语。"}], "explanations": {"担当": "“担当”表示接下后勤任务并负责，与“老师让我”的安排相符。", "抗拒": "语义：“抗拒”是拒不接受，与“老师让我”的指派相悖。", "回避": "搭配：“回避”多接问题、话题，不说“回避后勤工作”。", "躲藏": "搭配：“躲藏”是不及物动词，不能带“后勤工作”这样的宾语。"}, "sentence_index": 6, "correct_answer": "担当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他担当了一首新歌。", "explanation": "这里应该用〈创作〉。担当用于任务、职务或责任，不能用来指谱写或写作作品。"}, {"text": "她担当了很大的痛苦。", "explanation": "这里应该用〈承受〉。担当指接下任务或责任，身体或精神上的痛苦应说“承受”。"}, {"text": "他担当了一门技术。", "explanation": "这里应该用〈掌握〉。担当不用于技能或知识，学会一门技术应说“掌握”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他愿意担当了我们班的班长。", "corrected_sentence": "他愿意担当我们班的班长。", "error_description": "“担当”后面多加了“了”，表示动作已经完成，与“愿意”表示的意愿相矛盾。应去掉“了”，说“他愿意担当我们班的班长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她担当了起班里的所有工作。", "corrected_sentence": "她担当起了班里的所有工作。", "error_description": "趋向补语“起”应紧跟动词“担当”，再接“了”，应说“担当起了”，而不是“担当了起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93206, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推卸", "is_correct": true, "explanation": "“推卸”指不肯承担责任而推给别人，与“担当”的承担责任意义相对。"}, {"text": "休息", "is_correct": false, "explanation": "“休息”指停下来歇息，与“担当”的责任意义无反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "“观看”指注视某种景象或表演，与“担当”的责任意义无关。"}, {"text": "设计", "is_correct": false, "explanation": "“设计”指规划图样或方案，与“担当”的责任意义无反义关系。"}], "correct_answer": "推卸", "explanations": {"推卸": "“推卸”指不肯承担责任而推给别人，与“担当”的承担责任意义相对。", "休息": "“休息”指停下来歇息，与“担当”的责任意义无反义关系。", "观看": "“观看”指注视某种景象或表演，与“担当”的责任意义无关。", "设计": "“设计”指规划图样或方案，与“担当”的责任意义无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93206, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推卸", "is_correct": true, "explanation": "“推卸”指不肯承担责任而推给别人，与“担当”的承担责任意义相对。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”指在水中运动，与“担当”的责任意义无关。"}, {"text": "打扫", "is_correct": false, "explanation": "“打扫”指清除脏物，与“担当”的责任意义无反义关系。"}, {"text": "询问", "is_correct": false, "explanation": "“询问”指提出问题请人解答，与“担当”的责任意义无反义关系。"}], "correct_answer": "推卸", "explanations": {"推卸": "“推卸”指不肯承担责任而推给别人，与“担当”的承担责任意义相对。", "游泳": "“游泳”指在水中运动，与“担当”的责任意义无关。", "打扫": "“打扫”指清除脏物，与“担当”的责任意义无反义关系。", "询问": "“询问”指提出问题请人解答，与“担当”的责任意义无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93206, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接受并负起责任。", "primary_collocate": null, "pronunciation": "dān dāng", "ipa": "tan˥ taŋ˥", "syllable_count": 2, "sentences": [{"text": "做错了事，就要敢于担当。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犯了错，自己担当后果。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了问题，经理愿意担当责任。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错不是你的，不用你担当。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不敢担当，总是怪别人。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人担当着全家的责任。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情失败了，我愿意担当所有责任。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他担当起了照顾弟弟的责任。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了事，我来担当。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从不躲开责任，总是主动担当。", "target_word": "担当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "擔當", "label": "繁体"}, {"form": "担当了", "label": "体标"}, {"form": "担当过", "label": "体标"}, {"form": "担当着", "label": "体标"}], "register": "中性", "sense_fingerprint": "接受并承担责任或后果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5582003f-0fa5-4559-bf80-a34613800f6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93206, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担当", "is_correct": true, "explanation": "“担当”表示接受并承担责任，与“做错了事，就要敢于”的语境相符。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”是躲开责任，与“敢于”的勇敢态度相反。"}, {"text": "承包", "is_correct": false, "explanation": "搭配：“承包”多指承揽工程或业务，不指对过错负责。"}, {"text": "退缩", "is_correct": false, "explanation": "语义：“退缩”是因害怕而后退，与“敢于”的语义矛盾。"}], "explanations": {"担当": "“担当”表示接受并承担责任，与“做错了事，就要敢于”的语境相符。", "逃避": "语义：“逃避”是躲开责任，与“敢于”的勇敢态度相反。", "承包": "搭配：“承包”多指承揽工程或业务，不指对过错负责。", "退缩": "语义：“退缩”是因害怕而后退，与“敢于”的语义矛盾。"}, "sentence_index": 0, "correct_answer": "担当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他担当了整个假期。", "explanation": "这里应该用〈享受〉。担当指承担责任或任务，不能用来支配假期这样的时间。"}, {"text": "他担当了那台电脑。", "explanation": "这里应该用〈修理〉。担当的对象是责任或任务，不能用于具体的物品。"}, {"text": "他担当了两个小时。", "explanation": "这里应该用〈等待〉。担当不能表示耗费时间，等了两个小时应说“等待”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "担当", "is_correct": true, "explanation": "“担当”表示愿意承担所有责任，与“事情失败了”的语境相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“我愿意”的意愿相矛盾，不能拒绝所有责任。"}, {"text": "躲开", "is_correct": false, "explanation": "语义：“躲开”是避开，与“我愿意”的主动态度相矛盾。"}, {"text": "推辞", "is_correct": false, "explanation": "搭配：“推辞”多接职务、邀请，不说“推辞所有责任”。"}], "explanations": {"担当": "“担当”表示愿意承担所有责任，与“事情失败了”的语境相符。", "拒绝": "语义：“拒绝”与“我愿意”的意愿相矛盾，不能拒绝所有责任。", "躲开": "语义：“躲开”是避开，与“我愿意”的主动态度相矛盾。", "推辞": "搭配：“推辞”多接职务、邀请，不说“推辞所有责任”。"}, "sentence_index": 6, "correct_answer": "担当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他担当了自己的时间。", "explanation": "这里应该用〈控制〉。担当指承担责任或任务，不能用来支配时间。"}, {"text": "爱迪生担当了电灯。", "explanation": "这里应该用〈发明〉。担当不用于创造事物，电灯是爱迪生发明的。"}, {"text": "我们担当了美丽的风景。", "explanation": "这里应该用〈欣赏〉。担当的对象是责任或任务，风景应该用“欣赏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她从来没担当了家里的事。", "corrected_sentence": "她从来没担当过家里的事。", "error_description": "错误形式是“没担当了”，正确形式是“没担当过”。表示没有过某种经历时，动词后应用“过”，不用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "做错事的人应该担当了起责任。", "corrected_sentence": "做错事的人应该担当起责任。", "error_description": "错误形式是“担当了起责任”，正确形式是“担当起责任”。趋向补语“起”须紧跟动词“担当”，中间不能插入“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
