INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93207, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "线路是电或车子走的那条路线。", "primary_collocate": null, "pronunciation": "xiàn lù", "ipa": "ɕjɛn˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这条公交线路经过我家门口。", "target_word": "线路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子里的线路坏了，所以没有电。", "target_word": "线路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁新线路下个月开通。", "target_word": "线路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先检查一下线路，再打开灯。", "target_word": "线路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条线路上的车很多，要等很久。", "target_word": "线路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧线路太危险，工人换了新线路。", "target_word": "线路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天坐这条线路去学校。", "target_word": "线路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着地图，想找一条合适的线路。", "target_word": "线路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视没有声音，可能是线路有问题。", "target_word": "线路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司新开了一条去机场的线路。", "target_word": "线路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条线路", "label": "量词"}], "register": "中性", "sense_fingerprint": "电或车子走的那条路线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5cbcac1-4e17-487d-bba3-6efb4b2cfcde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93207, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "线路", "is_correct": true, "explanation": "正确：“公交线路”指公交车走的路线，“经过我家门口”符合句意。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票是买来坐车用的，不能“经过”门口，句子说不通。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“经过”的主语应是能移动的车辆或路线，“座位”不能与“经过”搭配。"}, {"text": "车牌", "is_correct": false, "explanation": "语义：车牌是挂在车上的标识，不会“经过”门口，句子说不通。"}], "explanations": {"线路": "正确：“公交线路”指公交车走的路线，“经过我家门口”符合句意。", "车票": "语义：车票是买来坐车用的，不能“经过”门口，句子说不通。", "座位": "搭配：“经过”的主语应是能移动的车辆或路线，“座位”不能与“经过”搭配。", "车牌": "语义：车牌是挂在车上的标识，不会“经过”门口，句子说不通。"}, "sentence_index": 0, "correct_answer": "线路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们坚持正确的线路，把工作做好。", "explanation": "这里应该用〈方针〉。线路指具体的电路或车子走的路，抽象的方针不能说“线路”。"}, {"text": "这是解决问题的好线路。", "explanation": "这里应该用〈途径〉。线路指具体的路径，解决问题的办法要说“途径”。"}, {"text": "他找到了自己的人生线路。", "explanation": "这里应该用〈路线〉。线路指具体的电力或交通路径，人生的方向要说“路线”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93207, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "线路", "is_correct": true, "explanation": "正确：“坐这条线路”指乘坐这条交通路线去学校，符合句意。"}, {"text": "桥", "is_correct": false, "explanation": "语义：桥是用来走过的，不能“坐”着去学校，句子说不通。"}, {"text": "隧道", "is_correct": false, "explanation": "搭配：“坐”的对象应是交通工具，不说“坐隧道”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能被“坐”去学校，这里说不通。"}], "explanations": {"线路": "正确：“坐这条线路”指乘坐这条交通路线去学校，符合句意。", "桥": "语义：桥是用来走过的，不能“坐”着去学校，句子说不通。", "隧道": "搭配：“坐”的对象应是交通工具，不说“坐隧道”。", "河流": "语义：河流不能被“坐”去学校，这里说不通。"}, "sentence_index": 6, "correct_answer": "线路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司新开了一座去机场的线路。", "explanation": "这里量词应该用〈条〉。“座”用于山、桥、楼等大型固定物，线路按“条”计数。"}, {"text": "公司新开了一把去机场的线路。", "explanation": "这里量词应该用〈条〉。“把”用于有柄的东西，线路不用“把”计数。"}, {"text": "公司新开了一台去机场的线路。", "explanation": "这里量词应该用〈条〉。“台”用于机器、仪器，线路不用“台”计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93207, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这朵线路一直通到郊区。", "corrected_sentence": "这条线路一直通到郊区。", "error_description": "错误形式：“这朵线路”。正确形式：“这条线路”。线路是长条状的，应用“条”计数；“朵”用于花、云等，不用于线路。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93207, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站附近新开了一颗公交线路。", "corrected_sentence": "车站附近新开了一条公交线路。", "error_description": "错误形式：“一颗公交线路”。正确形式：“一条公交线路”。线路是长条状的，应用“条”计数；“颗”用于小而圆的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
