INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93209, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "收取是把别人给的钱或东西拿过来。", "primary_collocate": null, "pronunciation": "shōu qǔ", "ipa": "ʂoʊ˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "老板收取了客人给的钱，然后给了他一杯茶。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员收取了我们寄出的包裹。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行收取了他交来的一千块钱。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师收取了同学们交来的书本费。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室收取了他送来的样品，并登记编号。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员收取我给的钱，然后找了零钱。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司收取了客户付的钱，马上发货。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮局收取我们寄的信，三天后会送到。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库收取了供应商的一批原料，清点后入库。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在柜台收取了客户递过来的合同，并核对了签名。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收取了", "label": "体标"}, {"form": "收取过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把别人交来、送来的钱或东西接过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f25efb-a327-4991-90ce-e83d14deee0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93209, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”用于碗盘等易碎物，不能说打碎钱。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”的宾语应是车船等交通工具，不能接“钱”。"}, {"text": "收取", "is_correct": true, "explanation": "正确。“收取”表示接过客人给的钱，与后文“给了他一杯茶”相符。"}, {"text": "朗读", "is_correct": false, "explanation": "语义：“朗读”的对象是文字，不能用来形容钱。"}], "explanations": {"打碎": "搭配：“打碎”用于碗盘等易碎物，不能说打碎钱。", "驾驶": "配价：“驾驶”的宾语应是车船等交通工具，不能接“钱”。", "收取": "正确。“收取”表示接过客人给的钱，与后文“给了他一杯茶”相符。", "朗读": "语义：“朗读”的对象是文字，不能用来形容钱。"}, "sentence_index": 0, "correct_answer": "收取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天收取房间。", "explanation": "这里应该用〈收拾〉。收取表示接过别人交来的东西，整理房间要说收拾。"}, {"text": "他收取了我的道歉。", "explanation": "这里应该用〈接受〉。收取只用于接过别人交来的钱或具体东西，不能用于道歉。"}, {"text": "他收取了一个好消息。", "explanation": "这里应该用〈收到〉。消息不能被收取，只能说收到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”接乐曲或乐器，不说演奏钱。"}, {"text": "收取", "is_correct": true, "explanation": "正确。“收取”表示接过客户付的钱，与“马上发货”的语境相符。"}, {"text": "播放", "is_correct": false, "explanation": "语义：“播放”的对象是影音内容，与钱无关。"}, {"text": "订购", "is_correct": false, "explanation": "配价：“订购”的宾语应是货物，不能接“钱”。"}], "explanations": {"演奏": "搭配：“演奏”接乐曲或乐器，不说演奏钱。", "收取": "正确。“收取”表示接过客户付的钱，与“马上发货”的语境相符。", "播放": "语义：“播放”的对象是影音内容，与钱无关。", "订购": "配价：“订购”的宾语应是货物，不能接“钱”。"}, "sentence_index": 6, "correct_answer": "收取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在路边收取了一个丢失的钱包。", "explanation": "这里应该用〈捡起〉。收取表示别人把东西交给自己，路边捡到的东西要说捡起。"}, {"text": "他收取了压力，但很快就放下了。", "explanation": "这里应该用〈承受〉。收取只用于接过具体的钱或物，压力不能收取，要说承受。"}, {"text": "他收取了一顿美餐。", "explanation": "这里应该用〈享受〉。收取是接过别人交来的东西，吃一顿美餐要说享受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "服务员了收取了我们的一笔钱。", "corrected_sentence": "服务员收取了我们的一笔钱。", "error_description": "错误：“收取”前面多了一个“了”，动态助词“了”只能紧跟在动词后面，应删去动词前的“了”，说“收取了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没收取了我的钱。", "corrected_sentence": "他没收取我的钱。", "error_description": "错误：“没”否定已发生的动作时，动词后不能再加“了”，应说“他没收取我的钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
