INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93210, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向人按规定征收（费用等）。", "primary_collocate": null, "pronunciation": "shōu qǔ", "ipa": "ʂoʊ˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "停车场按小时收取停车费。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行每个月收取一点手续费。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校按规定收取书本费。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院不收取挂号费。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景区向游客收取门票费。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东每月向我们收取房租。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司收取客户的服务费时，要开发票。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园不向孩子收取任何费用。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递公司按重量收取运费。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按规定，商店不能多收取顾客的钱。", "target_word": "收取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收取了", "label": "体标"}, {"form": "收取过", "label": "体标"}], "register": "中性", "sense_fingerprint": "按规定向别人收费用、租金等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f25efb-a327-4991-90ce-e83d14deee0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发放", "is_correct": false, "explanation": "搭配：“发放”指发给别人，不能用于停车场向车主收费。"}, {"text": "收取", "is_correct": true, "explanation": "正确。“收取”表示按规定向车主收费，与“按小时”的收费语境相符。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”的宾语应是商品，不能接“停车费”。"}, {"text": "支付", "is_correct": false, "explanation": "语义：“支付”是付钱的一方，停车场是收钱的一方，句意不通。"}], "explanations": {"发放": "搭配：“发放”指发给别人，不能用于停车场向车主收费。", "收取": "正确。“收取”表示按规定向车主收费，与“按小时”的收费语境相符。", "购买": "配价：“购买”的宾语应是商品，不能接“停车费”。", "支付": "语义：“支付”是付钱的一方，停车场是收钱的一方，句意不通。"}, "sentence_index": 0, "correct_answer": "收取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向朋友收取了一个笑容。", "explanation": "这里应该用〈得到〉。收取的对象应是费用，笑容不能收取，应说“他从朋友那里得到了一个笑容”。"}, {"text": "学校向学生收取了一句问候。", "explanation": "这里应该用〈收到〉。收取的对象应是按规定收的费用，问候不是费用，应说“学校收到了学生的一句问候”。"}, {"text": "顾客向店家收取了饭钱。", "explanation": "这里应该用〈付〉。收取的主语是收费的一方，付钱的顾客应说付。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "补充", "is_correct": false, "explanation": "语义：“补充”指增添，不能表示收取费用。"}, {"text": "收取", "is_correct": true, "explanation": "正确。“收取”表示公司向客户收服务费，与“要开发票”相符。"}, {"text": "挑选", "is_correct": false, "explanation": "语义：“挑选”指从多个对象中选择，与收费无关。"}, {"text": "收拾", "is_correct": false, "explanation": "搭配：“收拾”用于房间、物品，不说收拾服务费。"}], "explanations": {"补充": "语义：“补充”指增添，不能表示收取费用。", "收取": "正确。“收取”表示公司向客户收服务费，与“要开发票”相符。", "挑选": "语义：“挑选”指从多个对象中选择，与收费无关。", "收拾": "搭配：“收拾”用于房间、物品，不说收拾服务费。"}, "sentence_index": 6, "correct_answer": "收取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乘客向司机收取了车费。", "explanation": "这里应该用〈支付〉。收取的主语是收费的一方，付车费的乘客应说支付。"}, {"text": "店家收取了顾客的歉意。", "explanation": "这里应该用〈接受〉。歉意是抽象的，不能被收取，只能说接受。"}, {"text": "公司收取了客户的损失。", "explanation": "这里应该用〈赔偿〉。收取只用于收费，损失不能被收取，应说公司赔偿了客户的损失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车站了收取了一笔行李费。", "corrected_sentence": "车站收取了一笔行李费。", "error_description": "错误：“收取”前面多了一个“了”，动态助词“了”只能紧跟在动词后面，应删去动词前的“了”，说“收取了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "停车场很收取停车费。", "corrected_sentence": "停车场收取停车费。", "error_description": "错误：“很”是程度副词，不能修饰动词“收取”，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
