INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93211, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "总体是把所有部分加在一起的全部。", "primary_collocate": null, "pronunciation": "zǒng tǐ", "ipa": "tsʊŋ˨˩ tʰi˨˩", "syllable_count": 2, "sentences": [{"text": "总体来说，今年的天气很好。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总体来看，我们班学习不错。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总体上，这次旅行很愉快。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书总体写得很清楚。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总体上看，这幅画很漂亮。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先想总体，再想小地方。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，全班的总体情况很好。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的总体情况不错。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总体而言，大家对这件事很满意。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班的总体成绩很好。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "总体上", "label": "复合"}], "register": "中性", "sense_fingerprint": "各个部分合起来的全部，整体情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '731f2910-2ba7-4598-8f94-a05db7954603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93211, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总体", "is_correct": true, "explanation": "「总体来说」表示从整体上概括，与句意相符。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：「桌子来说」不成立，「来说」后面要接人或观察的视角。"}, {"text": "河流", "is_correct": false, "explanation": "语义：「河流」不能作为评价天气的视角，句意不通。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：「电脑来说」不成立，「来说」后面要接人或观察的视角。"}], "explanations": {"总体": "「总体来说」表示从整体上概括，与句意相符。", "桌子": "搭配：「桌子来说」不成立，「来说」后面要接人或观察的视角。", "河流": "语义：「河流」不能作为评价天气的视角，句意不通。", "电脑": "搭配：「电脑来说」不成立，「来说」后面要接人或观察的视角。"}, "sentence_index": 0, "correct_answer": "总体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "总体每人花了一百元。", "explanation": "这里应该用〈平均〉。「总体」指把所有部分加在一起的全部，不表示平均数，不能说「每人」。"}, {"text": "他把总体一下子打碎了。", "explanation": "这里应该用〈东西〉。「总体」是抽象的整体概念，不能当作具体物件打碎。"}, {"text": "她把总体带回了家。", "explanation": "这里应该用〈东西〉。「总体」是抽象概念，不能当作具体物品带回家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93211, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总体", "is_correct": true, "explanation": "「总体情况」指全班各方面合起来的整体情况，与句意相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：「全班的天空情况」说不通，天空与考试无关。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：「全班的月亮情况」说不通，月亮与考试无关。"}, {"text": "大海", "is_correct": false, "explanation": "语义：「全班的大海情况」说不通，大海与考试无关。"}], "explanations": {"总体": "「总体情况」指全班各方面合起来的整体情况，与句意相符。", "天空": "语义：「全班的天空情况」说不通，天空与考试无关。", "月亮": "语义：「全班的月亮情况」说不通，月亮与考试无关。", "大海": "语义：「全班的大海情况」说不通，大海与考试无关。"}, "sentence_index": 6, "correct_answer": "总体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把总体摔在了地上。", "explanation": "这里应该用〈东西〉。「总体」是抽象概念，不能当作具体物品摔在地上。"}, {"text": "我总体一个人去了北京。", "explanation": "这里应该用〈单独〉。「总体」表示把所有部分加在一起的全部，不能表示只有一个人、独自去做。"}, {"text": "他把总体一下子吃完了。", "explanation": "这里应该用〈饭〉。「总体」是抽象概念，不能当作食物吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "总体来说了，这次活动很成功。", "corrected_sentence": "总体来说，这次活动很成功。", "error_description": "错误：「来说了」；正确：「总体来说」。「总体来说」是固定的插入语，后面不能加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "总体的来说，大家很满意。", "corrected_sentence": "总体来说，大家很满意。", "error_description": "错误：多加了「的」；正确：「总体来说」。「总体来说」是固定的插入语，「总体」和「来说」之间不能加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93212, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "个体", "is_correct": true, "explanation": "「个体」指单个的人或事物，与「总体」相对，是反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：「桌子」与「总体」在这个义项上没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：「河流」与「总体」在这个义项上没有反义关系。"}, {"text": "蚂蚁", "is_correct": false, "explanation": "无关：「蚂蚁」与「总体」在这个义项上没有反义关系。"}], "correct_answer": "个体", "explanations": {"个体": "「个体」指单个的人或事物，与「总体」相对，是反义关系。", "桌子": "无关：「桌子」与「总体」在这个义项上没有反义关系。", "河流": "无关：「河流」与「总体」在这个义项上没有反义关系。", "蚂蚁": "无关：「蚂蚁」与「总体」在这个义项上没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
