INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由许多个体组成的整体。", "primary_collocate": null, "pronunciation": "zǒng tǐ", "ipa": "tsʊŋ˨˩ tʰi˨˩", "syllable_count": 2, "sentences": [{"text": "我们从总体里选了二十个人。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总体的人数有一千人。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个总体里有老人和孩子。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先分析总体的特点，再分析个人的特点。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总体中的每个人都要回答。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个调查的总体很大。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们只能用小部分代表总体。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总体里男生比女生多。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总体和个体有什么不同？", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们从总体中找出了十个学生。", "target_word": "总体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "总体上", "label": "复合"}], "register": "中性", "sense_fingerprint": "由许多个体构成的整体，与个体相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '731f2910-2ba7-4598-8f94-a05db7954603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总体", "is_correct": true, "explanation": "「总体」指由许多个体组成的整体，这里是选取对象的全体，与句意相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是由许多个体组成的集合，不能从中选人，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：「天空」不是可以从中挑选人的集合，句意不通。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：「从……里选」要求对象是一群人或事物的集合，不能说从书包里选人。"}], "explanations": {"总体": "「总体」指由许多个体组成的整体，这里是选取对象的全体，与句意相符。", "桌子": "语义：桌子不是由许多个体组成的集合，不能从中选人，句意不通。", "天空": "语义：「天空」不是可以从中挑选人的集合，句意不通。", "书包": "搭配：「从……里选」要求对象是一群人或事物的集合，不能说从书包里选人。"}, "sentence_index": 0, "correct_answer": "总体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "总体城市都下了雪。", "explanation": "这里应该用〈整个〉。「总体」指由许多个体组成的整体，不能像「整个」那样修饰「城市」表示全部。"}, {"text": "她把总体放在了桌子上。", "explanation": "这里应该用〈东西〉。「总体」是抽象的集合概念，不能当作具体物件放在桌上。"}, {"text": "我的总体是一个学生。", "explanation": "这里应该用〈身份〉。「总体」指由许多个体组成的整体，不能指一个人的身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总体", "is_correct": true, "explanation": "「总体」是被代表的整体，与「小部分代表」的语境相符。"}, {"text": "电话", "is_correct": false, "explanation": "语义：「电话」是通信工具，不能用一小部分来代表。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：「钥匙」是开锁的工具，不能用一小部分来代表。"}, {"text": "大门", "is_correct": false, "explanation": "搭配：「代表」的对象应是群体或整体，不能说代表大门。"}], "explanations": {"总体": "「总体」是被代表的整体，与「小部分代表」的语境相符。", "电话": "语义：「电话」是通信工具，不能用一小部分来代表。", "钥匙": "语义：「钥匙」是开锁的工具，不能用一小部分来代表。", "大门": "搭配：「代表」的对象应是群体或整体，不能说代表大门。"}, "sentence_index": 6, "correct_answer": "总体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把总体拿起来喝了。", "explanation": "这里应该用〈水〉。「总体」是抽象的集合概念，不能当作饮料来喝。"}, {"text": "每个人都是一个总体。", "explanation": "这里应该用〈个体〉。「总体」指许多个体组成的整体，不能用来称呼单个的人。"}, {"text": "他一口气把总体吃完了。", "explanation": "这里应该用〈饭〉。「总体」是抽象的集合概念，不能当作食物吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本总体里有很多学生。", "corrected_sentence": "这个总体里有很多学生。", "error_description": "错误：「这本总体」；正确：「这个总体」。「总体」是抽象的集合名词，量词应该用「个」。「本」用于书。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们研究的这只总体很大。", "corrected_sentence": "我们研究的这个总体很大。", "error_description": "错误：「这只总体」；正确：「这个总体」。「总体」是抽象的集合名词，指示词应搭配「这个」，「只」用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
