INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93213, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "新闻网是在网上看新闻的地方。", "primary_collocate": null, "pronunciation": "xīn wén wǎng", "ipa": "ɕin⁵⁵ wən³⁵ waŋ²¹⁴", "syllable_count": 3, "sentences": [{"text": "我每天早上都用手机上新闻网看新闻。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新闻网每天都有很多新消息。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在新闻网上看到了昨天的比赛结果。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家新闻网的首页很简单，找新闻很方便。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸喜欢在新闻网上看国家大事。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻网上的照片很清楚，我都看过了。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道哪个新闻网最快吗？", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她睡前习惯打开新闻网看看今天的消息。", "target_word": "新闻网", "complexity_tier": "T3", "furigana": "xīn wén wǎng", "sentence_source": "generated"}, {"text": "这个新闻网有手机软件，用起来很方便。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们去新闻网找一篇关于天气的文章。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家", "label": "量词"}, {"form": "新聞網", "label": "繁体"}], "register": "中性", "sense_fingerprint": "新闻网：读者上网看新闻的网站", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ef20229-854f-45a8-be5e-aab94d82e2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93213, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新闻网", "is_correct": true, "explanation": "正确：“新闻网”指可以在网上看新闻的网站，这里是用手机上这个网站看新闻。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的房间，不能用手机“上”去看新闻。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：“上黑板”指到黑板上写字，与“用手机看新闻”不搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是存放食物的电器，不是可以用手机浏览新闻的地方。"}], "explanations": {"新闻网": "正确：“新闻网”指可以在网上看新闻的网站，这里是用手机上这个网站看新闻。", "厨房": "语义：厨房是做饭的房间，不能用手机“上”去看新闻。", "黑板": "搭配：“上黑板”指到黑板上写字，与“用手机看新闻”不搭配。", "冰箱": "语义：冰箱是存放食物的电器，不是可以用手机浏览新闻的地方。"}, "sentence_index": 0, "correct_answer": "新闻网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天早上把新闻网折起来放进包里。", "explanation": "这里应该用〈报纸〉。折起来放进包里的是纸质报纸；新闻网是网站，不能折叠，也不能放进包里。"}, {"text": "我去新闻网借了一本关于天气的书。", "explanation": "这里应该用〈图书馆〉。借书要去图书馆；新闻网是网站，不是借书的地方。"}, {"text": "这家新闻网每天印刷十万份报纸。", "explanation": "这里应该用〈报社〉。印刷报纸是报社的工作；新闻网是网站，不印刷报纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93213, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新闻网", "is_correct": true, "explanation": "正确：问的是哪个新闻网站消息更新最快，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“最快”用于比较速度或效率，天气不能这样比较。"}, {"text": "贵报", "is_correct": false, "explanation": "语域：“贵报”是书信中对他人报纸的敬称，用在口语提问里不合适。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是地理事物，不能说哪一个海洋最快。"}], "explanations": {"新闻网": "正确：问的是哪个新闻网站消息更新最快，符合语境。", "天气": "语义：“最快”用于比较速度或效率，天气不能这样比较。", "贵报": "语域：“贵报”是书信中对他人报纸的敬称，用在口语提问里不合适。", "海洋": "语义：海洋是地理事物，不能说哪一个海洋最快。"}, "sentence_index": 6, "correct_answer": "新闻网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生在新闻网里给病人看病。", "explanation": "这里应该用〈医院〉。给病人看病要在医院里进行；新闻网是网站，不能用来看病。"}, {"text": "我去新闻网寄了一封信。", "explanation": "这里应该用〈邮局〉。寄信要去邮局；新闻网是网站，不是寄信的地方。"}, {"text": "新闻网里可以剪头发。", "explanation": "这里应该用〈理发店〉。剪头发要在理发店进行；新闻网是网站，不能剪头发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93213, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市有一本新闻网很有名。", "corrected_sentence": "这个城市有一家新闻网很有名。", "error_description": "量词错误：新闻网是机构式网站，应该用量词“家”，不能用“本”（“本”用于书册）。正确说法是“一家新闻网”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93213, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个新闻网更新地很快。", "corrected_sentence": "这个新闻网更新得很快。", "error_description": "补语标记错误：“更新”后的程度补语应用“得”，不能用“地”（“地”用于修饰动词的状语）。正确说法是“更新得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
