INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93214, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "发布和传播新闻的网站。", "primary_collocate": null, "pronunciation": "xīn wén wǎng", "ipa": "ɕin⁵⁵ wən³⁵ waŋ²¹⁴", "syllable_count": 3, "sentences": [{"text": "这家新闻网刚刚发布了一条重要消息。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻网的记者每天都在外面采访。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新闻网是去年办的，现在很有名。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻网把这件事发给了全国的读者。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的新闻网每天更新五十多条新闻。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家新闻网请了很多有经验的记者。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻网发出了一个错误的消息，后来改过了。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王大学毕业后，进了一家大型新闻网。", "target_word": "新闻网", "complexity_tier": "T3", "furigana": "xīn wén wǎng", "sentence_source": "generated"}, {"text": "这个新闻网的编辑正在写今天的头条。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人都转发了新闻网的这篇报道。", "target_word": "新闻网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家", "label": "量词"}, {"form": "新聞網", "label": "繁体"}], "register": "中性", "sense_fingerprint": "新闻网：发布、传播新闻的媒体网站", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ef20229-854f-45a8-be5e-aab94d82e2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93214, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新闻网", "is_correct": true, "explanation": "正确：发布消息的是提供新闻的网站，这里“刚刚发布了一条重要消息”符合语境。"}, {"text": "茶杯", "is_correct": false, "explanation": "语义：茶杯是喝茶用的器具，不会“发布”消息。"}, {"text": "贵社", "is_correct": false, "explanation": "语域：“贵社”是书面敬称，用于称呼对方的公司，不用于第三方的叙述。"}, {"text": "茶馆", "is_correct": false, "explanation": "语义：茶馆是供人喝茶的场所，不是发布重要消息的机构。"}], "explanations": {"新闻网": "正确：发布消息的是提供新闻的网站，这里“刚刚发布了一条重要消息”符合语境。", "茶杯": "语义：茶杯是喝茶用的器具，不会“发布”消息。", "贵社": "语域：“贵社”是书面敬称，用于称呼对方的公司，不用于第三方的叙述。", "茶馆": "语义：茶馆是供人喝茶的场所，不是发布重要消息的机构。"}, "sentence_index": 0, "correct_answer": "新闻网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新闻网每天做很多好吃的菜。", "explanation": "这里应该用〈厨师〉。做菜的是厨师；新闻网是发布新闻的网站，不做菜。"}, {"text": "新闻网每天给病人看病。", "explanation": "这里应该用〈医生〉。给病人看病的是医生；新闻网不看病。"}, {"text": "新闻网每天开车送客人去机场。", "explanation": "这里应该用〈司机〉。开车送人的是司机；新闻网不能开车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新闻网", "is_correct": true, "explanation": "正确：新闻网是发布消息的机构，可以发出消息，符合语境。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子不能“发出消息”，句子说的是媒体发布了错误信息。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会发出消息，与“发出一个错误的消息”的语境冲突。"}, {"text": "贵府", "is_correct": false, "explanation": "语域：“贵府”是对他人家庭的敬称，多用于书信，不能用作叙述句的主语。"}], "explanations": {"新闻网": "正确：新闻网是发布消息的机构，可以发出消息，符合语境。", "鞋子": "语义：鞋子不能“发出消息”，句子说的是媒体发布了错误信息。", "窗户": "语义：窗户不会发出消息，与“发出一个错误的消息”的语境冲突。", "贵府": "语域：“贵府”是对他人家庭的敬称，多用于书信，不能用作叙述句的主语。"}, "sentence_index": 6, "correct_answer": "新闻网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上都去新闻网买菜。", "explanation": "这里应该用〈菜市场〉。买菜要去菜市场；新闻网是发布新闻的网站，不卖菜。"}, {"text": "新闻网每周一都举行升旗仪式。", "explanation": "这里应该用〈学校〉。升旗仪式是学校的活动；新闻网是网站，不能举行升旗仪式。"}, {"text": "新闻网里可以剪头发。", "explanation": "这里应该用〈理发店〉。剪头发要在理发店进行；新闻网是网站，不能剪头发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只新闻网昨天发布了很多消息。", "corrected_sentence": "这家新闻网昨天发布了很多消息。", "error_description": "量词错误：新闻网是机构式网站，应该用量词“家”，不能用“只”（“只”多用于动物等）。正确说法是“这家新闻网”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家新闻网报道地很仔细。", "corrected_sentence": "这家新闻网报道得很仔细。", "error_description": "补语标记错误：“报道”后的程度补语应用“得”，不能用“地”（“地”用于修饰动词的状语）。正确说法是“报道得很仔细”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
