INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93215, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赶是跑得快一点，追上前面的。", "primary_collocate": null, "pronunciation": "gǎn", "ipa": "kan˨˩˦", "syllable_count": 1, "sentences": [{"text": "他跑在前面，我在后面使劲赶。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的同学跑得快，我拼命赶。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我骑车去赶前面的朋友。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先走，我在后面赶你。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在跑，小明在最后拼命赶。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走得太快，我赶了很久。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥跑在前面，弟弟在后面赶。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跑得慢，只能在后面赶。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中，他在后面拼命赶前面的选手。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们已经走远了，快去赶。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赶了", "label": "体标"}, {"form": "赶过", "label": "体标"}, {"form": "赶上", "label": "复合"}, {"form": "趕", "label": "繁体"}], "register": "口语", "sense_fingerprint": "加快脚步追赶前面的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c5916a-9e2c-4e57-852e-1ec8e059930b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93215, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赶", "is_correct": true, "explanation": "赶（gǎn）指快步追上前面的人，是本题的目标词。"}, {"text": "砍", "is_correct": false, "explanation": "kǎn（砍）与 gǎn 声母不同（k/g），声调相同，意思是用刀斧砍。"}, {"text": "港", "is_correct": false, "explanation": "gǎng（港）与 gǎn 韵尾不同（ng/n），声调相同，意思是港口。"}, {"text": "干", "is_correct": false, "explanation": "gàn（干）与 gǎn 声调不同，意思是做、干活。"}], "explanations": {"赶": "赶（gǎn）指快步追上前面的人，是本题的目标词。", "砍": "kǎn（砍）与 gǎn 声母不同（k/g），声调相同，意思是用刀斧砍。", "港": "gǎng（港）与 gǎn 韵尾不同（ng/n），声调相同，意思是港口。", "干": "gàn（干）与 gǎn 声调不同，意思是做、干活。"}, "sentence_index": null, "correct_answer": "赶"}, "level_3": {"options": [{"text": "赶", "is_correct": true, "explanation": "赶：加快脚步追上，符合「我在后面使劲赶」的语境。"}, {"text": "写", "is_correct": false, "explanation": "语义：「写」与前面的「跑」和「使劲」语境不合。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」的对象是食物，不说「使劲煮」。"}, {"text": "吐", "is_correct": false, "explanation": "语义：「吐」与追赶跑步的语境毫不相干。"}], "explanations": {"赶": "赶：加快脚步追上，符合「我在后面使劲赶」的语境。", "写": "语义：「写」与前面的「跑」和「使劲」语境不合。", "煮": "搭配：「煮」的对象是食物，不说「使劲煮」。", "吐": "语义：「吐」与追赶跑步的语境毫不相干。"}, "sentence_index": 0, "correct_answer": "赶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他赶了一杯茶。", "explanation": "这里应该用〈泡〉。泡茶要说泡，赶只指快步追上前面的人，不能用于茶。"}, {"text": "我在车站赶了你半个小时。", "explanation": "这里应该用〈等〉。赶表示快步追上，等人要说等，赶不表示等待。"}, {"text": "他赶了一会儿电影。", "explanation": "这里应该用〈看〉。看电影要说看，赶表示快步追上或驱赶，不用于看电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93215, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赶", "is_correct": true, "explanation": "赶（gǎn）指快步追上前面的人，是本题的目标词。"}, {"text": "喊", "is_correct": false, "explanation": "hǎn（喊）与 gǎn 声母不同（h/g），声调相同，意思是呼喊。"}, {"text": "搞", "is_correct": false, "explanation": "gǎo（搞）与 gǎn 韵尾不同（o/n），声调相同，意思是做、弄。"}, {"text": "板", "is_correct": false, "explanation": "bǎn（板）与 gǎn 声母不同（b/g），声调相同，意思是木板。"}, {"text": "毯", "is_correct": false, "explanation": "tǎn（毯）与 gǎn 声母不同（t/g），声调相同，意思是毯子。"}], "explanations": {"赶": "赶（gǎn）指快步追上前面的人，是本题的目标词。", "喊": "hǎn（喊）与 gǎn 声母不同（h/g），声调相同，意思是呼喊。", "搞": "gǎo（搞）与 gǎn 韵尾不同（o/n），声调相同，意思是做、弄。", "板": "bǎn（板）与 gǎn 声母不同（b/g），声调相同，意思是木板。", "毯": "tǎn（毯）与 gǎn 声母不同（t/g），声调相同，意思是毯子。"}, "sentence_index": null, "correct_answer": "赶"}, "level_3": {"options": [{"text": "赶", "is_correct": true, "explanation": "赶：加快脚步追赶，符合「弟弟在后面赶」的语境。"}, {"text": "扔", "is_correct": false, "explanation": "配价：「扔」需要宾语，「在后面扔」说不完整。"}, {"text": "睡", "is_correct": false, "explanation": "语义：「睡」与弟弟追赶哥哥的情境不合。"}, {"text": "戴", "is_correct": false, "explanation": "配价：「戴」需要宾语（帽子、眼镜等），此处不成句。"}], "explanations": {"赶": "赶：加快脚步追赶，符合「弟弟在后面赶」的语境。", "扔": "配价：「扔」需要宾语，「在后面扔」说不完整。", "睡": "语义：「睡」与弟弟追赶哥哥的情境不合。", "戴": "配价：「戴」需要宾语（帽子、眼镜等），此处不成句。"}, "sentence_index": 6, "correct_answer": "赶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每周末都去赶图书馆。", "explanation": "这里应该用〈泡〉。去图书馆待着、消磨时间，口语可说泡图书馆；赶只指快步追上前面的人，不能用于图书馆。"}, {"text": "车上赶满了乘客。", "explanation": "这里应该用〈挤〉。挤满乘客要说挤，赶用于追赶或驱赶。"}, {"text": "他赶了一幅画到墙上。", "explanation": "这里应该用〈挂〉。把画挂到墙上要说挂，赶表示快步追上或驱赶，不用于挂画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我终于赶到了他。", "corrected_sentence": "我终于赶上了他。", "error_description": "「赶到」表示到达某个地点，不能带人作宾语表示追上，应说「赶上」，即「我终于赶上了他」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我赶了上前面的车。", "corrected_sentence": "我赶上了前面的车。", "error_description": "「赶上」是动补结构，「了」应放在补语「上」之后，说「赶上了」，不能插在「赶」和「上」之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
