INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93216, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "快走追上；加快行动以免迟到。", "primary_collocate": null, "pronunciation": "gǎn", "ipa": "kan˨˩˦", "syllable_count": 1, "sentences": [{"text": "我要赶八点的火车。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑着去赶公共汽车。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要赶时间，快走吧。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天早上我要赶飞机。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早起，赶第一班地铁。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，大家都赶着回家。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点儿走，我们要赶末班车。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了赶最后一班车，她跑了起来。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说别迟到，我们得早点赶车。", "target_word": "赶", "complexity_tier": "T3", "furigana": "lǎoshī shuō bié chídào wǒmen děi zǎo diǎn gǎn chē", "sentence_source": "generated"}, {"text": "他想赶在天黑前到家。", "target_word": "赶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赶了", "label": "体标"}, {"form": "赶着", "label": "体标"}, {"form": "赶快", "label": "复合"}, {"form": "趕", "label": "繁体"}], "register": "口语", "sense_fingerprint": "加快行动，赶上车、船或时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c5916a-9e2c-4e57-852e-1ec8e059930b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93216, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赶", "is_correct": true, "explanation": "赶（gǎn）指加快行动赶上车、船或时间，是本题的目标词。"}, {"text": "喊", "is_correct": false, "explanation": "hǎn（喊）与 gǎn 声母不同（h/g），声调相同，意思是呼喊。"}, {"text": "港", "is_correct": false, "explanation": "gǎng（港）与 gǎn 韵尾不同（ng/n），声调相同，意思是港口。"}, {"text": "板", "is_correct": false, "explanation": "bǎn（板）与 gǎn 声母不同（b/g），声调相同，意思是木板。"}], "explanations": {"赶": "赶（gǎn）指加快行动赶上车、船或时间，是本题的目标词。", "喊": "hǎn（喊）与 gǎn 声母不同（h/g），声调相同，意思是呼喊。", "港": "gǎng（港）与 gǎn 韵尾不同（ng/n），声调相同，意思是港口。", "板": "bǎn（板）与 gǎn 声母不同（b/g），声调相同，意思是木板。"}, "sentence_index": null, "correct_answer": "赶"}, "level_3": {"options": [{"text": "赶", "is_correct": true, "explanation": "赶：加快行动赶上火车，符合「我要赶八点的火车」的语境。"}, {"text": "写", "is_correct": false, "explanation": "语义：「写」不能用于火车，句子说不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」与「火车」不搭，句子说不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」的对象不是交通工具，不说洗火车。"}], "explanations": {"赶": "赶：加快行动赶上火车，符合「我要赶八点的火车」的语境。", "写": "语义：「写」不能用于火车，句子说不通。", "吃": "语义：「吃」与「火车」不搭，句子说不通。", "洗": "搭配：「洗」的对象不是交通工具，不说洗火车。"}, "sentence_index": 0, "correct_answer": "赶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家都赶座位，场面很乱。", "explanation": "这里应该用〈抢〉。赶表示加快行动去赶车船或时间，抢座位要说抢。"}, {"text": "他赶了一碗饭给妈妈。", "explanation": "这里应该用〈盛〉。盛饭要说盛，赶表示快步追上或加快行动，不能用于盛饭。"}, {"text": "他每天赶房间。", "explanation": "这里应该用〈打扫〉。赶不能带「房间」作宾语，打扫房间要说打扫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93216, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赶", "is_correct": true, "explanation": "赶（gǎn）指加快行动赶上车、船或时间，是本题的目标词。"}, {"text": "砍", "is_correct": false, "explanation": "kǎn（砍）与 gǎn 声母不同（k/g），声调相同，意思是用刀斧砍。"}, {"text": "干", "is_correct": false, "explanation": "gàn（干）与 gǎn 声调不同，意思是做、干活。"}, {"text": "毯", "is_correct": false, "explanation": "tǎn（毯）与 gǎn 声母不同（t/g），声调相同，意思是毯子。"}, {"text": "搞", "is_correct": false, "explanation": "gǎo（搞）与 gǎn 韵尾不同（o/n），声调相同，意思是做、弄。"}], "explanations": {"赶": "赶（gǎn）指加快行动赶上车、船或时间，是本题的目标词。", "砍": "kǎn（砍）与 gǎn 声母不同（k/g），声调相同，意思是用刀斧砍。", "干": "gàn（干）与 gǎn 声调不同，意思是做、干活。", "毯": "tǎn（毯）与 gǎn 声母不同（t/g），声调相同，意思是毯子。", "搞": "gǎo（搞）与 gǎn 韵尾不同（o/n），声调相同，意思是做、弄。"}, "sentence_index": null, "correct_answer": "赶"}, "level_3": {"options": [{"text": "赶", "is_correct": true, "explanation": "赶：加快行动赶上车，符合「我们要赶末班车」的语境。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」的对象是食物，不说煮末班车。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的对象是饮料，不说喝末班车。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」与「末班车」毫不相干。"}], "explanations": {"赶": "赶：加快行动赶上车，符合「我们要赶末班车」的语境。", "煮": "搭配：「煮」的对象是食物，不说煮末班车。", "喝": "搭配：「喝」的对象是饮料，不说喝末班车。", "唱": "语义：「唱」与「末班车」毫不相干。"}, "sentence_index": 6, "correct_answer": "赶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车上赶满了乘客。", "explanation": "这里应该用〈挤〉。挤满乘客要说挤，赶用于赶上车船或时间。"}, {"text": "他赶了一下午的花。", "explanation": "这里应该用〈浇〉。浇花要说浇，赶表示快步追上或加快行动，不能用于花草。"}, {"text": "他每周末都去赶公园。", "explanation": "这里应该用〈逛〉。去公园玩要说逛，赶表示快步追上或加快行动，不能用于公园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我要赶到八点的火车。", "corrected_sentence": "我要赶上八点的火车。", "error_description": "「赶到」表示到达某地，不能接车次时间。赶上车次应说「赶上」，即「我要赶上八点的火车」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "为了赶了最后一班地铁，他跑了起来。", "corrected_sentence": "为了赶最后一班地铁，他跑了起来。", "error_description": "「为了」引导的目的小句里不用「了」，应说「为了赶最后一班地铁」，不说「为了赶了最后一班地铁」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
