INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93217, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "日场是白天的那一场电影或表演。", "primary_collocate": null, "pronunciation": "rì chǎng", "ipa": "ɻʅ˥˩ ʈʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "日场在白天演，晚上不用出门。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下午有日场，我们去看吧。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部戏的日场座位很多。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她带女儿看了日场，三点就结束了。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日场结束后，我们去公园走了走。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日的日场票很快就卖完了。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友说日场人少，很安静。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想看日场，不想看晚上的。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个剧团一周只演两次日场。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日场几点开始？我想带爷爷去看。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日场电影", "label": "复合"}, {"form": "日场票", "label": "复合"}], "register": "中性", "sense_fingerprint": "白天的一场电影或表演", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0806fb53-8715-4a01-946f-96193aca6881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93217, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日场", "is_correct": true, "explanation": "正确答案：日场（rì chǎng），指白天的一场电影或表演。"}, {"text": "日常", "is_correct": false, "explanation": "cháng（第二声）与 chǎng（第三声）声调不同，意思是日常、每天都有的。"}, {"text": "立场", "is_correct": false, "explanation": "lì 与 rì 声母不同（l 与 r），意思是立场、态度。"}, {"text": "日程", "is_correct": false, "explanation": "chéng 与 chǎng 韵尾不同（eng 与 ang），意思是日程、安排。"}, {"text": "日产", "is_correct": false, "explanation": "chǎn 与 chǎng 韵尾不同（n 与 ng），意思是每天生产的数量。"}, {"text": "入场", "is_correct": false, "explanation": "rù 与 rì 韵母不同（u 与 i），意思是进入场地。"}], "explanations": {"日场": "正确答案：日场（rì chǎng），指白天的一场电影或表演。", "日常": "cháng（第二声）与 chǎng（第三声）声调不同，意思是日常、每天都有的。", "立场": "lì 与 rì 声母不同（l 与 r），意思是立场、态度。", "日程": "chéng 与 chǎng 韵尾不同（eng 与 ang），意思是日程、安排。", "日产": "chǎn 与 chǎng 韵尾不同（n 与 ng），意思是每天生产的数量。", "入场": "rù 与 rì 韵母不同（u 与 i），意思是进入场地。"}, "sentence_index": null, "correct_answer": "日场"}, "level_3": {"options": [{"text": "日场", "is_correct": true, "explanation": "日场指白天的演出场次，与“在白天演”相符。"}, {"text": "夜场", "is_correct": false, "explanation": "语义：夜场在晚上，与“在白天演”矛盾。"}, {"text": "晚场", "is_correct": false, "explanation": "语义：晚场在晚上演，与“在白天演”矛盾。"}, {"text": "午夜场", "is_correct": false, "explanation": "语义：午夜场在深夜，与“在白天演”矛盾。"}], "explanations": {"日场": "日场指白天的演出场次，与“在白天演”相符。", "夜场": "语义：夜场在晚上，与“在白天演”矛盾。", "晚场": "语义：晚场在晚上演，与“在白天演”矛盾。", "午夜场": "语义：午夜场在深夜，与“在白天演”矛盾。"}, "sentence_index": 0, "correct_answer": "日场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋楼的日场朝南，冬天很暖和。", "explanation": "这里应该用〈日照〉。日场指白天的演出场次，说房子的光照要用日照。"}, {"text": "这个湖边的日场很安静，适合散步。", "explanation": "这里应该用〈白天〉。日场指白天演出的场次，不能用来表示湖边的时段。"}, {"text": "她带儿子看了午夜日场。", "explanation": "这里应该用〈午夜场〉。日场指白天的场次，午夜的场次应说“午夜场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日场", "is_correct": true, "explanation": "日场指白天的演出场次，可以是人少、安静的场次，与句中描述相符。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会通常热闹，与“很安静”矛盾。"}, {"text": "球赛", "is_correct": false, "explanation": "语义：球赛现场观众喧闹，与“很安静”矛盾。"}, {"text": "庆典", "is_correct": false, "explanation": "搭配：庆典一般说人多、热闹，不与“人少，很安静”搭配。"}], "explanations": {"日场": "日场指白天的演出场次，可以是人少、安静的场次，与句中描述相符。", "演唱会": "语义：演唱会通常热闹，与“很安静”矛盾。", "球赛": "语义：球赛现场观众喧闹，与“很安静”矛盾。", "庆典": "搭配：庆典一般说人多、热闹，不与“人少，很安静”搭配。"}, "sentence_index": 6, "correct_answer": "日场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的日场工作很忙，经常加班。", "explanation": "这里应该用〈日常〉。日场是演出场次，不表示每天的工作状态。"}, {"text": "这座钢厂的日场产量是两万吨。", "explanation": "这里应该用〈日产〉。日产指每天生产的数量，日场指演出场次，表示每天的产量要说日产。"}, {"text": "他在这件事上的日场很明确。", "explanation": "这里应该用〈立场〉。立场指对事情的态度，日场是演出场次，不能用“明确”来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天的日场晚上九点开始，我们去看吧。", "corrected_sentence": "今天的日场下午两点开始，我们去看吧。", "error_description": "“日场”是白天的演出场次，不会在晚上九点开始。晚上的场次要说“晚场”或“夜场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部戏的日场在晚上十点开始。", "corrected_sentence": "这部戏的日场在下午三点开始。", "error_description": "“日场”指白天的演出场次，不能在晚上十点开始。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
