INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93218, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "戏剧或电影在白天的演出场次。", "primary_collocate": null, "pronunciation": "rì chǎng", "ipa": "ɻʅ˥˩ ʈʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这部电影有日场，下午两点开始。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的日场比晚场便宜很多。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家剧院每天都有日场演出。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们更喜欢看日场，因为不用太晚回家。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日场两点开始，你可以先吃午饭。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看过昨天的日场，说很好看。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日场的观众大多是老人和孩子。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你下午有空的话，去看日场吧。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的日场已经卖完了票。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢晚场，所以订了日场。", "target_word": "日场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日场电影", "label": "复合"}, {"form": "日场票", "label": "复合"}], "register": "中性", "sense_fingerprint": "戏剧或电影白天的演出场次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0806fb53-8715-4a01-946f-96193aca6881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93218, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日场", "is_correct": true, "explanation": "正确答案：日场（rì chǎng），指戏剧或电影白天的演出场次。"}, {"text": "日常", "is_correct": false, "explanation": "cháng（第二声）与 chǎng（第三声）声调不同，意思是日常、每天都有的。"}, {"text": "立场", "is_correct": false, "explanation": "lì 与 rì 声母不同（l 与 r），意思是立场、态度。"}, {"text": "日程", "is_correct": false, "explanation": "chéng 与 chǎng 韵尾不同（eng 与 ang），意思是日程、安排。"}, {"text": "日产", "is_correct": false, "explanation": "chǎn 与 chǎng 韵尾不同（n 与 ng），意思是每天生产的数量。"}, {"text": "入场", "is_correct": false, "explanation": "rù 与 rì 韵母不同（u 与 i），意思是进入场地。"}], "explanations": {"日场": "正确答案：日场（rì chǎng），指戏剧或电影白天的演出场次。", "日常": "cháng（第二声）与 chǎng（第三声）声调不同，意思是日常、每天都有的。", "立场": "lì 与 rì 声母不同（l 与 r），意思是立场、态度。", "日程": "chéng 与 chǎng 韵尾不同（eng 与 ang），意思是日程、安排。", "日产": "chǎn 与 chǎng 韵尾不同（n 与 ng），意思是每天生产的数量。", "入场": "rù 与 rì 韵母不同（u 与 i），意思是进入场地。"}, "sentence_index": null, "correct_answer": "日场"}, "level_3": {"options": [{"text": "日场", "is_correct": true, "explanation": "日场指白天的演出场次，与“下午两点开始”相符。"}, {"text": "晚场", "is_correct": false, "explanation": "语义：晚场在晚上，与“下午两点开始”矛盾。"}, {"text": "早场", "is_correct": false, "explanation": "语义：早场在上午，与“下午两点开始”矛盾。"}, {"text": "放映厅", "is_correct": false, "explanation": "搭配：“开始”的对象是场次或演出，放映厅是场所，不说它开始。"}], "explanations": {"日场": "日场指白天的演出场次，与“下午两点开始”相符。", "晚场": "语义：晚场在晚上，与“下午两点开始”矛盾。", "早场": "语义：早场在上午，与“下午两点开始”矛盾。", "放映厅": "搭配：“开始”的对象是场次或演出，放映厅是场所，不说它开始。"}, "sentence_index": 0, "correct_answer": "日场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的日场很好，阳光充足。", "explanation": "这里应该用〈日照〉。日场指白天的演出场次，房间的光照要用日照。"}, {"text": "这个公园的日场很安静，适合散步。", "explanation": "这里应该用〈白天〉。日场指白天演出的场次，不能用来表示公园的时段。"}, {"text": "我们订了晚上十点的日场。", "explanation": "这里应该用〈夜场〉。日场指白天的场次，晚上十点的场次应该说夜场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日场", "is_correct": true, "explanation": "日场指白天的场次，观众大多是老人和孩子，与句意相符。"}, {"text": "健身房", "is_correct": false, "explanation": "搭配：健身房里的人是锻炼的人，一般不说“健身房的观众”。"}, {"text": "图书馆", "is_correct": false, "explanation": "搭配：图书馆里的人是读者，不说“图书馆的观众”。"}, {"text": "夜店", "is_correct": false, "explanation": "语义：夜店以年轻人为主，与“观众大多是老人和孩子”矛盾。"}], "explanations": {"日场": "日场指白天的场次，观众大多是老人和孩子，与句意相符。", "健身房": "搭配：健身房里的人是锻炼的人，一般不说“健身房的观众”。", "图书馆": "搭配：图书馆里的人是读者，不说“图书馆的观众”。", "夜店": "语义：夜店以年轻人为主，与“观众大多是老人和孩子”矛盾。"}, "sentence_index": 6, "correct_answer": "日场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的日场生活很忙，每天都要上班。", "explanation": "这里应该用〈日常〉。日场是演出场次，不表示每天的生活状态。"}, {"text": "这家工厂的日场能力达到每天一千辆汽车。", "explanation": "这里应该用〈日产〉。日产指每天生产的数量，日场指演出场次，表示工厂产能要用日产能力。"}, {"text": "他在这件事上的日场很坚定。", "explanation": "这里应该用〈立场〉。立场指对事情的态度，日场是演出场次，不能用“坚定”来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们看了晚上十点的日场。", "corrected_sentence": "我们看了晚上十点的夜场。", "error_description": "“日场”是白天的演出场次，晚上十点的场次应说“夜场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家剧院的日场在半夜开始。", "corrected_sentence": "这家剧院的日场在下午两点开始。", "error_description": "“日场”指白天的演出场次，不能在半夜开始。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
