INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93220, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，抓紧时间，立刻。", "primary_collocate": null, "pronunciation": "gǎn jǐn", "ipa": "kan˨˩˦ tɕin˨˩˦", "syllable_count": 2, "sentences": [{"text": "时间不多了，你赶紧把作业写完。", "target_word": "赶紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药要趁热喝，赶紧喝吧。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机没电了，我赶紧找充电器。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人快到了，赶紧把房间收拾一下。", "target_word": "赶紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有水，大家赶紧躲开。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看见老人摔倒，他赶紧跑过去扶。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作业明天要交，今晚得赶紧做完。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想起约会的事，赶紧换衣服出门。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汤快洒出来了，她赶紧关火。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨越下越大，我们赶紧找地方躲雨。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "抓紧时间，立刻去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39432ac-a2b3-4cb2-a82d-341df50f8430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赶紧", "is_correct": true, "explanation": "正确：“你赶紧把作业写完”表示抓紧时间立刻去做，与“时间不多了”相合。"}, {"text": "慢慢", "is_correct": false, "explanation": "语义：“慢慢”表示缓慢，与“时间不多了”的紧迫语境相反。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒然，“白白把作业写完”与催促的语境不合。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词连用，不能用于“你……把作业写完”的催促句。"}], "explanations": {"赶紧": "正确：“你赶紧把作业写完”表示抓紧时间立刻去做，与“时间不多了”相合。", "慢慢": "语义：“慢慢”表示缓慢，与“时间不多了”的紧迫语境相反。", "白白": "语义：“白白”表示徒然，“白白把作业写完”与催促的语境不合。", "从来": "搭配：“从来”多与否定词连用，不能用于“你……把作业写完”的催促句。"}, "sentence_index": 0, "correct_answer": "赶紧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我赶紧生病了。", "explanation": "这里应该用〈突然〉。赶紧表示马上去做某事，不能用来说生病这种不由自主发生的变化。"}, {"text": "他赶紧高兴了一个下午。", "explanation": "这里应该用〈整整〉。赶紧表示马上去做，不能用来说持续一个下午的心情。"}, {"text": "天气赶紧变冷。", "explanation": "这里应该用〈逐渐〉。赶紧表示立即，不能描述气温慢慢变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赶紧", "is_correct": true, "explanation": "正确：“今晚得赶紧做完”表示抓紧时间完成，与“明天要交”的紧迫语境相合。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意地，“今晚得故意做完”与紧迫的语境不合。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与“明天要交”的因果关系不通。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，与“今晚得……做完”的必然性相反。"}], "explanations": {"赶紧": "正确：“今晚得赶紧做完”表示抓紧时间完成，与“明天要交”的紧迫语境相合。", "故意": "语义：“故意”表示有意地，“今晚得故意做完”与紧迫的语境不合。", "竟然": "语义：“竟然”表示出乎意料，与“明天要交”的因果关系不通。", "偶尔": "语义：“偶尔”表示不经常，与“今晚得……做完”的必然性相反。"}, "sentence_index": 6, "correct_answer": "赶紧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们赶紧每年都回老家。", "explanation": "这里应该用〈经常〉。赶紧表示马上去做，不能用来说每年重复发生的事。"}, {"text": "我赶紧没吃过北京烤鸭。", "explanation": "这里应该用〈从来〉。赶紧表示马上去做，不能用来描述一直没有发生过的经历。"}, {"text": "他赶紧三年前就毕业了。", "explanation": "这里应该用〈早就〉。赶紧表示马上去做，不能用来说几年前已经发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很赶紧换衣服出门。", "corrected_sentence": "他赶紧换衣服出门。", "error_description": "程度副词错误：“赶紧”是副词，不能受“很”修饰。应删去“很”，说“赶紧换衣服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下雨了，我们赶紧了去躲雨。", "corrected_sentence": "下雨了，我们赶紧去躲雨。", "error_description": "体标错误：“赶紧”是副词，后面不能直接加“了”。应删去“了”，说“赶紧去躲雨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
