INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93221, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "时时是一次又一次，常常这样。", "primary_collocate": null, "pronunciation": "shí shí", "ipa": "ʂʐ̩˧˥ ʂʐ̩˧˥", "syllable_count": 2, "sentences": [{"text": "他时时提醒自己要多喝水。", "target_word": "时时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈时时想着远方的孩子。", "target_word": "时时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师时时鼓励我们大胆说话。", "target_word": "时时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我时时看手机，眼睛有点累。", "target_word": "时时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗时时回头看主人。", "target_word": "时时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他时时担心考试考不好。", "target_word": "时时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她时时对朋友说谢谢。", "target_word": "时时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子时时问我为什么。", "target_word": "时时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的风时时吹过窗前。", "target_word": "时时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷时时讲起小时候的事。", "target_word": "时时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示动作一次又一次地发生，常常如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088928fc-a436-497e-8711-79f5a28a97a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93221, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时事", "is_correct": false, "explanation": "第二音节 shì 与 shí 声调不同（第四声），意思是时事、近期发生的新闻。"}, {"text": "时时", "is_correct": true, "explanation": "正确：时时 shí shí，意思是一次又一次地、常常。"}, {"text": "事实", "is_correct": false, "explanation": "第一音节 shì 与 shí 声调不同（第四声），意思是事实。"}, {"text": "试试", "is_correct": false, "explanation": "第一音节 shì 与 shí 声调不同（第四声），第二音节为轻声，意思是试一试。"}, {"text": "史实", "is_correct": false, "explanation": "第一音节 shǐ 与 shí 声调不同（第三声），意思是历史上的事实。"}], "explanations": {"时事": "第二音节 shì 与 shí 声调不同（第四声），意思是时事、近期发生的新闻。", "时时": "正确：时时 shí shí，意思是一次又一次地、常常。", "事实": "第一音节 shì 与 shí 声调不同（第四声），意思是事实。", "试试": "第一音节 shì 与 shí 声调不同（第四声），第二音节为轻声，意思是试一试。", "史实": "第一音节 shǐ 与 shí 声调不同（第三声），意思是历史上的事实。"}, "sentence_index": null, "correct_answer": "时时"}, "level_3": {"options": [{"text": "很", "is_correct": false, "explanation": "语义：“很”表示程度，不表示动作反复出现，也不能修饰“提醒”。"}, {"text": "时时", "is_correct": true, "explanation": "正确：“时时”表示一次又一次地，与“提醒自己”的反复含义相符。"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”表示程度最高，一般修饰形容词，不能直接修饰“提醒”这样的动作。"}, {"text": "再也", "is_correct": false, "explanation": "搭配：“再也”必须与否定词连用（如“再也不”），这里没有否定词。"}], "explanations": {"很": "语义：“很”表示程度，不表示动作反复出现，也不能修饰“提醒”。", "时时": "正确：“时时”表示一次又一次地，与“提醒自己”的反复含义相符。", "最": "搭配：“最”表示程度最高，一般修饰形容词，不能直接修饰“提醒”这样的动作。", "再也": "搭配：“再也”必须与否定词连用（如“再也不”），这里没有否定词。"}, "sentence_index": 0, "correct_answer": "时时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我时时去过一次北京。", "explanation": "“时时”表示动作一次又一次地发生，而“去过一次”只发生了一次，二者矛盾，这里不能用“时时”。"}, {"text": "他时时搬进了新房子。", "explanation": "“时时”表示反复发生，而“搬进新房子”是一次性的事，这里不能用“时时”。"}, {"text": "他时时参加了昨天的考试。", "explanation": "“时时”表示反复，而“昨天的考试”只有一次，这里不能用“时时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93221, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "实事", "is_correct": false, "explanation": "第二音节 shì 与 shí 声调不同（第四声），意思是实际的事情。"}, {"text": "石狮", "is_correct": false, "explanation": "第二音节 shī 与 shí 声调不同（第一声），意思是石头雕成的狮子。"}, {"text": "时时", "is_correct": true, "explanation": "正确：时时 shí shí，意思是一次又一次地、常常。"}, {"text": "世事", "is_correct": false, "explanation": "两个音节的声调都与 shí shí 不同（都是第四声），意思是世间的事情。"}], "explanations": {"实事": "第二音节 shì 与 shí 声调不同（第四声），意思是实际的事情。", "石狮": "第二音节 shī 与 shí 声调不同（第一声），意思是石头雕成的狮子。", "时时": "正确：时时 shí shí，意思是一次又一次地、常常。", "世事": "两个音节的声调都与 shí shí 不同（都是第四声），意思是世间的事情。"}, "sentence_index": null, "correct_answer": "时时"}, "level_3": {"options": [{"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，不能修饰“对朋友说谢谢”这类动作。"}, {"text": "时时", "is_correct": true, "explanation": "正确：“时时”表示反复，与“对朋友说谢谢”的重复含义相符。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”是程度副词，一般修饰形容词，不能修饰“说谢谢”。"}, {"text": "极其", "is_correct": false, "explanation": "搭配：“极其”是程度副词，修饰形容词，不能修饰“对朋友说谢谢”这类动作。"}], "explanations": {"非常": "搭配：“非常”是程度副词，不能修饰“对朋友说谢谢”这类动作。", "时时": "正确：“时时”表示反复，与“对朋友说谢谢”的重复含义相符。", "十分": "搭配：“十分”是程度副词，一般修饰形容词，不能修饰“说谢谢”。", "极其": "搭配：“极其”是程度副词，修饰形容词，不能修饰“对朋友说谢谢”这类动作。"}, "sentence_index": 6, "correct_answer": "时时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他时时出生在北京。", "explanation": "“时时”表示反复，而“出生”只发生一次，二者矛盾，这里不能用“时时”。"}, {"text": "这座桥时时在1999年建成。", "explanation": "“时时”表示反复，而“建成”是一次性完成的事，且有具体年份，这里不能用“时时”。"}, {"text": "他时时毕业于北京大学。", "explanation": "“时时”表示反复，而“毕业”是一次性的事，这里不能用“时时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid =