INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93221, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们时时了想起远方的朋友。", "corrected_sentence": "我们时时想起远方的朋友。", "error_description": "错误在于“时时”和动词之间多插了“了”。“时时”是副词，直接修饰动词，中间不能插入“了”。应说“我们时时想起远方的朋友”，不说“我们时时了想起远方的朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93221, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们时时的聊起从前的事。", "corrected_sentence": "我们时时聊起从前的事。", "error_description": "错误在于多加了“的”。“时时”是副词，直接修饰动词，中间不加“的”。应说“时时聊起”，不说“时时的聊起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
