INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93222, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时事", "is_correct": false, "explanation": "第二音节 shì 与 shí 声调不同（第四声），意思是时事、近期发生的新闻。"}, {"text": "试试", "is_correct": false, "explanation": "第一音节 shì 与 shí 声调不同（第四声），第二音节为轻声，意思是试一试。"}, {"text": "时时", "is_correct": true, "explanation": "正确：时时 shí shí，意思是常常、每时每刻。"}, {"text": "史实", "is_correct": false, "explanation": "第一音节 shǐ 与 shí 声调不同（第三声），意思是历史上的事实。"}], "explanations": {"时事": "第二音节 shì 与 shí 声调不同（第四声），意思是时事、近期发生的新闻。", "试试": "第一音节 shì 与 shí 声调不同（第四声），第二音节为轻声，意思是试一试。", "时时": "正确：时时 shí shí，意思是常常、每时每刻。", "史实": "第一音节 shǐ 与 shí 声调不同（第三声），意思是历史上的事实。"}, "sentence_index": null, "correct_answer": "时时"}, "level_3": {"options": [{"text": "千万", "is_correct": false, "explanation": "搭配：“千万”用于祈使、叮嘱，如“千万要小心”，不能用在陈述句里描述他人的持续状态。"}, {"text": "时时", "is_correct": true, "explanation": "正确：“时时”表示经常、随时，与“关心着”所描述的持续状态相符。"}, {"text": "再也", "is_correct": false, "explanation": "搭配：“再也”必须与否定词连用，这里没有否定词。"}, {"text": "差点", "is_correct": false, "explanation": "语义：“差点”表示几乎发生却没有发生，与“关心着”所描述的持续状态相矛盾。"}], "explanations": {"千万": "搭配：“千万”用于祈使、叮嘱，如“千万要小心”，不能用在陈述句里描述他人的持续状态。", "时时": "正确：“时时”表示经常、随时，与“关心着”所描述的持续状态相符。", "再也": "搭配：“再也”必须与否定词连用，这里没有否定词。", "差点": "语义：“差点”表示几乎发生却没有发生，与“关心着”所描述的持续状态相矛盾。"}, "sentence_index": 0, "correct_answer": "时时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天时时搬了家。", "explanation": "“时时”表示反复进行，而“搬家”是一次性的事，且有“昨天”的具体时间，这里不能用“时时”。"}, {"text": "他时时参加了去年的运动会。", "explanation": "“时时”表示反复，而“去年的运动会”只有一次，这里不能用“时时”。"}, {"text": "她时时拿到了博士学位。", "explanation": "“时时”表示反复，而“拿到博士学位”是一次性的成就，这里不能用“时时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93222, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "石狮", "is_correct": false, "explanation": "第二音节 shī 与 shí 声调不同（第一声），意思是石头雕成的狮子。"}, {"text": "时时", "is_correct": true, "explanation": "正确：时时 shí shí，意思是常常、每时每刻。"}, {"text": "实事", "is_correct": false, "explanation": "第二音节 shì 与 shí 声调不同（第四声），意思是实际的事情。"}, {"text": "世事", "is_correct": false, "explanation": "两个音节的声调都与 shí shí 不同（都是第四声），意思是世间的事情。"}], "explanations": {"石狮": "第二音节 shī 与 shí 声调不同（第一声），意思是石头雕成的狮子。", "时时": "正确：时时 shí shí，意思是常常、每时每刻。", "实事": "第二音节 shì 与 shí 声调不同（第四声），意思是实际的事情。", "世事": "两个音节的声调都与 shí shí 不同（都是第四声），意思是世间的事情。"}, "sentence_index": null, "correct_answer": "时时"}, "level_3": {"options": [{"text": "很", "is_correct": false, "explanation": "语义：“很”表示程度，不表示经常发生，也不能修饰“听取”这类动作。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”表示过分的程度，一般修饰形容词，不能修饰“听取”。"}, {"text": "时时", "is_correct": true, "explanation": "正确：“时时”表示经常、随时，与“听取客户的意见”的持续做法相符。"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”表示程度最高，不能直接修饰“听取意见”这类动作。"}], "explanations": {"很": "语义：“很”表示程度，不表示经常发生，也不能修饰“听取”这类动作。", "太": "搭配：“太”表示过分的程度，一般修饰形容词，不能修饰“听取”。", "时时": "正确：“时时”表示经常、随时，与“听取客户的意见”的持续做法相符。", "最": "搭配：“最”表示程度最高，不能直接修饰“听取意见”这类动作。"}, "sentence_index": 6, "correct_answer": "时时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座大楼时时在2010年落成。", "explanation": "“时时”表示反复，而“落成”是一次性完成的事，且有具体年份，这里不能用“时时”。"}, {"text": "他时时出生在上海。", "explanation": "“时时”表示反复，而“出生”只发生一次，这里不能用“时时”。"}, {"text": "我时时考上了大学。", "explanation": "“时时”表示反复，而“考上大学”是一次性的事，这里不能用“时时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们时时的记住老师的教导。", "corrected_sentence": "我们时时记住老师的教导。", "error_description": "错误在于“时时”后多加了“的”。“时时”是副词，直接修饰动词，中间不加“的”。应说“我们时时记住老师的教导”，不说“我们时时的记住老师的教导”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们时时的惦记着远方的亲人。", "corrected_sentence": "他们时时惦记着远方的亲人。", "error_description": "错误在于多加了“的”。“时时”是副词，直接修饰动词，中间不加“的”。应说“时时惦记着”，不说“时时的惦记着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
