INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93223, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "转换是从一样变成另一样。", "primary_collocate": null, "pronunciation": "zhuǎn huàn", "ipa": "ʈʂwan˨˩˦ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "这台仪器可以在两种模式之间转换。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能把图片转换成文字。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个按钮可以把中文转换成英文。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很快转换了角色，开始认真工作。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以用遥控器转换频道。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把美元转换成人民币要去银行。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器能把太阳能转换为电能。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从工作到休息，他转换得很快。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家要学会转换思路，别总想老办法。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一亮，场景转换了，演员走上舞台。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转换了", "label": "体标"}, {"form": "转换过", "label": "体标"}, {"form": "转换器", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把一样东西换成另一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '599121f6-7aa3-4196-b677-939c72d4cb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93223, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转换", "is_correct": true, "explanation": "「在……之间转换」表示在两种状态之间切换，符合语境。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：「生产」的对象是产品，不能用于两种模式之间。"}, {"text": "打开", "is_correct": false, "explanation": "配价：「打开」要接具体的东西，不能用「在……之间」来表示位置关系。"}, {"text": "调查", "is_correct": false, "explanation": "语义：「调查」是了解情况，与仪器模式的切换无关。"}], "explanations": {"转换": "「在……之间转换」表示在两种状态之间切换，符合语境。", "生产": "搭配：「生产」的对象是产品，不能用于两种模式之间。", "打开": "配价：「打开」要接具体的东西，不能用「在……之间」来表示位置关系。", "调查": "语义：「调查」是了解情况，与仪器模式的切换无关。"}, "sentence_index": 0, "correct_answer": "转换"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快转换了衣服，开始认真工作。", "explanation": "这里应该用〈换〉。换衣服是更换，不是把一样东西变成另一样，不说「转换衣服」。"}, {"text": "他很快转换了桌子，开始认真工作。", "explanation": "这里应该用〈搬〉。「转换」用于抽象的形式、状态或角色，不能用于搬动具体的家具。"}, {"text": "他很快转换了身高，开始认真工作。", "explanation": "这里应该用〈长〉。身高的变化说「长高」，「转换」不能用于身体的生长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93223, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转换", "is_correct": true, "explanation": "「把……转换为……」表示变成另一种能量，符合语境。"}, {"text": "消耗", "is_correct": false, "explanation": "语义：「消耗」是用掉，不是变成另一种能量。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：「翻译」是换成另一种语言，不是能量形式的改变，句意不通。"}, {"text": "分解", "is_correct": false, "explanation": "语义：「分解」指拆成部分，不是变成另一种能量。"}], "explanations": {"转换": "「把……转换为……」表示变成另一种能量，符合语境。", "消耗": "语义：「消耗」是用掉，不是变成另一种能量。", "翻译": "语义：「翻译」是换成另一种语言，不是能量形式的改变，句意不通。", "分解": "语义：「分解」指拆成部分，不是变成另一种能量。"}, "sentence_index": 6, "correct_answer": "转换"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把牙齿转换了，第二天就去看牙医。", "explanation": "这里应该用〈拔〉。拔牙是把牙取出，不是形式或状态的变化，不能用「转换」。"}, {"text": "妈妈每天都转换窗户，屋里很亮。", "explanation": "这里应该用〈擦〉。「转换」指形式或状态的变化，擦窗户不能用「转换」。"}, {"text": "这个月他的体重转换了三公斤。", "explanation": "这里应该用〈增加〉。体重的增减要说增加或减少，「转换」不能表示数量的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93223, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个程序能把声音转换到文字。", "corrected_sentence": "这个程序能把声音转换成文字。", "error_description": "错误：「转换到文字」；正确：「转换成文字」。表示变成另一种东西，要用「成」或「为」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93223, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经把教室转换了舞台。", "corrected_sentence": "他已经把教室转换成了舞台。", "error_description": "错误：「转换了舞台」缺少补语「成」；正确：「转换成了舞台」。表示变成另一种东西，要用「成」连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
