INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93224, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改变，从一种形式、状态变为另一种。", "primary_collocate": null, "pronunciation": "zhuǎn huàn", "ipa": "ʈʂwan˨˩˦ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "植物能把光转换成自己需要的能量。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池把化学能转换成电能。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把旧的想法转换成新的办法。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏可以在不同的模式之间转换。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作方式转换得很顺利。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从夏天到秋天，天气转换得很快。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑可以把文件转换成别的格式。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，手机的语言怎么转换成中文？", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经把失败的经验转换成了前进的动力。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度传感器能把热量转换成数字信号。", "target_word": "转换", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转换了", "label": "体标"}, {"form": "转换过", "label": "体标"}, {"form": "转换器", "label": "复合词"}], "register": "中性", "sense_fingerprint": "形式或状态发生改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '599121f6-7aa3-4196-b677-939c72d4cb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转换", "is_correct": true, "explanation": "「把光转换成能量」表示光变为能量，符合语境。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：「翻译」是换成另一种语言，不是能量形式的变化，句意不通。"}, {"text": "消耗", "is_correct": false, "explanation": "语义：「消耗」是用掉，不是变成另一种形式。"}, {"text": "分离", "is_correct": false, "explanation": "语义：「分离」是把东西分开，光不会被分开成能量。"}], "explanations": {"转换": "「把光转换成能量」表示光变为能量，符合语境。", "翻译": "语义：「翻译」是换成另一种语言，不是能量形式的变化，句意不通。", "消耗": "语义：「消耗」是用掉，不是变成另一种形式。", "分离": "语义：「分离」是把东西分开，光不会被分开成能量。"}, "sentence_index": 0, "correct_answer": "转换"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都转换不同的朋友。", "explanation": "这里应该用〈换〉。「转换」指形式或状态的变化，换朋友不能用「转换」。"}, {"text": "他在树上转换了苹果。", "explanation": "这里应该用〈摘〉。「转换」指变成另一种形式，摘苹果不能用「转换」。"}, {"text": "班里转换了十个新同学。", "explanation": "这里应该用〈招〉。新同学是招收来的，「转换」不能用于增加人员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转换", "is_correct": true, "explanation": "「把文件转换成……格式」表示改变文件的格式，符合语境。"}, {"text": "删除", "is_correct": false, "explanation": "语义：「删除」是去掉文件，不是改变格式。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：打印的结果是纸张，不能说「把文件打印成别的格式」。"}, {"text": "发送", "is_correct": false, "explanation": "搭配：「发送」是传递文件，不会改变文件本身的格式。"}], "explanations": {"转换": "「把文件转换成……格式」表示改变文件的格式，符合语境。", "删除": "语义：「删除」是去掉文件，不是改变格式。", "打印": "搭配：打印的结果是纸张，不能说「把文件打印成别的格式」。", "发送": "搭配：「发送」是传递文件，不会改变文件本身的格式。"}, "sentence_index": 6, "correct_answer": "转换"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把旧书转换了，全部扔进了垃圾箱。", "explanation": "这里应该用〈扔〉。扔掉东西不是形式的变化，不能用「转换」。"}, {"text": "师傅很快转换了这辆自行车的车铃。", "explanation": "这里应该用〈换〉。换车铃是更换零件，不是形式或状态的变化，不能用「转换」。"}, {"text": "妈妈去超市转换了三斤苹果。", "explanation": "这里应该用〈买〉。购买东西要用「买」，「转换」不表示交易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种材料能把热量转换到电能。", "corrected_sentence": "这种材料能把热量转换为电能。", "error_description": "错误：「转换到电能」；正确：「转换为电能」。表示变成另一种形式，要用「为」或「成」，不用「到」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项技术已经把光线转换了信号。", "corrected_sentence": "这项技术已经把光线转换成了信号。", "error_description": "错误：「转换了信号」缺少补语「成」；正确：「转换成了信号」。表示变成另一种形式，要用「成」连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93225, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "正确：白天与晚间（太阳下山以后）相对，二者是一对反义词。"}, {"text": "中午", "is_correct": false, "explanation": "中午属于白天之内，与“晚间”没有对立关系，不构成反义。"}, {"text": "上午", "is_correct": false, "explanation": "上午是白天的前半段，不是与“晚间”相对的词。"}, {"text": "周末", "is_correct": false, "explanation": "周末指星期六、星期日，与“晚间”的时段没有对立关系。"}], "correct_answer": "白天", "explanations": {"白天": "正确：白天与晚间（太阳下山以后）相对，二者是一对反义词。", "中午": "中午属于白天之内，与“晚间”没有对立关系，不构成反义。", "上午": "上午是白天的前半段，不是与“晚间”相对的词。", "周末": "周末指星期六、星期日，与“晚间”的时段没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93225, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "正确：白天与晚间（太阳下山以后）相对，二者是一对反义词。"}, {"text": "下午", "is_correct": false, "explanation": "下午属于白天的一部分，与“晚间”没有对立关系，不构成反义。"}, {"text": "星期三", "is_correct": false, "explanation": "星期三指一周中的某一天，与“晚间”的时段没有对立关系。"}, {"text": "春节", "is_correct": false, "explanation": "春节指农历新年，与“晚间”没有对立关系。"}], "correct_answer": "白天", "explanations": {"白天": "正确：白天与晚间（太阳下山以后）相对，二者是一对反义词。", "下午": "下午属于白天的一部分，与“晚间”没有对立关系，不构成反义。", "星期三": "星期三指一周中的某一天，与“晚间”的时段没有对立关系。", "春节": "春节指农历新年，与“晚间”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93225, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "晚间是太阳下山以后的时候。", "primary_collocate": null, "pronunciation": "wǎn jiān", "ipa": "wan˨˩ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "晚间天黑了，路上的车少了。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚间我常常在家看书。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山了，晚间的风有点凉。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的晚间，大家喜欢在外面走走。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚间路灯都亮了，请小心开车。", "target_word": "晚间", "complexity_tier": "T3", "furigana": "wǎn jiān", "sentence_source": "generated"}, {"text": "他每天晚间都去公园跑步。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚间的天空里有很多星星。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚间的街上很热闹，很多人在散步。", "target_word": "晚间", "complexity_tier": "T3", "furigana": "wǎn jiān", "sentence_source": "generated"}, {"text": "冬天晚间天黑得早。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚间我们一家人在院子里吃饭。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "晚間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "太阳下山、天黑以后的那段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecaec501-a7ea-4216-b684-7b1fdd95ce2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93225, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晚间", "is_correct": true, "explanation": "正确：“晚间”指太阳下山以后，与“天黑了”相符。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：清晨是早上，与“天黑了”矛盾。"}, {"text": "中午", "is_correct": false, "explanation": "语义：中午是白天，不会出现天黑的情况。"}, {"text": "白昼", "is_correct": false, "explanation": "语域：“白昼”偏书面，口语多说“白天”；且白昼时天不会黑。"}], "explanations": {"晚间": "正确：“晚间”指太阳下山以后，与“天黑了”相符。", "清晨": "语义：清晨是早上，与“天黑了”矛盾。", "中午": "语义：中午是白天，不会出现天黑的情况。", "白昼": "语域：“白昼”偏书面，口语多说“白天”；且白昼时天不会黑。"}, "sentence_index": 0, "correct_answer": "晚间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚间的太阳还挂在天上，我们在湖边钓鱼。", "explanation": "这里应该用〈白天〉。太阳还挂在天上时用“白天”，“晚间”指太阳下山以后，两者不能搭配。"}, {"text": "晚间阳光很强，我们戴上了太阳镜。", "explanation": "这里应该用〈中午〉。阳光很强是在白天中午；“晚间”指太阳下山以后，没有强烈的阳光。"}, {"text": "晚间的日出很美，我们早早起来看。", "explanation": "这里应该用〈清晨〉。日出在清晨，“晚间”指太阳下山以后，不能用来描述日出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93225, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晚间", "is_correct": true, "explanation": "正确：“晚间”指入夜后的时段，天空中有星星，与句意相符。"}, {"text": "正午", "is_correct": false, "explanation": "语义：正午是白天最亮的时候，天空中看不到许多星星。"}, {"text": "午后", "is_correct": false, "explanation": "语义：午后仍是白天，天空中看不到星星。"}, {"text": "昼间", "is_correct": false, "explanation": "语域：“昼间”偏书面，口语多说“白天”；且白天的天空看不到星星。"}], "explanations": {"晚间": "正确：“晚间”指入夜后的时段，天空中有星星，与句意相符。", "正午": "语义：正午是白天最亮的时候，天空中看不到许多星星。", "午后": "语义：午后仍是白天，天空中看不到星星。", "昼间": "语域：“昼间”偏书面，口语多说“白天”；且白天的天空看不到星星。"}, "sentence_index": 6, "correct_answer": "晚间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚间吃早饭的时候，我们在院子里聊天。", "explanation": "这里应该用〈早上〉。吃早饭是在早上，“晚间”指太阳下山以后，不能用来说早饭的时间。"}, {"text": "晚间太阳刚升起来，公鸡就叫了。", "explanation": "这里应该用〈清晨〉。太阳升起是在清晨；“晚间”指太阳下山以后。"}, {"text": "晚间的午饭时间，食堂里很热闹。", "explanation": "这里应该用〈中午〉。午饭时间是中午，“晚间”指太阳下山以后，不能用来说午饭时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93225, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们晚间的看电视。", "corrected_sentence": "我们晚间看电视。", "error_description": "错误：“晚间”后多加了“的”，动词“看”前不能直接用“的”，应说「我们晚间看电视」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93225, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天一晚间散步。", "corrected_sentence": "他每天晚间散步。", "error_description": "错误：“晚间”前多加了数词“一”。时间词“晚间”前用“每天”修饰即可，不加数词，应说「他每天晚间散步」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93226, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "正确：白天与晚间（傍晚到夜里）相对，二者是一对反义词。"}, {"text": "下午", "is_correct": false, "explanation": "下午属于白天的一部分，与“晚间”没有对立关系，不构成反义。"}, {"text": "中午", "is_correct": false, "explanation": "中午是白天的一个时刻，与“晚间”没有对立关系。"}, {"text": "星期天", "is_correct": false, "explanation": "星期天指一周中的某一天，与“晚间”的时段没有对立关系。"}], "correct_answer": "白天", "explanations": {"白天": "正确：白天与晚间（傍晚到夜里）相对，二者是一对反义词。", "下午": "下午属于白天的一部分，与“晚间”没有对立关系，不构成反义。", "中午": "中午是白天的一个时刻，与“晚间”没有对立关系。", "星期天": "星期天指一周中的某一天，与“晚间”的时段没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93226, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "正确：白天与晚间（傍晚到夜里）相对，二者是一对反义词。"}, {"text": "周末", "is_correct": false, "explanation": "周末指星期六、星期日，与“晚间”的时段没有对立关系。"}, {"text": "星期一", "is_correct": false, "explanation": "星期一指一周中的某一天，与“晚间”没有对立关系。"}, {"text": "元旦", "is_correct": false, "explanation": "元旦指公历新年，与“晚间”没有对立关系。"}], "correct_answer": "白天", "explanations": {"白天": "正确：白天与晚间（傍晚到夜里）相对，二者是一对反义词。", "周末": "周末指星期六、星期日，与“晚间”的时段没有对立关系。", "星期一": "星期一指一周中的某一天，与“晚间”没有对立关系。", "元旦": "元旦指公历新年，与“晚间”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93226, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "晚上；傍晚到夜里的一段时间。", "primary_collocate": null, "pronunciation": "wǎn jiān", "ipa": "wan˨˩ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "今天晚间有一场大雨。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目晚间七点开始播出。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天晚间气温会降到五度。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店晚间十点才关门。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末晚间，电影院里人很多。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说晚间不要吃太多。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司晚间会发通知。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这趟火车晚间到北京。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在晚间八点以后给我打电话。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电视节目在晚间播出。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "晚間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从傍晚到夜里的时段，常用于预报、安排、通知", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecaec501-a7ea-4216-b684-7b1fdd95ce2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93226, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晚间", "is_correct": true, "explanation": "正确：“晚间”指傍晚到夜里的时段，与“今天”及大雨的预报相符。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”与句中的“今天”冲突，不能同时指今天。"}, {"text": "明年", "is_correct": false, "explanation": "语义：明年是将来的年份，与“今天”矛盾。"}, {"text": "前夜", "is_correct": false, "explanation": "语域：“前夜”偏书面，且指前一天的夜里，与“今天”冲突。"}], "explanations": {"晚间": "正确：“晚间”指傍晚到夜里的时段，与“今天”及大雨的预报相符。", "昨天": "语义：“昨天”与句中的“今天”冲突，不能同时指今天。", "明年": "语义：明年是将来的年份，与“今天”矛盾。", "前夜": "语域：“前夜”偏书面，且指前一天的夜里，与“今天”冲突。"}, "sentence_index": 0, "correct_answer": "晚间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚间十二点，我们一起去吃午饭。", "explanation": "这里应该用〈中午〉。吃午饭在中午，“晚间”指傍晚到夜里，不能用于中午的活动。"}, {"text": "太阳刚升起来，晚间的空气很新鲜。", "explanation": "这里应该用〈早上〉。太阳刚升起是早上，“晚间”指傍晚到夜里。"}, {"text": "晚间的晨练很热闹，老人们都在公园里。", "explanation": "这里应该用〈早上〉。晨练在早上，“晚间”指傍晚到夜里，不能用于早晨的活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晚间", "is_correct": true, "explanation": "正确：“晚间”指入夜前后的时段，适用于公司发通知的语境。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”是过去，与“会”表示将来的语境矛盾。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”指过去的一周，与表示将来的“会发”矛盾。"}, {"text": "昨晚", "is_correct": false, "explanation": "语义：“昨晚”指过去的夜间，与表示将来的“会发”矛盾。"}], "explanations": {"晚间": "正确：“晚间”指入夜前后的时段，适用于公司发通知的语境。", "去年": "语义：“去年”是过去，与“会”表示将来的语境矛盾。", "上周": "语义：“上周”指过去的一周，与表示将来的“会发”矛盾。", "昨晚": "语义：“昨晚”指过去的夜间，与表示将来的“会发”矛盾。"}, "sentence_index": 6, "correct_answer": "晚间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚间的午后很安静，我在窗边看书。", "explanation": "这里应该用〈下午〉。午后属于白天，“晚间”指傍晚到夜里，不能用来说午后的时间。"}, {"text": "晚间学生们都在教室里上第一节课。", "explanation": "这里应该用〈早上〉。第一节课在早上，“晚间”指傍晚到夜里。"}, {"text": "晚间的中午很热，我们去游泳。", "explanation": "这里应该用〈白天〉。中午属于白天，“晚间”指傍晚到夜里，不能用于中午。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们从晚间八点见面。", "corrected_sentence": "我们在晚间八点见面。", "error_description": "错误：“从晚间八点”表示起点，后面要有“开始”或“到……”。这里说的是见面的时间点，应用“在”：「我们在晚间八点见面」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节目对晚间播出。", "corrected_sentence": "这个节目在晚间播出。", "error_description": "错误：介词“对”不能引出时间。表示时间应用“在”：「这个节目在晚间播出」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
