INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93229, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遭受是碰到了不好的事，要忍受。", "primary_collocate": null, "pronunciation": "zāo shòu", "ipa": "tsɑʊ˥ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他小时候遭受过很多苦难。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的人民遭受了长期的战争。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在公司遭受了不公平的对待。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人在地震中遭受了巨大的痛苦。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人遭受着很大的压力。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店的老板遭受了很大的损失。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人长年遭受病痛的折磨。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的同学遭受了大家的冷落。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从没遭受过这样的打击。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不应该遭受这样的批评。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遭受了", "label": "完成体"}, {"form": "遭受着", "label": "持续体"}, {"form": "遭受过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "人碰到苦难、痛苦、打击等不好的事并忍受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ce09844-0065-49c3-b8ad-6ca918984161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93229, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "享受", "is_correct": false, "explanation": "语义：“享受”指感到快乐、舒适，苦难不能被享受。"}, {"text": "遭受", "is_correct": true, "explanation": "遭受：碰到不好的事并忍受，与“过”搭配，符合“小时候承受苦难”的语境。"}, {"text": "赢得", "is_correct": false, "explanation": "配价：“赢得”要求带胜利、尊重等宾语，不能带“苦难”。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指觉得好而品味，苦难不能被欣赏。"}], "explanations": {"享受": "语义：“享受”指感到快乐、舒适，苦难不能被享受。", "遭受": "遭受：碰到不好的事并忍受，与“过”搭配，符合“小时候承受苦难”的语境。", "赢得": "配价：“赢得”要求带胜利、尊重等宾语，不能带“苦难”。", "欣赏": "语义：“欣赏”指觉得好而品味，苦难不能被欣赏。"}, "sentence_index": 0, "correct_answer": "遭受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在假期里遭受了很多乐趣。", "explanation": "这里应该用〈享受〉。遭受用于不好的事，“乐趣”是好事，应说享受。"}, {"text": "他在比赛中遭受了冠军。", "explanation": "这里应该用〈赢得〉。遭受的对象是不好的事，冠军是要赢得的。"}, {"text": "农民今年秋天遭受了丰收。", "explanation": "这里应该用〈获得〉。遭受用于不好的事，丰收是好事，应说获得丰收。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93229, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指觉得好而品味，病痛的折磨不能被欣赏。"}, {"text": "遭受", "is_correct": true, "explanation": "遭受：碰到不好的事并忍受，与“长年”搭配，符合病痛折磨的语境。"}, {"text": "享有", "is_correct": false, "explanation": "配价：“享有”要求带权利、名誉等宾语，不能带“病痛的折磨”。"}, {"text": "获得", "is_correct": false, "explanation": "语义：“获得”指得到好的结果，不能用来指长年承受病痛。"}], "explanations": {"欣赏": "语义：“欣赏”指觉得好而品味，病痛的折磨不能被欣赏。", "遭受": "遭受：碰到不好的事并忍受，与“长年”搭配，符合病痛折磨的语境。", "享有": "配价：“享有”要求带权利、名誉等宾语，不能带“病痛的折磨”。", "获得": "语义：“获得”指得到好的结果，不能用来指长年承受病痛。"}, "sentence_index": 6, "correct_answer": "遭受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们应该遭受老师的帮助。", "explanation": "这里应该用〈接受〉。遭受用于不好的事，老师的帮助是好事，应说接受。"}, {"text": "科学家遭受了一颗新星。", "explanation": "这里应该用〈发现〉。遭受的对象是不好的事，新星是要发现的。"}, {"text": "妈妈遭受了生病的孩子。", "explanation": "这里应该用〈照顾〉。遭受的对象是事情，不能指人，照顾孩子应说照顾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93229, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每到年底，他都遭受了很大的打击。", "corrected_sentence": "每到年底，他都遭受很大的打击。", "error_description": "体标错误：“每到……都”表示反复发生的情况，不能与完成体“了”同用，应说“每到年底，他都遭受很大的打击”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93229, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子从小遭受了过很多批评，性格很敏感。", "corrected_sentence": "这个孩子从小遭受过很多批评，性格很敏感。", "error_description": "体标重复错误：“遭受过”已表示经历过，不能再加“了”。应说“遭受过很多批评”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
