INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93230, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "受到（不幸或损害）。", "primary_collocate": null, "pronunciation": "zāo shòu", "ipa": "tsɑʊ˥ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "南方今年遭受了严重的干旱。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市遭受了一场大洪水。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民的庄稼遭受了很大的损害。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司上个月遭受了网络攻击。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的村子遭受了台风的袭击。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古桥在战争中遭受了破坏。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年冬天，果树遭受了冻害。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区常常遭受暴雨。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游业遭受了很大的打击。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小镇遭受了一次严重的火灾。", "target_word": "遭受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遭受了", "label": "完成体"}, {"form": "遭受着", "label": "持续体"}, {"form": "遭受过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "地区、事物或机构受到灾害、攻击、破坏等损害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ce09844-0065-49c3-b8ad-6ca918984161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指觉得好而品味，干旱不能被欣赏。"}, {"text": "遭受", "is_correct": true, "explanation": "遭受：受到灾害等损害，与“了”搭配，符合南方遭遇干旱的语境。"}, {"text": "赢得", "is_correct": false, "explanation": "配价：“赢得”要求带胜利、支持等宾语，不能带“干旱”。"}, {"text": "分享", "is_correct": false, "explanation": "语义：“分享”指与人共同拥有好的东西，干旱不能分享。"}], "explanations": {"欣赏": "语义：“欣赏”指觉得好而品味，干旱不能被欣赏。", "遭受": "遭受：受到灾害等损害，与“了”搭配，符合南方遭遇干旱的语境。", "赢得": "配价：“赢得”要求带胜利、支持等宾语，不能带“干旱”。", "分享": "语义：“分享”指与人共同拥有好的东西，干旱不能分享。"}, "sentence_index": 0, "correct_answer": "遭受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她终于遭受了老师的表扬。", "explanation": "这里应该用〈得到〉。遭受用于不好的事，老师的表扬是好事，应说得到。"}, {"text": "她的作品遭受了大家的喜爱。", "explanation": "这里应该用〈受到〉。遭受用于不好的事，大家的喜爱是好事，应说受到。"}, {"text": "我们正在遭受美好的周末。", "explanation": "这里应该用〈享受〉。遭受用于不好的事，美好的周末是好事，应说享受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "享受", "is_correct": false, "explanation": "语义：“享受”指感到快乐、舒适，冻害不能被享受。"}, {"text": "遭受", "is_correct": true, "explanation": "遭受：受到灾害等损害，与“了”搭配，符合果树遭受冻害的语境。"}, {"text": "获得", "is_correct": false, "explanation": "语义：“获得”指得到好的结果，冻害不能被获得。"}, {"text": "享有", "is_correct": false, "explanation": "配价：“享有”要求带权利、名誉等宾语，不能带“冻害”。"}], "explanations": {"享受": "语义：“享受”指感到快乐、舒适，冻害不能被享受。", "遭受": "遭受：受到灾害等损害，与“了”搭配，符合果树遭受冻害的语境。", "获得": "语义：“获得”指得到好的结果，冻害不能被获得。", "享有": "配价：“享有”要求带权利、名誉等宾语，不能带“冻害”。"}, "sentence_index": 6, "correct_answer": "遭受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨水遭受了丰收。", "explanation": "这里应该用〈带来〉。遭受用于不好的事，丰收是好事，应说带来。"}, {"text": "这家医院遭受了免费服务。", "explanation": "这里应该用〈提供〉。遭受的对象是不好的事，免费服务是要提供的。"}, {"text": "学生遭受了奖学金。", "explanation": "这里应该用〈获得〉。遭受用于不好的事，奖学金是要获得的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小镇正在遭受了一场火灾，很多房子被烧毁了。", "corrected_sentence": "小镇正在遭受一场火灾，很多房子被烧毁了。", "error_description": "体标错误：“正在”表示动作进行中，不能与完成体“了”同用，应说“正在遭受一场火灾”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个岛每年夏天常常遭受了台风。", "corrected_sentence": "这个岛每年夏天常常遭受台风。", "error_description": "体标错误：“每年”“常常”表示反复发生的情况，不能与完成体“了”同用。应说“常常遭受台风”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
