INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93231, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "期刊是每隔一段时间出一本的杂志。", "primary_collocate": null, "pronunciation": "qī kān", "ipa": "tɕʰi˥ kʰan˥", "syllable_count": 2, "sentences": [{"text": "图书馆里有很多期刊。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本期刊每个月出一期。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他订了一份英文期刊。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在期刊上看到了这篇文章。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份期刊每周都出新的一期。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把期刊放在桌子上。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的文章发表在一本期刊上。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生可以在阅览室看期刊。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本期刊的封面很漂亮。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每个季度买一本旅游期刊。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一本期刊", "label": "量词"}, {"form": "一份期刊", "label": "量词"}], "register": "书面", "sense_fingerprint": "名词，每隔一段时间出一期的杂志", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088928fc-a436-497e-8711-79f5a28a97a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93231, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "期刊", "is_correct": true, "explanation": "“期刊”是定期出版的刊物，图书馆里可以有很多，句意通顺。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：图书馆是看书的地方，不会放很多饭菜，与句中的“图书馆里”相矛盾。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会成堆地放在图书馆里，与“图书馆里有很多”不合。"}, {"text": "北京", "is_correct": false, "explanation": "搭配：“很多”不修饰地名，“图书馆里有很多北京”不成立。"}], "explanations": {"期刊": "“期刊”是定期出版的刊物，图书馆里可以有很多，句意通顺。", "饭菜": "语义：图书馆是看书的地方，不会放很多饭菜，与句中的“图书馆里”相矛盾。", "汽车": "语义：汽车不会成堆地放在图书馆里，与“图书馆里有很多”不合。", "北京": "搭配：“很多”不修饰地名，“图书馆里有很多北京”不成立。"}, "sentence_index": 0, "correct_answer": "期刊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在期刊上收看了今天的新闻联播。", "explanation": "这里应该用〈电视〉。“收看”的对象是电视节目，期刊是印刷品，不能“收看”。"}, {"text": "我下班后喜欢听期刊。", "explanation": "这里应该用〈广播〉。期刊是印刷品，不能用“听”，“听”的对象是广播。"}, {"text": "他写了一份期刊。", "explanation": "这里应该用〈报告〉。“写”的是文字材料；期刊是定期出版的刊物，要说“编”或“办”，不说“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93231, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "期刊", "is_correct": true, "explanation": "“期刊”是定期出版的刊物，可以“发表在”它上面，句意通顺。"}, {"text": "饭桌", "is_correct": false, "explanation": "搭配：量词“一本”用于书册，不用于饭桌，“一本饭桌”不成立。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以刊登文章的载体，“发表在天空上”不合句意。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“一本”不修饰石头，应说“一块石头”。"}], "explanations": {"期刊": "“期刊”是定期出版的刊物，可以“发表在”它上面，句意通顺。", "饭桌": "搭配：量词“一本”用于书册，不用于饭桌，“一本饭桌”不成立。", "天空": "语义：天空不是可以刊登文章的载体，“发表在天空上”不合句意。", "石头": "搭配：“一本”不修饰石头，应说“一块石头”。"}, "sentence_index": 6, "correct_answer": "期刊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一条期刊。", "explanation": "这里应该用〈本〉。“条”用于细长的东西，期刊不用“条”。"}, {"text": "他订了一台期刊。", "explanation": "这里应该用〈本〉或〈份〉。“台”用于机器，期刊不用“台”。"}, {"text": "图书馆新进了一顶期刊。", "explanation": "这里应该用〈本〉。“顶”用于帽子、帐篷等，期刊不用“顶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每个月都订阅一只期刊。", "corrected_sentence": "我每个月都订阅一本期刊。", "error_description": "量词错误：“期刊”应用量词“本”或“份”。“只”用于动物等，不能用于期刊。错误形式是“一只期刊”，正确形式是“一本期刊”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天借了这本英文期刊们。", "corrected_sentence": "我昨天借了这本英文期刊。", "error_description": "错误在于“期刊”后多加了复数词尾“们”。“们”只用于指人的名词，期刊是物，且“这本”已表示单数，不能再加“们”。应说“这本英文期刊”，不说“这本英文期刊们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
