INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93232, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93232, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "定期出版的刊物，如周刊、月刊。", "primary_collocate": null, "pronunciation": "qī kān", "ipa": "tɕʰi˥ kʰan˥", "syllable_count": 2, "sentences": [{"text": "这种期刊每年出十二期。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想给那本期刊投稿。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一本有名的期刊。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐是一份期刊的编辑。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校有自己的期刊。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份期刊的读者大多是老师。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把论文寄给了一份期刊。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "期刊上的文章都要先检查。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本期刊停刊了三年。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里新来了几种期刊。", "target_word": "期刊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一本期刊", "label": "量词"}, {"form": "一份期刊", "label": "量词"}], "register": "书面", "sense_fingerprint": "名词，定期出版的刊物，包括周刊、月刊等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088928fc-a436-497e-8711-79f5a28a97a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "期刊", "is_correct": true, "explanation": "“期刊”是定期出版的刊物，“每年出十二期”正好说明它的出版周期。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不是出版物，不会“出十二期”。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视机不是定期出版的东西，不能说“出十二期”。"}, {"text": "演唱会", "is_correct": false, "explanation": "搭配：“出……期”只搭配出版物，演唱会不能说“出十二期”。"}], "explanations": {"期刊": "“期刊”是定期出版的刊物，“每年出十二期”正好说明它的出版周期。", "树木": "语义：树木不是出版物，不会“出十二期”。", "电视": "语义：电视机不是定期出版的东西，不能说“出十二期”。", "演唱会": "搭配：“出……期”只搭配出版物，演唱会不能说“出十二期”。"}, "sentence_index": 0, "correct_answer": "期刊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他订了一把期刊。", "explanation": "这里应该用〈本〉或〈份〉。“把”用于有柄的东西，期刊不用“把”。"}, {"text": "妈妈借来一块期刊。", "explanation": "这里应该用〈本〉或〈份〉。“块”用于块状的东西，期刊不用“块”。"}, {"text": "学校收到了一架期刊。", "explanation": "这里应该用〈本〉或〈份〉。“架”用于飞机、机器等，期刊不用“架”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "期刊", "is_correct": true, "explanation": "“期刊”是定期出版的刊物，“寄给了一份”正好指投寄的稿件对象。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：量词“一份”不用于人，应说“一位老师”。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：“寄给”的对象必须是人或机构，牛奶不能作为收件对象。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能作为收件对象，“寄给了冰箱”不合句意。"}], "explanations": {"期刊": "“期刊”是定期出版的刊物，“寄给了一份”正好指投寄的稿件对象。", "老师": "搭配：量词“一份”不用于人，应说“一位老师”。", "牛奶": "语义：“寄给”的对象必须是人或机构，牛奶不能作为收件对象。", "冰箱": "语义：冰箱是家电，不能作为收件对象，“寄给了冰箱”不合句意。"}, "sentence_index": 6, "correct_answer": "期刊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份期刊每天早上送到我家。", "explanation": "这里应该用〈报纸〉。报纸每天出版，期刊隔一段时间才出一期，不会每天送来。"}, {"text": "我写期刊给远方的朋友。", "explanation": "这里应该用〈信〉。“写”的是书信，期刊是定期出版的刊物，不能“写”给朋友。"}, {"text": "我给朋友打期刊。", "explanation": "这里应该用〈电话〉。“打”搭配电话，期刊不能被“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每个月都读一本期刊们。", "corrected_sentence": "我每个月都读一本期刊。", "error_description": "错误在于“期刊”后多加了复数词尾“们”。“们”不能用于物品名词，且“一本”已表示数量，不能再加“们”。应说“我每个月都读一本期刊”，不说“我每个月都读一本期刊们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这支期刊留给了我。", "corrected_sentence": "他把这份期刊留给了我。", "error_description": "量词错误：“期刊”应用量词“份”或“本”。“支”用于细长的东西，如笔、烟，不能用于期刊。错误形式是“这支期刊”，正确形式是“这份期刊”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
