INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93233, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "遗址是房屋倒塌或烧毁以后，留下来的地方。", "primary_collocate": null, "pronunciation": "yí zhǐ", "ipa": "i˧˥ ʈʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "老房子倒了以后，只留下了遗址。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的古庙只剩下一片遗址。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火以后，这里变成了遗址。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋老屋早已坍塌，如今只剩下遗址。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在遗址上找到一块旧砖。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在遗址前，我想起了以前住在这里的人。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座烧毁的老房子的遗址在草地下面。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遗址上长满了草。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，这里以前有一座大房子，现在是遗址。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子倒了，留下来的只是一片遗址。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处", "label": "量词"}, {"form": "遗址公园", "label": "复合"}, {"form": "遺址", "label": "繁体"}], "register": "中性", "sense_fingerprint": "房屋倒塌或烧毁以后留下来的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de94bd89-19e3-4337-868c-ae9af5a910e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93233, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遗址", "is_correct": true, "explanation": "正确。“遗址”指房屋倒塌或烧毁以后留下的地方，与原句一致。"}, {"text": "一致", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是相同、没有差别。"}, {"text": "意志", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是决心和毅力。"}, {"text": "医治", "is_correct": false, "explanation": "yī（第一声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是治疗。"}, {"text": "以至", "is_correct": false, "explanation": "yǐ（第三声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是表示结果或程度。"}], "explanations": {"遗址": "正确。“遗址”指房屋倒塌或烧毁以后留下的地方，与原句一致。", "一致": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是相同、没有差别。", "意志": "yì（第四声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是决心和毅力。", "医治": "yī（第一声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是治疗。", "以至": "yǐ（第三声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是表示结果或程度。"}, "sentence_index": null, "correct_answer": "遗址"}, "level_3": {"options": [{"text": "遗址", "is_correct": true, "explanation": "正确。老房子倒了以后留下的是遗址，与句意一致。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：房子倒了，留下的不是汽车，与“老房子倒了”的语境不合。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“留下”后面接具体的物体或痕迹，不能说“留下了年龄”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：老房子倒了以后留下的不会是电脑，与句意不合。"}], "explanations": {"遗址": "正确。老房子倒了以后留下的是遗址，与句意一致。", "汽车": "语义：房子倒了，留下的不是汽车，与“老房子倒了”的语境不合。", "年龄": "搭配：“留下”后面接具体的物体或痕迹，不能说“留下了年龄”。", "电脑": "语义：老房子倒了以后留下的不会是电脑，与句意不合。"}, "sentence_index": 0, "correct_answer": "遗址"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋老屋早已坍塌，如今只剩下一条遗址。", "explanation": "这里应该用〈处〉。“遗址”的量词是“处”，“条”用于细长的东西，不能修饰它。"}, {"text": "这件瓷器是珍贵的遗址。", "explanation": "这里应该用〈文物〉。文物是可以保存和收藏的器物，“遗址”指场所，不能用来指瓷器。"}, {"text": "他把遗址寄给了远方的朋友。", "explanation": "这里应该用〈信〉。“遗址”是场所，不是能寄送的东西，“寄”的对象应是信件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93233, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "遗址", "is_correct": true, "explanation": "正确。“遗址”指房屋倒塌或烧毁以后留下的地方，与原句一致。"}, {"text": "遗志", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是人去世前留下的愿望。"}, {"text": "移植", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是把植物挪到别处栽种。"}, {"text": "异质", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是性质不同。"}, {"text": "移至", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是挪动到某处。"}], "explanations": {"遗址": "正确。“遗址”指房屋倒塌或烧毁以后留下的地方，与原句一致。", "遗志": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是人去世前留下的愿望。", "移植": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是把植物挪到别处栽种。", "异质": "yì（第四声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是性质不同。", "移至": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是挪动到某处。"}, "sentence_index": null, "correct_answer": "遗址"}, "level_3": {"options": [{"text": "遗址", "is_correct": true, "explanation": "正确。老房子烧毁以后留下的地方就是遗址，与句意一致。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不是建筑遗存，不会在草地下面，句意不合。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是收入，不会埋在草地下面，句意不合。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是饮食，不会埋在草地下面，句意不合。"}], "explanations": {"遗址": "正确。老房子烧毁以后留下的地方就是遗址，与句意一致。", "心情": "语义：心情不是建筑遗存，不会在草地下面，句意不合。", "工资": "语义：工资是收入，不会埋在草地下面，句意不合。", "早餐": "语义：早餐是饮食，不会埋在草地下面，句意不合。"}, "sentence_index": 6, "correct_answer": "遗址"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "律师昨天当众宣读了遗址，大家都很感动。", "explanation": "这里应该用〈遗嘱〉。“遗址”是场所，不能宣读，宣读的是遗嘱。"}, {"text": "我的弟弟就是一片遗址。", "explanation": "语义：“遗址”是场所，不指人，不能用来说明一个人。"}, {"text": "院子里有一颗遗址。", "explanation": "这里应该用〈处〉。“遗址”的量词是“处”，“颗”用于小而圆的东西，不能修饰它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDE