INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93234, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "古代人类活动遗留下来的场所。", "primary_collocate": null, "pronunciation": "yí zhǐ", "ipa": "i˧˥ ʈʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这里是三千年前的古代遗址。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考古人员在山下发现了一处遗址。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们周末去参观了那个古城遗址。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这处遗址有五千多年的历史。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遗址里挖出了很多陶器。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客不能随便进入遗址。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在研究这个新发现的遗址。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的遗址里有古人住过的房子。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要保护这片遗址。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个遗址在河边，离我家不远。", "target_word": "遗址", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处", "label": "量词"}, {"form": "遗址公园", "label": "复合"}, {"form": "遺址", "label": "繁体"}], "register": "中性", "sense_fingerprint": "古代人类活动遗留下来的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de94bd89-19e3-4337-868c-ae9af5a910e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93234, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遗址", "is_correct": true, "explanation": "正确。“遗址”指古代人类活动遗留下来的场所，与原句一致。"}, {"text": "移植", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是把植物挪到别处栽种。"}, {"text": "一致", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是相同、没有差别。"}, {"text": "意志", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是决心和毅力。"}, {"text": "医治", "is_correct": false, "explanation": "yī（第一声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是治疗。"}], "explanations": {"遗址": "正确。“遗址”指古代人类活动遗留下来的场所，与原句一致。", "移植": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是把植物挪到别处栽种。", "一致": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是相同、没有差别。", "意志": "yì（第四声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是决心和毅力。", "医治": "yī（第一声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是治疗。"}, "sentence_index": null, "correct_answer": "遗址"}, "level_3": {"options": [{"text": "遗址", "is_correct": true, "explanation": "正确。“遗址”指古代人类活动遗留下来的场所，与“这里”相符。"}, {"text": "人物", "is_correct": false, "explanation": "语义：“这里”指地点，“人物”不是地点，句意不合。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”不是地点，与“这里是”的句式不合。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”指某地的人数，不能说“这里是……古代人口”。"}], "explanations": {"遗址": "正确。“遗址”指古代人类活动遗留下来的场所，与“这里”相符。", "人物": "语义：“这里”指地点，“人物”不是地点，句意不合。", "乐器": "语义：“乐器”不是地点，与“这里是”的句式不合。", "人口": "搭配：“人口”指某地的人数，不能说“这里是……古代人口”。"}, "sentence_index": 0, "correct_answer": "遗址"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去参观了那个古城的一条遗址。", "explanation": "这里应该用〈处〉。“遗址”的量词是“处”，“条”用于细长的东西，不能修饰它。"}, {"text": "博物馆收藏了很多遗址。", "explanation": "这里应该用〈文物〉。“收藏”的对象是可以搬动的文物，遗址是地点，不能收藏。"}, {"text": "他去世以后，遗址被送到了殡仪馆。", "explanation": "这里应该用〈遗体〉。“遗址”指古代遗留下来的场所，不指人的遗体，“送到殡仪馆”的对象应是遗体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93234, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "遗址", "is_correct": true, "explanation": "正确。“遗址”指古代人类活动遗留下来的场所，与原句一致。"}, {"text": "遗志", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是人去世前留下的愿望。"}, {"text": "以至", "is_correct": false, "explanation": "yǐ（第三声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是表示结果或程度。"}, {"text": "移至", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是挪动到某处。"}, {"text": "异质", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是性质不同。"}], "explanations": {"遗址": "正确。“遗址”指古代人类活动遗留下来的场所，与原句一致。", "遗志": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是人去世前留下的愿望。", "以至": "yǐ（第三声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是表示结果或程度。", "移至": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是挪动到某处。", "异质": "yì（第四声）与 yí（第二声）、zhì（第四声）与 zhǐ（第三声）声调都不同，意思是性质不同。"}, "sentence_index": null, "correct_answer": "遗址"}, "level_3": {"options": [{"text": "遗址", "is_correct": true, "explanation": "正确。“新发现的遗址”指古代遗留的场所，与句意一致。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是饮食，不是专家需要研究的新发现，句意不合。"}, {"text": "晚会", "is_correct": false, "explanation": "语义：晚会是一种活动，不是需要研究的新发现对象，句意不合。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是收入，不是专家研究的对象，句意不合。"}], "explanations": {"遗址": "正确。“新发现的遗址”指古代遗留的场所，与句意一致。", "早餐": "语义：早餐是饮食，不是专家需要研究的新发现，句意不合。", "晚会": "语义：晚会是一种活动，不是需要研究的新发现对象，句意不合。", "工资": "语义：工资是收入，不是专家研究的对象，句意不合。"}, "sentence_index": 6, "correct_answer": "遗址"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的新房子是一个遗址，很漂亮。", "explanation": "这里应该用〈住宅〉。“遗址”指古代遗留的场所，不指新建的住宅。"}, {"text": "遗址是我们班的新同学。", "explanation": "语义：“遗址”指场所，不指人，不能当作“同学”。"}, {"text": "河边有一颗遗址，离我家不远。", "explanation": "这里应该用〈处〉。“遗址”的量词是“处”，“颗”用于小而圆的东西，不能修饰它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "游客们在这只遗址前拍照。", "corrected_sentence": "游客们在这处遗址前拍照。", "error_description": "量词错误：“遗址”的量词是“处”，不用“只”。应把“这只遗址”改为“这处遗址”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一张遗址是国家保护的。", "corrected_sentence": "这一处遗址是国家保护的。", "error_description": "量词错误：“遗址”的量词是“处”，“张”用于平的东西，不能修饰“遗址”。应把“这一张遗址”改为“这一处遗址”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
