INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93236, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93236, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从东方吹来的风；多指春风。", "primary_collocate": null, "pronunciation": "dōng fēng", "ipa": "tʊŋ˥ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "东风吹来，花都开了。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的东风很暖和。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东风一来，河里的冰就化了。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们都说，东风带来了春天。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东风吹绿了河边的小草。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东风吹过，柳树发芽了。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一阵暖暖的东风吹在脸上。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨夜东风吹过，今天满山是花。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗人常用东风来形容春天的到来。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东风送暖，大地又有了生机。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "東風", "label": "繁体"}, {"form": "一阵东风", "label": "量词"}], "register": "书面", "sense_fingerprint": "春风（东风送暖，春天来临）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5582003f-0fa5-4559-bf80-a34613800f6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93236, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷风", "is_correct": false, "explanation": "语义：“冷风”是寒冷的风，与花开的春日情景不合。"}, {"text": "东风", "is_correct": true, "explanation": "正确：“东风”指春风，吹来时百花开放，与句意相合。"}, {"text": "北风", "is_correct": false, "explanation": "语义：“北风”多指冬季的寒风，与“花都开了”的春天不符。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“雨”不能说“吹来”，“吹”的对象应是风。"}], "explanations": {"冷风": "语义：“冷风”是寒冷的风，与花开的春日情景不合。", "东风": "正确：“东风”指春风，吹来时百花开放，与句意相合。", "北风": "语义：“北风”多指冬季的寒风，与“花都开了”的春天不符。", "雨": "搭配：“雨”不能说“吹来”，“吹”的对象应是风。"}, "sentence_index": 0, "correct_answer": "东风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人们都说，东风带来了冬天。", "explanation": "这里应该用〈春天〉。“东风”指春风，带来的是春天，不能带来冬天。"}, {"text": "人们都说，一只东风带来了春天。", "explanation": "这里应该用〈阵〉。“东风”作量词搭配应用“阵”，不用“只”。"}, {"text": "东风吹过，树叶纷纷落下，秋天到了。", "explanation": "“东风”指春风，应带来暖意和生机；这里说树叶落下、秋天到了，与春风的作用相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寒风", "is_correct": false, "explanation": "语义：“寒风”寒冷，与“暖暖的”相矛盾。"}, {"text": "东风", "is_correct": true, "explanation": "正确：“东风”指春风，带来暖意，与“一阵暖暖的”相合。"}, {"text": "雪", "is_correct": false, "explanation": "语义：“雪”是冷的，不能说成“暖暖的雪”。"}, {"text": "冰雹", "is_correct": false, "explanation": "搭配：冰雹是降落的冰块，不能说“吹在脸上”。"}], "explanations": {"寒风": "语义：“寒风”寒冷，与“暖暖的”相矛盾。", "东风": "正确：“东风”指春风，带来暖意，与“一阵暖暖的”相合。", "雪": "语义：“雪”是冷的，不能说成“暖暖的雪”。", "冰雹": "搭配：冰雹是降落的冰块，不能说“吹在脸上”。"}, "sentence_index": 6, "correct_answer": "东风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "东风吹到哪里，哪里的花就都谢了，草木都枯黄了。", "explanation": "“东风”多指温暖的春风，它吹到的地方应是花开草绿；这里说花谢草枯，与春风的意思相反。"}, {"text": "东风一来，河里的冰就冻得更厚了。", "explanation": "“东风”指春风，应使冰化开、春暖回来；这里说冰冻得更厚，与春风的作用相反。"}, {"text": "我家住在东风的南边。", "explanation": "这里应该用〈东边〉。“东风”指春风，是风，不是方位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天的一只东风吹过河面，冰都化了。", "corrected_sentence": "春天的东风吹过河面，冰都化了。", "error_description": "错误形式是“一只东风”，正确形式是“东风”。“东风”作为风，不能用量词“只”，应说“一阵东风”或直接用“春天的东风”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "早春的一条东风吹绿了河岸。", "corrected_sentence": "早春的东风吹绿了河岸。", "error_description": "错误形式是“一条东风”，正确形式是“东风”（或“一阵东风”）。“东风”是风，不能用量词“条”，“条”用于河流、道路等长条形事物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
