INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93237, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93237, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "难民是因为战争或灾害，没有家可回的人。", "primary_collocate": null, "pronunciation": "nàn mín", "ipa": "nan˥˩ min˧˥", "syllable_count": 2, "sentences": [{"text": "战争开始后，很多难民离开了家。", "target_word": "难民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "难民们没有吃的，也没有水。", "target_word": "难民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家接收了一万名难民。", "target_word": "难民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红十字会给难民送来了药和衣服。", "target_word": "难民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震以后，难民住在帐篷里。", "target_word": "难民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者每天都为难民准备热饭。", "target_word": "难民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些难民坐船去了一个安全的国家。", "target_word": "难民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洪水让上千人变成了难民，他们需要帮助。", "target_word": "难民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为难民孩子办了一个免费的班。", "target_word": "难民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者采访了几位刚到的难民。", "target_word": "难民", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "批", "label": "量词"}, {"form": "难民营", "label": "复合"}, {"form": "难民潮", "label": "复合"}], "register": "中性", "sense_fingerprint": "因战争或灾害无家可归的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39432ac-a2b3-4cb2-a82d-341df50f8430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93237, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "难民", "is_correct": true, "explanation": "难民指因战争或灾害而离开家的人，填入后句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会离开家，句意不通。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝是零件，不能离开家。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“离开家”的主语需要是人或动物，“窗户”不能离开家。"}], "explanations": {"难民": "难民指因战争或灾害而离开家的人，填入后句意通顺。", "石头": "语义：石头不会离开家，句意不通。", "螺丝": "语义：螺丝是零件，不能离开家。", "窗户": "搭配：“离开家”的主语需要是人或动物，“窗户”不能离开家。"}, "sentence_index": 0, "correct_answer": "难民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "难民在战场上保卫国家。", "explanation": "这里应该用〈士兵〉。难民指因战乱或灾害而失去家园的人，不是保卫国家的军人。"}, {"text": "难民在天上飞来飞去，叽叽喳喳地叫。", "explanation": "这里应该用〈鸟〉。难民是失去家园的人，不会在天上飞，也不会叽叽喳喳地叫。"}, {"text": "难民在夜里翻墙出了监狱。", "explanation": "这里应该用〈逃犯〉。难民是流离失所的人，不是越狱的罪犯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93237, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "难民", "is_correct": true, "explanation": "难民指需要帮助、坐船离开的人，填入后句意通顺。"}, {"text": "海豚", "is_correct": false, "explanation": "语义：海豚不是人，不会“坐船去国家”，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能坐船去一个国家，句意不通。"}, {"text": "货物", "is_correct": false, "explanation": "搭配：“坐船”的主语应是人，货物是被船运送的，不能“坐船”去一个安全的国家。"}], "explanations": {"难民": "难民指需要帮助、坐船离开的人，填入后句意通顺。", "海豚": "语义：海豚不是人，不会“坐船去国家”，句意不通。", "桌子": "语义：桌子不能坐船去一个国家，句意不通。", "货物": "搭配：“坐船”的主语应是人，货物是被船运送的，不能“坐船”去一个安全的国家。"}, "sentence_index": 6, "correct_answer": "难民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "难民在医院里给病人治病。", "explanation": "这里应该用〈医生〉。难民指流离失所的人，不能替病人治病。"}, {"text": "难民在路口指挥交通。", "explanation": "这里应该用〈警察〉。难民指失去家园的人，并不负责指挥交通。"}, {"text": "春天到了，难民在花园里开了。", "explanation": "这里应该用〈花〉。难民是失去家园的人，不会“开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93237, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "营地里有一辆难民，他的孩子生病了。", "corrected_sentence": "营地里有一名难民，他的孩子生病了。", "error_description": "量词错误：难民指人，量词应用「名」或「个」，不能用「辆」（「辆」用于车）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93237, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一颗难民抱着孩子，走过了边境。", "corrected_sentence": "一位难民抱着孩子，走过了边境。", "error_description": "量词错误：难民指人，量词应用「位」，不能用「颗」（「颗」用于小而圆的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
