INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93239, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "民意是很多人心里的想法。", "primary_collocate": null, "pronunciation": "mín yì", "ipa": "min˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "市长很重视民意。", "target_word": "民意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事要听听民意。", "target_word": "民意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多市民希望有一个新公园，这就是民意。", "target_word": "民意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的民意很清楚。", "target_word": "民意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想知道真正的民意。", "target_word": "民意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个决定不符合民意。", "target_word": "民意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "民意告诉我们，大家喜欢这个计划。", "target_word": "民意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想先了解民意再做决定。", "target_word": "民意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好官员要听民意。", "target_word": "民意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上的民意很一致。", "target_word": "民意", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "民意调查", "label": "复合"}], "register": "中性", "sense_fingerprint": "很多普通人心里的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76794e94-6924-4452-985d-713c29f920c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93239, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "民意", "is_correct": true, "explanation": "正确答案：民意（mín yì），指很多人心里的想法。"}, {"text": "名义", "is_correct": false, "explanation": "míng yì 与 mín yì 韵尾不同（ng 与 n），意思是名义。"}, {"text": "民事", "is_correct": false, "explanation": "shì 与 yì 声母不同（sh 与 y），意思是民间事务。"}, {"text": "民力", "is_correct": false, "explanation": "lì 与 yì 声母不同（l 与 y），意思是民众的力量。"}, {"text": "民气", "is_correct": false, "explanation": "qì 与 yì 声母不同（q 与 y），意思是民间的情绪和士气。"}], "explanations": {"民意": "正确答案：民意（mín yì），指很多人心里的想法。", "名义": "míng yì 与 mín yì 韵尾不同（ng 与 n），意思是名义。", "民事": "shì 与 yì 声母不同（sh 与 y），意思是民间事务。", "民力": "lì 与 yì 声母不同（l 与 y），意思是民众的力量。", "民气": "qì 与 yì 声母不同（q 与 y），意思是民间的情绪和士气。"}, "sentence_index": null, "correct_answer": "民意"}, "level_3": {"options": [{"text": "民意", "is_correct": true, "explanation": "正确答案：民意指很多人的想法，可以被“重视”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“重视”要求抽象对象，“桌子”是具体家具，不能说重视桌子。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：市长不会去重视一只小猫这样的个体动物，句子与常理不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“重视”的对象是事务或意见，不能是家用电器。"}], "explanations": {"民意": "正确答案：民意指很多人的想法，可以被“重视”。", "桌子": "搭配：“重视”要求抽象对象，“桌子”是具体家具，不能说重视桌子。", "小猫": "语义：市长不会去重视一只小猫这样的个体动物，句子与常理不符。", "冰箱": "搭配：“重视”的对象是事务或意见，不能是家用电器。"}, "sentence_index": 0, "correct_answer": "民意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对这件事有自己的民意。", "explanation": "这里应该用〈意见〉。民意指很多人的想法，说个人的看法要用意见。"}, {"text": "这份礼物是我的一点民意。", "explanation": "这里应该用〈心意〉。民意指很多人的想法，不能用来指个人的心意或礼物。"}, {"text": "他的民意是去北京工作。", "explanation": "这里应该用〈心愿〉。民意指很多人的想法，个人的愿望要说心愿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93239, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民意", "is_correct": true, "explanation": "正确答案：民意可以“告诉”人们大家的想法，与句子内容相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能表达想法，无法“告诉”我们大家喜欢什么。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能传递意见，与“大家喜欢这个计划”的信息不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能表达大家对计划的喜好，与句意不符。"}], "explanations": {"民意": "正确答案：民意可以“告诉”人们大家的想法，与句子内容相合。", "石头": "语义：石头不能表达想法，无法“告诉”我们大家喜欢什么。", "空气": "语义：空气不能传递意见，与“大家喜欢这个计划”的信息不符。", "天气": "语义：天气不能表达大家对计划的喜好，与句意不符。"}, "sentence_index": 6, "correct_answer": "民意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子终于说出了自己的民意。", "explanation": "这里应该用〈心声〉。民意指很多人的想法，一个孩子自己内心的感受要说心声。"}, {"text": "他的民意很坚决，不肯让步。", "explanation": "这里应该用〈态度〉。民意指很多人的想法，个人的态度不能说民意。"}, {"text": "我对他的民意很好。", "explanation": "这里应该用〈印象〉。民意是群体的想法，个人对人的印象不能用民意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93239, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市长应该认真考虑民意们。", "corrected_sentence": "市长应该认真考虑民意。", "error_description": "“民意”是抽象名词，不能加“们”表示复数。“民意们”是错误形式，应说“民意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93239, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "网络上地民意很集中。", "corrected_sentence": "网络上的民意很集中。", "error_description": "修饰名词“民意”的定语要用“的”，不能用“地”。“地”用于动词前作状语。应为“网络上的民意很集中”，“网络上地民意”是错误形式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
