INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人民群众的意愿和意见。", "primary_collocate": null, "pronunciation": "mín yì", "ipa": "min˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "政府的政策应该反映民意。", "target_word": "民意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要认真倾听民意。", "target_word": "民意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项法律充分尊重民意。", "target_word": "民意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官员不能违背民意。", "target_word": "民意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸报道了社会的民意。", "target_word": "民意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民意是政府决策的重要依据。", "target_word": "民意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表要把民意带到会议上。", "target_word": "民意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次选举体现了民意。", "target_word": "民意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "违背民意的政策很难成功。", "target_word": "民意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府通过会议了解民意。", "target_word": "民意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "民意调查", "label": "复合"}], "register": "书面", "sense_fingerprint": "人民群众的意愿和意见(政治、社会语境)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76794e94-6924-4452-985d-713c29f920c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93240, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "民意", "is_correct": true, "explanation": "正确答案：民意（mín yì），指人民群众的意愿和意见。"}, {"text": "名义", "is_correct": false, "explanation": "míng yì 与 mín yì 韵尾不同（ng 与 n），意思是名义。"}, {"text": "民事", "is_correct": false, "explanation": "shì 与 yì 声母不同（sh 与 y），意思是民间事务。"}, {"text": "民力", "is_correct": false, "explanation": "lì 与 yì 声母不同（l 与 y），意思是民众的力量。"}, {"text": "民气", "is_correct": false, "explanation": "qì 与 yì 声母不同（q 与 y），意思是民间的情绪和士气。"}], "explanations": {"民意": "正确答案：民意（mín yì），指人民群众的意愿和意见。", "名义": "míng yì 与 mín yì 韵尾不同（ng 与 n），意思是名义。", "民事": "shì 与 yì 声母不同（sh 与 y），意思是民间事务。", "民力": "lì 与 yì 声母不同（l 与 y），意思是民众的力量。", "民气": "qì 与 yì 声母不同（q 与 y），意思是民间的情绪和士气。"}, "sentence_index": null, "correct_answer": "民意"}, "level_3": {"options": [{"text": "民意", "is_correct": true, "explanation": "正确答案：政策应该反映的是人民群众的意愿。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“反映”的内容是意愿或情况，体重不能由政策来反映。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“反映”要求抽象内容，“冰箱”是具体家电，不能说政策反映冰箱。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”是具体家具，与“反映”搭配不当。"}], "explanations": {"民意": "正确答案：政策应该反映的是人民群众的意愿。", "体重": "语义：“反映”的内容是意愿或情况，体重不能由政策来反映。", "冰箱": "搭配：“反映”要求抽象内容，“冰箱”是具体家电，不能说政策反映冰箱。", "桌子": "搭配：“桌子”是具体家具，与“反映”搭配不当。"}, "sentence_index": 0, "correct_answer": "民意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府接受了专家的民意。", "explanation": "这里应该用〈建议〉。民意指群众普遍的意愿，专家的个别建议不能说民意。"}, {"text": "他对历史有深刻的民意。", "explanation": "这里应该用〈认识〉。民意指群众的意愿，对历史的理解要说认识。"}, {"text": "他的民意是考上大学。", "explanation": "这里应该用〈愿望〉。民意指群众共同的意愿，个人的愿望不能说民意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民意", "is_correct": true, "explanation": "正确答案：代表带到会议上的是群众的意见和意愿。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气无法被带到会议上，这里应指可以携带的内容。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“把……带到”的宾语须是可携带之物，“空气”不能被带到会议上。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不能被带到会议上，与代表的行为不合。"}], "explanations": {"民意": "正确答案：代表带到会议上的是群众的意见和意愿。", "天气": "语义：天气无法被带到会议上，这里应指可以携带的内容。", "空气": "配价：“把……带到”的宾语须是可携带之物，“空气”不能被带到会议上。", "雨": "语义：雨不能被带到会议上，与代表的行为不合。"}, "sentence_index": 6, "correct_answer": "民意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我听到一个好民意。", "explanation": "这里应该用〈消息〉。民意是群众的想法，不能用来指一条好消息。"}, {"text": "政府出台了新民意。", "explanation": "这里应该用〈政策〉。民意是群众的意愿，政府出台的规定要说政策。"}, {"text": "他说出了自己的民意。", "explanation": "这里应该用〈看法〉。民意指很多人的想法，个人的看法不能说民意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府应当充分尊重民意们。", "corrected_sentence": "政府应当充分尊重民意。", "error_description": "“民意”是抽象名词，不能加“们”表示复数。“民意们”是错误形式，应说“民意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告反映了民意地变化。", "corrected_sentence": "这份报告反映了民意的变化。", "error_description": "“民意”修饰“变化”时应用“的”，不能用“地”。“地”用于动词前作状语，名词后应为“的”。应为“民意的变化”，“民意地变化”是错误形式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93241, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
