INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93241, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上分是在游戏里让分数变多、排名往上。", "primary_collocate": null, "pronunciation": "shàng fēn", "ipa": "ʂɑŋ˥˩ fən˥", "syllable_count": 2, "sentences": [{"text": "今晚我想和朋友一起打游戏上分。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上都玩游戏，想早点上分。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个英雄很强，用它上分特别快。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天一直输，今天一定要上分。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥带我玩了三个小时，终于上分了。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想在排位赛里上分，要多和队友说话。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末他不出门，在家打游戏上分。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的游戏打得好，带我上分吧。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他玩了一晚上，一点儿也没上分。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用新手机玩游戏，上分比以前快多了。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上分了", "label": "体标：了"}, {"form": "上分过", "label": "体标：过"}], "register": "口语", "sense_fingerprint": "游戏中让分数变多、排名上升", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4240d01-219b-4bd2-9ad0-703dd789f62b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93241, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上分", "is_correct": true, "explanation": "正确答案。“上分”指在游戏里让分数变多、排名上升。"}, {"text": "上坟", "is_correct": false, "explanation": "“坟”与“分”只有第二个音节的声调不同（fén 与 fēn），意思是到墓地祭扫。"}, {"text": "上风", "is_correct": false, "explanation": "“风”与“分”韵母不同（fēng 与 fēn，-ng 与 -n），意思是占优势的位置。"}, {"text": "上粉", "is_correct": false, "explanation": "“粉”与“分”只有声调不同（fěn 与 fēn），意思是在食材或物体表面敷上一层粉。"}], "explanations": {"上分": "正确答案。“上分”指在游戏里让分数变多、排名上升。", "上坟": "“坟”与“分”只有第二个音节的声调不同（fén 与 fēn），意思是到墓地祭扫。", "上风": "“风”与“分”韵母不同（fēng 与 fēn，-ng 与 -n），意思是占优势的位置。", "上粉": "“粉”与“分”只有声调不同（fěn 与 fēn），意思是在食材或物体表面敷上一层粉。"}, "sentence_index": null, "correct_answer": "上分"}, "level_3": {"options": [{"text": "上分", "is_correct": true, "explanation": "正确。“上分”指在游戏里让分数变多，与“打游戏”搭配，符合句意。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：“写作业”与“和朋友一起打游戏”不能同时进行，句子不通。"}, {"text": "洗碗", "is_correct": false, "explanation": "搭配：“洗碗”不能与“打游戏”并列作为今晚想做的事，句中动作搭配不合理。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“一起打游戏”的意图相反，句子不通。"}], "explanations": {"上分": "正确。“上分”指在游戏里让分数变多，与“打游戏”搭配，符合句意。", "写作业": "语义：“写作业”与“和朋友一起打游戏”不能同时进行，句子不通。", "洗碗": "搭配：“洗碗”不能与“打游戏”并列作为今晚想做的事，句中动作搭配不合理。", "睡觉": "语义：“睡觉”与“一起打游戏”的意图相反，句子不通。"}, "sentence_index": 0, "correct_answer": "上分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的工资上分了两百块。", "explanation": "这里应该用〈涨〉。“上分”只用于游戏里的分数或段位，工资的增加要说“涨”。"}, {"text": "这家店的客流上分了很多。", "explanation": "这里应该用〈增长〉。“上分”只用于游戏里的分数或段位，客流的增加要说“增长”。"}, {"text": "我的体重一直在上分，已经胖了五公斤。", "explanation": "这里应该用〈上升〉。“上分”只用于游戏里的分数或段位，体重的增加要说“上升”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93241, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上分", "is_correct": true, "explanation": "正确。“上分”指在游戏里让分数变多，与“在家打游戏”搭配，符合句意。"}, {"text": "逛街", "is_correct": false, "explanation": "搭配：“逛街”需要到外面去，与“在家”的地点不搭配。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”要出门走动，与句中的“不出门”矛盾。"}, {"text": "买菜", "is_correct": false, "explanation": "语义：“买菜”要到外面的市场去，与句中的“不出门”矛盾。"}], "explanations": {"上分": "正确。“上分”指在游戏里让分数变多，与“在家打游戏”搭配，符合句意。", "逛街": "搭配：“逛街”需要到外面去，与“在家”的地点不搭配。", "散步": "语义：“散步”要出门走动，与句中的“不出门”矛盾。", "买菜": "语义：“买菜”要到外面的市场去，与句中的“不出门”矛盾。"}, "sentence_index": 6, "correct_answer": "上分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他练习书法很认真，一个月就上分很多。", "explanation": "这里应该用〈进步〉。“上分”指游戏里的分数或段位上升，书法水平的提高要说“进步”。"}, {"text": "这个月我的收入上分了不少。", "explanation": "这里应该用〈增加〉。“上分”只用于游戏，收入的增加要说“增加”。"}, {"text": "今年的物价上分了很多。", "explanation": "这里应该用〈上涨〉。“上分”指游戏中分数上升，物价的上涨要说“上涨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93241, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这局他上分了三十分，排名一下子升了很多。", "corrected_sentence": "这局他上了三十分，排名一下子升了很多。", "error_description": "错误形式“上分了三十分”重复了“分”，“上分”已是动宾结构，不能再接数量词。正确形式是离合用法“上了三十分”，即在“上”和“分”之间插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93241, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一晚他上分三分，队友很高兴。", "corrected_sentence": "这一晚他上了三分，队友很高兴。", "error_description": "“上分”本身是动宾结构，后面不能再接数量词“三分”。应说“上了三分”，表示分数上升三分。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93243, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
