INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93243, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "民生是老百姓过日子的事，比如吃饭、住房。", "primary_collocate": null, "pronunciation": "mín shēng", "ipa": "min˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "吃饭和住房都是民生大事。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府每年都花很多钱在民生上。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议主要谈民生。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人看病难，也是民生的大事。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很关心民生，常常去市场看看菜价。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜价上涨，影响了民生。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长说：“民生无小事。”", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校、医院和住房，都是民生的内容。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好政府要先把民生做好。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里常常说到民生。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "民生问题", "label": "复合词"}, {"form": "民生工程", "label": "复合词"}], "register": "书面", "sense_fingerprint": "老百姓日常生活中的吃饭、住房等具体事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e91c0d-146f-4be2-97f8-2129581fbe82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93243, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民族", "is_correct": false, "explanation": "语义：民族指人群共同体，不指吃饭、住房等日常事务。"}, {"text": "民权", "is_correct": false, "explanation": "语义：民权指公民的政治权利，与吃饭、住房不相符。"}, {"text": "民生", "is_correct": true, "explanation": "正确：吃饭、住房是老百姓过日子的事，是“民生大事”。"}, {"text": "民心", "is_correct": false, "explanation": "搭配：“民心”指人心向背，多说“得民心”“失民心”，不说“民心大事”，吃饭、住房也不是民心。"}], "explanations": {"民族": "语义：民族指人群共同体，不指吃饭、住房等日常事务。", "民权": "语义：民权指公民的政治权利，与吃饭、住房不相符。", "民生": "正确：吃饭、住房是老百姓过日子的事，是“民生大事”。", "民心": "搭配：“民心”指人心向背，多说“得民心”“失民心”，不说“民心大事”，吃饭、住房也不是民心。"}, "sentence_index": 0, "correct_answer": "民生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "多锻炼能保持民生。", "explanation": "这里应该用〈健康〉。保持的是健康、体力，民生指老百姓的吃饭、住房等事务。"}, {"text": "他有一手好民生。", "explanation": "这里应该用〈手艺〉。“一手好手艺”指技能，民生不是技能。"}, {"text": "这位画家的民生很大。", "explanation": "这里应该用〈名声〉。名声指别人对他的评价，民生不指名誉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93243, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "票房", "is_correct": false, "explanation": "语义：票房指电影的售票收入，与老百姓的生活无关，“票房无小事”表达不了这里的意思。"}, {"text": "夜宵", "is_correct": false, "explanation": "语义：夜宵是夜间吃的饭食，不指老百姓的生活事务，与“民生无小事”的说法不搭。"}, {"text": "民生", "is_correct": true, "explanation": "正确：“民生无小事”指老百姓的生活事务都很重要。"}, {"text": "相册", "is_correct": false, "explanation": "语义：相册指装照片的本子，与“无小事”的说法不搭。"}], "explanations": {"票房": "语义：票房指电影的售票收入，与老百姓的生活无关，“票房无小事”表达不了这里的意思。", "夜宵": "语义：夜宵是夜间吃的饭食，不指老百姓的生活事务，与“民生无小事”的说法不搭。", "民生": "正确：“民生无小事”指老百姓的生活事务都很重要。", "相册": "语义：相册指装照片的本子，与“无小事”的说法不搭。"}, "sentence_index": 6, "correct_answer": "民生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的民生很大，一生气就摔东西。", "explanation": "这里应该用〈脾气〉。脾气指性情，民生是老百姓的生活事务，不能用来形容性格。"}, {"text": "她的民生很苗条。", "explanation": "这里应该用〈身材〉。身材指体形，民生不能形容人的身形。"}, {"text": "她弹民生弹得很好。", "explanation": "这里应该用〈钢琴〉。弹的是钢琴、吉他等乐器，民生不能被弹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93243, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府今年又民生上投入了很多钱。", "corrected_sentence": "政府今年又在民生上投入了很多钱。", "error_description": "介词缺失：“在……上”表示方面，漏掉了“在”。应为“在民生上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93243, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府要把钱花民生上。", "corrected_sentence": "政府要把钱花在民生上。", "error_description": "介词缺失：“花在……上”表示用于某方面，漏掉了“在”。应为“花在民生上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
