INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93244, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人民的基本生活。", "primary_collocate": null, "pronunciation": "mín shēng", "ipa": "min˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "改善民生是政府的重要工作。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家把更多钱用在民生上。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项政策关系到民生。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民生问题得到了很好的解决。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里有一部分专门谈民生。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保障民生需要大家共同努力。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育和医疗是民生的重要内容。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展了，民生也会变好。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民生工作做得好，老百姓才满意。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写文章研究民生。", "target_word": "民生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "民生问题", "label": "复合词"}, {"form": "民生工程", "label": "复合词"}], "register": "书面", "sense_fingerprint": "人民基本生活状况，多用于政策与社会议题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e91c0d-146f-4be2-97f8-2129581fbe82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主权", "is_correct": false, "explanation": "搭配：“改善”一般搭配“生活”“条件”“环境”，“主权”应说“维护”。"}, {"text": "音响", "is_correct": false, "explanation": "语义：音响是音箱等设备，不是政府要改善的对象。"}, {"text": "词汇", "is_correct": false, "explanation": "语义：词汇是语言单位，政府不会把“改善词汇”当作重要工作。"}, {"text": "民生", "is_correct": true, "explanation": "正确：“改善”的对象是人民的基本生活。"}], "explanations": {"主权": "搭配：“改善”一般搭配“生活”“条件”“环境”，“主权”应说“维护”。", "音响": "语义：音响是音箱等设备，不是政府要改善的对象。", "词汇": "语义：词汇是语言单位，政府不会把“改善词汇”当作重要工作。", "民生": "正确：“改善”的对象是人民的基本生活。"}, "sentence_index": 0, "correct_answer": "民生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个运动员拿到了民生。", "explanation": "这里应该用〈金牌〉。拿到的是奖牌、奖品，民生不是可以拿到的东西。"}, {"text": "我的电脑出了民生，不能开机。", "explanation": "这里应该用〈故障〉。出的是故障、问题，民生不是机器的故障。"}, {"text": "他的民生很清楚。", "explanation": "这里应该用〈字迹〉。“字迹清楚”指书写的样子，民生指人民的生活，不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "股票", "is_correct": false, "explanation": "语义：股票是金融产品，不属于教育、医疗所在的内容范畴。"}, {"text": "赛场", "is_correct": false, "explanation": "语义：赛场是比赛的场地，教育和医疗不是赛场的内容。"}, {"text": "油水", "is_correct": false, "explanation": "语义：“油水”指额外的好处或食物中的油脂，教育和医疗不是油水的内容。"}, {"text": "民生", "is_correct": true, "explanation": "正确：教育、医疗属于人民的基本生活，是民生的内容。"}], "explanations": {"股票": "语义：股票是金融产品，不属于教育、医疗所在的内容范畴。", "赛场": "语义：赛场是比赛的场地，教育和医疗不是赛场的内容。", "油水": "语义：“油水”指额外的好处或食物中的油脂，教育和医疗不是油水的内容。", "民生": "正确：教育、医疗属于人民的基本生活，是民生的内容。"}, "sentence_index": 6, "correct_answer": "民生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冰箱里有很多民生。", "explanation": "这里应该用〈饮料〉。饮料可以放在冰箱里，民生不是物品。"}, {"text": "他得了民生。", "explanation": "这里应该用〈感冒〉。得的是病，民生不是病症。"}, {"text": "她把民生刷得很干净。", "explanation": "这里应该用〈鞋〉。刷的是鞋、衣服等物品，民生不能被刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国家今年把更多资金用民生上。", "corrected_sentence": "国家今年把更多资金用在民生上。", "error_description": "介词缺失：“用在……上”漏掉了“在”。应为“用在民生上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要把重心放民生上。", "corrected_sentence": "我们要把重心放在民生上。", "error_description": "介词缺失：“放在……上”表示位置，漏掉了“在”。应为“放在民生上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
