INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93245, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上去是从下面往上面去。", "primary_collocate": null, "pronunciation": "shàng qù", "ipa": "ʂaŋ˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "楼上有人等你，你快上去吧。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我上去拿一下书，马上下来。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯坏了，我们只能从楼梯上去。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶的风景很美，你想上去看看吗？", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在三楼，你可以上去找他。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把箱子搬到屋顶，然后自己也上去了。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台阶很高，我不敢一个人上去。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在下面等着，我上去看看。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，我们不要上去了。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她上去叫弟弟吃饭。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上去了", "label": "体标"}, {"form": "上去过", "label": "体标"}], "register": "中性", "sense_fingerprint": "独立作动词，从下面去上面（楼上、山上等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '624b5296-b316-469e-b898-2490f7fe2795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93245, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上去", "is_correct": true, "explanation": "正确：“上去”指从下往上去，楼上有人等你，应往上去。"}, {"text": "下去", "is_correct": false, "explanation": "语义：“下去”指向下去，与“楼上有人等你”的方向相反。"}, {"text": "出去", "is_correct": false, "explanation": "语义：“出去”指向外去，与楼上等人的语境不符。"}, {"text": "下来", "is_correct": false, "explanation": "搭配：“下来”指向说话人一方下行，与“楼上”的位置相冲突。"}], "explanations": {"上去": "正确：“上去”指从下往上去，楼上有人等你，应往上去。", "下去": "语义：“下去”指向下去，与“楼上有人等你”的方向相反。", "出去": "语义：“出去”指向外去，与楼上等人的语境不符。", "下来": "搭配：“下来”指向说话人一方下行，与“楼上”的位置相冲突。"}, "sentence_index": 0, "correct_answer": "上去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你上去吧，我在楼上等你。", "explanation": "这里应该用〈上来〉。说话人在楼上，对方应朝说话人所在处移动，用“上来”；“上去”指离开说话人向上去。"}, {"text": "他从楼上走上去，回到了一楼。", "explanation": "这里应该用〈下去〉。从楼上回到一楼是由高向低，应说“下去”；“上去”只表示由低向高。"}, {"text": "我们周末上去海边游泳。", "explanation": "这里应该用〈去〉。海边不是向上的方向，“上去”不用于水平移动的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93245, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上去", "is_correct": true, "explanation": "正确：“上去”指由低往高去，台阶很高，需要往上走。"}, {"text": "跌下去", "is_correct": false, "explanation": "语义：“跌下去”是向下坠落，与“台阶很高，我不敢一个人上去”所描述的向上动作相反。"}, {"text": "摔下去", "is_correct": false, "explanation": "语义：“摔”也指意外跌落，说“不敢摔下去”不合常理。"}, {"text": "上边", "is_correct": false, "explanation": "语法：“上边”是方位名词，不能放在“敢……一个人”后作动作。"}], "explanations": {"上去": "正确：“上去”指由低往高去，台阶很高，需要往上走。", "跌下去": "语义：“跌下去”是向下坠落，与“台阶很高，我不敢一个人上去”所描述的向上动作相反。", "摔下去": "语义：“摔”也指意外跌落，说“不敢摔下去”不合常理。", "上边": "语法：“上边”是方位名词，不能放在“敢……一个人”后作动作。"}, "sentence_index": 6, "correct_answer": "上去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她上去北京找工作。", "explanation": "这里应该用〈去〉。北京不是高处的目的地，“上去”只用于向上的移动。"}, {"text": "我们上去火车站接人。", "explanation": "这里应该用〈去〉。火车站不在高处，不能用“上去”。"}, {"text": "我在二楼，现在要上去一楼。", "explanation": "这里应该用〈下去〉。从二楼到一楼是向下，“上去”只表示向上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93245, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师在楼上，你快上去楼吧。", "corrected_sentence": "老师在楼上，你快上楼去吧。", "error_description": "错误形式「上去楼」；正确形式「上楼去」。「上去」不能直接带处所宾语，处所词要放在「上」和「去」之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93245, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他上去了拿一本书。", "corrected_sentence": "他上去拿了一本书。", "error_description": "“了”应放在动词“拿”之后，说“上去拿了一本书”；“上去了拿”把“了”插在补语和动词之间，不符合语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
