INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93246, 1, 'prompt1_core', '{"pos": "方向补语", "semantic_class": "function", "definition": "由低处向高处去。", "primary_collocate": null, "pronunciation": "shàng qù", "ipa": "ʂaŋ˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "小猫很快爬上去了。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他沿着楼梯跑上去。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球飞上去了，我拿不到。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她踩着椅子爬上去换灯。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路很陡，我们慢慢走上去。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跳上去坐在大石头上。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把梯子靠好，然后爬上去。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人走不动了，我扶着他走上去。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟一下子飞上去了。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座塔很高，我们一口气爬上去了。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上得去", "label": "可能补语"}, {"form": "上不去", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "放在动词后作方向补语，表示由低处向高处移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '624b5296-b316-469e-b898-2490f7fe2795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上去", "is_correct": true, "explanation": "正确：“爬上去”表示由低向高的动作，“上去”作方向补语。"}, {"text": "起去", "is_correct": false, "explanation": "语法：“起去”不是汉语的趋向补语，不能说“爬起去”。"}, {"text": "上不去", "is_correct": false, "explanation": "搭配：可能补语的否定形式与“很快”搭配不当。"}, {"text": "上着", "is_correct": false, "explanation": "语法：“上着”不能作“爬”的补语，“爬上着了”不成话。"}], "explanations": {"上去": "正确：“爬上去”表示由低向高的动作，“上去”作方向补语。", "起去": "语法：“起去”不是汉语的趋向补语，不能说“爬起去”。", "上不去": "搭配：可能补语的否定形式与“很快”搭配不当。", "上着": "语法：“上着”不能作“爬”的补语，“爬上着了”不成话。"}, "sentence_index": 0, "correct_answer": "上去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从山顶爬上去，走到了山脚下。", "explanation": "这里应该用〈下去〉。从山顶到山脚是由高向低，应说“下去”；“上去”只表示由低处向高处。"}, {"text": "他从树顶爬上去，回到了地面。", "explanation": "这里应该用〈下来〉或〈下去〉。从树顶到地面是由高向低，“上去”只表示向高处。"}, {"text": "鱼儿游上去，潜到了河底。", "explanation": "这里应该用〈游下去〉。河底在下方，应由高处向低处去，用“下去”；“上去”表示向高处去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上去", "is_correct": true, "explanation": "正确：“爬上去”指沿梯子向上，与“靠好梯子”的语境一致。"}, {"text": "上不来", "is_correct": false, "explanation": "语义：“上来”指向说话人一方，句中没有这个方向。"}, {"text": "起去", "is_correct": false, "explanation": "语法：“起去”不是趋向补语，不能说“爬起去”。"}, {"text": "高去", "is_correct": false, "explanation": "语法：“高去”不是趋向补语，不能说“爬高去”。"}], "explanations": {"上去": "正确：“爬上去”指沿梯子向上，与“靠好梯子”的语境一致。", "上不来": "语义：“上来”指向说话人一方，句中没有这个方向。", "起去": "语法：“起去”不是趋向补语，不能说“爬起去”。", "高去": "语法：“高去”不是趋向补语，不能说“爬高去”。"}, "sentence_index": 6, "correct_answer": "上去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把钱包往书包里放上去。", "explanation": "这里应该用〈放进去〉。书包里是容器，东西是放入的，不是向上移动，不能用“上去”。"}, {"text": "他从门口跑上去，到了大门外。", "explanation": "这里应该用〈出去〉。大门外不在高处，“上去”只用于向上的移动。"}, {"text": "他从桥上跳上去，掉进了河里。", "explanation": "这里应该用〈跳下去〉。河在桥下，是由高向低，“上去”只表示向高处移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他抓着绳子慢慢爬上去去。", "corrected_sentence": "他抓着绳子慢慢爬上去。", "error_description": "错误形式「他抓着绳子慢慢爬上去去」；正确形式「他抓着绳子慢慢爬上去」。「上去」本身已含「去」，后面不能再加一个「去」，多出的「去」应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猫咪轻轻跳上去沙发。", "corrected_sentence": "猫咪轻轻跳上沙发。", "error_description": "错误形式「跳上去沙发」；正确形式「跳上沙发」。「上去」是复合趋向补语，不能直接带处所名词，处所须接在「上」后，应说「跳上沙发」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93247, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短暂", "is_correct": true, "explanation": "短暂指时间很短，与“永恒”构成反义。"}, {"text": "宽广", "is_correct": false, "explanation": "宽广形容空间大，与“永恒”没有反义关系。"}, {"text": "厚重", "is_correct": false, "explanation": "厚重形容分量大或内容深，与“永恒”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚形容清晰、明白，与“永恒”没有反义关系。"}], "correct_answer": "短暂", "explanations": {"短暂": "短暂指时间很短，与“永恒”构成反义。", "宽广": "宽广形容空间大，与“永恒”没有反义关系。", "厚重": "厚重形容分量大或内容深，与“永恒”没有反义关系。", "清楚": "清楚形容清晰、明白，与“永恒”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93247, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短暂", "is_correct": true, "explanation": "短暂指时间很短，与“永恒”构成反义。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙形容表面不光滑，与“永恒”没有反义关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "狭窄形容空间小，与“永恒”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线强或颜色亮，与“永恒”没有反义关系。"}], "correct_answer": "短暂", "explanations": {"短暂": "短暂指时间很短，与“永恒”构成反义。", "粗糙": "粗糙形容表面不光滑，与“永恒”没有反义关系。", "狭窄": "狭窄形容空间小，与“永恒”没有反义关系。", "明亮": "明亮形容光线强或颜色亮，与“永恒”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93247, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "永恒是一直这样，永远不会变。", "primary_collocate": null, "pronunciation": "yǒng héng", "ipa": "yŋ˨˩˦ xɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个故事讲的是一份永恒的爱。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大海面前，人类的生命不是永恒的。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在教堂里许下了永恒的誓言。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间的感情，不一定是永恒的。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，只有变化才是永恒的。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗写的是爱情，也是永恒的美。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的主题是永恒的，几十年后也不会过时。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望我们的友谊永恒。", "target_word": "永恒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "金字塔在沙漠里站了几千年，看上去是永恒的。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能拥有永恒的青春。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "永恒不变", "label": "复合"}], "register": "书面", "sense_fingerprint": "永恒：一直这样，永远不会变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0806fb53-8715-4a01-946f-96193aca6881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93247, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永恒", "is_correct": true, "explanation": "永恒指一直这样、永远不会变，与“这个故事讲的是一份永恒的爱”相符。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：清脆形容声音，不能用来修饰爱。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：聪明指有智慧，爱不能说是聪明的。"}, {"text": "和蔼", "is_correct": false, "explanation": "搭配：和蔼修饰人的态度，不与“爱”搭配。"}], "explanations": {"永恒": "永恒指一直这样、永远不会变，与“这个故事讲的是一份永恒的爱”相符。", "清脆": "语义：清脆形容声音，不能用来修饰爱。", "聪明": "语义：聪明指有智慧，爱不能说是聪明的。", "和蔼": "搭配：和蔼修饰人的态度，不与“爱”搭配。"}, "sentence_index": 0, "correct_answer": "永恒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种涂料很永恒，刷一次能用好几年。", "explanation": "这里应该用〈持久〉。刷一次能用好几年说的是保持的时间长，要用持久；永恒指永远不变，不用来形容涂料。"}, {"text": "我们每周的例会时间是永恒的。", "explanation": "这里应该用〈固定〉。固定指规定好不变动，但不是永远不变，永恒不用来说具体的时间安排。"}, {"text": "他的规划很永恒，已经定到十年后。", "explanation": "这里应该用〈长远〉。长远指着眼于将来的时间长，永恒不用来形容规划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93247, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "永恒", "is_correct": true, "explanation": "永恒指永远不变，与“几十年后也不会过时”相符。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：陈旧即过时，与“几十年后也不会过时”矛盾。"}, {"text": "短暂", "is_correct": false, "explanation": "语义：短暂说时间不长，与“几十年后也不会过时”矛盾。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：热闹形容场面或气氛，不用来形容主题。"}], "explanations": {"永恒": "永恒指永远不变，与“几十年后也不会过时”相符。", "陈旧": "语义：陈旧即过时，与“几十年后也不会过时”矛盾。", "短暂": "语义：短暂说时间不长，与“几十年后也不会过时”矛盾。", "热闹": "搭配：热闹形容场面或气氛，不用来形容主题。"}, "sentence_index": 6, "correct_answer": "永恒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的眼光很永恒，总能看到未来。", "explanation": "这里应该用〈长远〉。长远指着眼于将来，永恒指永远不变，不用来形容眼光。"}, {"text": "这棵冬青一年四季永恒。", "explanation": "这里应该用〈常青〉。常青指植物一年四季都是绿的，永恒不用来描述植物的颜色或季节。"}, {"text": "这件外套很永恒，穿了很多年也不会坏。", "explanation": "这里应该用〈耐用〉。耐用指经久使用不坏，永恒指永远不变，不用来形容衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
