INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93248, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "永远不变；恒久。", "primary_collocate": null, "pronunciation": "yǒng héng", "ipa": "yŋ˨˩˦ xɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "世界上没有什么东西是永恒的。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们发誓要让这份友谊永恒。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多诗人都写过永恒的爱情。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对科学家来说，真理是永恒的。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城像一幅永恒的画，几百年没有变过。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌唱出了永恒的主题：爱与和平。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星星在夜空中发出永恒的光。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她希望这一刻是永恒的。", "target_word": "永恒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "时间是永恒的，人的生命却很短。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有永恒的敌人，也没有永恒的朋友。", "target_word": "永恒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "永恒不变", "label": "复合"}], "register": "书面", "sense_fingerprint": "永恒：永远不变、恒久", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0806fb53-8715-4a01-946f-96193aca6881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93248, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永恒", "is_correct": true, "explanation": "永恒指永远不变、恒久，与“世界上没有什么东西是永恒的”相符。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：聪明指有智慧的人或动物，东西不能说是聪明的。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：活泼形容人或动物的性情，不用来描述东西。"}, {"text": "和蔼", "is_correct": false, "explanation": "搭配：和蔼修饰人的态度或神情，不与“东西”搭配。"}], "explanations": {"永恒": "永恒指永远不变、恒久，与“世界上没有什么东西是永恒的”相符。", "聪明": "语义：聪明指有智慧的人或动物，东西不能说是聪明的。", "活泼": "语义：活泼形容人或动物的性情，不用来描述东西。", "和蔼": "搭配：和蔼修饰人的态度或神情，不与“东西”搭配。"}, "sentence_index": 0, "correct_answer": "永恒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个会议很永恒，开了整整一下午。", "explanation": "这里应该用〈漫长〉。漫长指时间很长；永恒指永远不变，不用来说会议持续的时间。"}, {"text": "这台冰箱真永恒，用了十年还好好的。", "explanation": "这里应该用〈耐用〉。永恒说的是永远不变，不用来形容物品经久耐用。"}, {"text": "他已经拿到了这里的永恒居留权。", "explanation": "这里应该用〈永久〉。永久可以修饰居留权、居民身份，永恒是抽象概念，不用来修饰身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "永恒", "is_correct": true, "explanation": "永恒指永远不变，与“星星发出永恒的光”相符。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：响亮形容声音，不能用来修饰光。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：嘈杂形容声音杂乱，不能用来修饰光。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：沉重修饰负担、压力或心情，不与“光”搭配。"}], "explanations": {"永恒": "永恒指永远不变，与“星星发出永恒的光”相符。", "响亮": "语义：响亮形容声音，不能用来修饰光。", "嘈杂": "语义：嘈杂形容声音杂乱，不能用来修饰光。", "沉重": "搭配：沉重修饰负担、压力或心情，不与“光”搭配。"}, "sentence_index": 6, "correct_answer": "永恒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司制定了一份永恒的发展计划。", "explanation": "这里应该用〈长期〉。永恒指永远不变，不用来说计划的时间长短。"}, {"text": "这片竹林一年四季永恒。", "explanation": "这里应该用〈常青〉。常青指植物一年四季都是绿的，永恒不用来描述植物的颜色或季节。"}, {"text": "这种颜料的颜色很永恒，不容易褪色。", "explanation": "这里应该用〈持久〉。颜色不容易褪色说的是保持的时间长，要用持久；永恒指永远不变，不用来形容颜色的耐久。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
