INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93251, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "沙发是软软的、可以坐的大椅子。", "primary_collocate": null, "pronunciation": "shā fā", "ipa": "ʂa˥ fa˥", "syllable_count": 2, "sentences": [{"text": "我家客厅里有一张大沙发。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸坐在沙发上看电视。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个沙发很软，坐着很舒服。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫睡在沙发上。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们新买了一张红色的沙发。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友来了，我请他们坐到沙发上。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上他常常躺在沙发上看书。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在沙发上跳来跳去。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张沙发太旧了，该换新的了。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把书放在沙发旁边的桌子上。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "沙發", "label": "繁体"}], "register": "中性", "sense_fingerprint": "家里软软的、可以坐的大椅子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3e1b82-d785-4be0-9594-3915e54d0855') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93251, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沙发", "is_correct": true, "explanation": "沙发：软软的大椅子，摆在家中客厅正合适。"}, {"text": "名片", "is_correct": false, "explanation": "语义：名片很小，不能说“大名片”摆在客厅里。"}, {"text": "邮票", "is_correct": false, "explanation": "语义：邮票很小，与“大”不符，也不是客厅里摆的家具。"}, {"text": "车票", "is_correct": false, "explanation": "搭配：车票是凭证，不说“客厅里有一张大车票”。"}], "explanations": {"沙发": "沙发：软软的大椅子，摆在家中客厅正合适。", "名片": "语义：名片很小，不能说“大名片”摆在客厅里。", "邮票": "语义：邮票很小，与“大”不符，也不是客厅里摆的家具。", "车票": "搭配：车票是凭证，不说“客厅里有一张大车票”。"}, "sentence_index": 0, "correct_answer": "沙发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把沙发放进冰箱里冻一冻。", "explanation": "这里把“沙发”当成了能放进冰箱的小食物。沙发是很大的坐具，放不进冰箱，也不用冷冻。"}, {"text": "妈妈用沙发炒了一盘菜。", "explanation": "这里把“沙发”当成了炒菜的锅。沙发是供人坐的软椅，不能做饭。"}, {"text": "我每天早上喝一杯沙发。", "explanation": "这里把“沙发”当成了饮料。沙发是家具，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93251, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙发", "is_correct": true, "explanation": "沙发：可以躺在上面看书的软家具，与“躺在…上”搭配。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是挂在墙上写字用的，不能躺在上面看书。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“躺在…上”一般不说冰箱，冰箱也不能躺。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "体貌：垃圾桶又小又窄，躺不下人。"}], "explanations": {"沙发": "沙发：可以躺在上面看书的软家具，与“躺在…上”搭配。", "黑板": "语义：黑板是挂在墙上写字用的，不能躺在上面看书。", "冰箱": "搭配：“躺在…上”一般不说冰箱，冰箱也不能躺。", "垃圾桶": "体貌：垃圾桶又小又窄，躺不下人。"}, "sentence_index": 6, "correct_answer": "沙发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张沙发可以当衣柜，把衣服都挂在里面。", "explanation": "这里把“沙发”当成了放衣服的柜子来用。沙发是供人坐靠的软座椅，没有柜门和挂衣的空间，不能用来收衣服。"}, {"text": "这张沙发可以当桌子，用来摆放碗筷。", "explanation": "这里把“沙发”当成了摆放碗筷的平台来用。沙发是供人坐的软椅，不能摆碗筷。"}, {"text": "这张沙发亮得像灯，晚上可以照明。", "explanation": "这里把“沙发”说成了能发光照明的东西。沙发是供人坐的软座椅，不会发光，与它的用途不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93251, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想买一座新沙发。", "corrected_sentence": "我想买一张新沙发。", "error_description": "量词错误：“一座”应为“一张”。“座”用于山、桥、楼等大型固定的东西，沙发不能这样数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93251, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一台沙发搬到了阳台上。", "corrected_sentence": "他把一张沙发搬到了阳台上。", "error_description": "量词错误：“一台”应为“一张”。“台”用于机器、电器，沙发的量词是“张”或“套”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
