INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93252, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装有弹性衬垫的、可供多人坐靠的软座椅。", "primary_collocate": null, "pronunciation": "shā fā", "ipa": "ʂa˥ fa˥", "syllable_count": 2, "sentences": [{"text": "这张三人沙发可以坐三个人。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人们都坐在长沙发上聊天。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙发里的弹簧坏了，坐着不舒服。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的皮沙发又软又舒服。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在沙发上靠着说话。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一套布沙发放在客厅。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套沙发的垫子可以拿下来洗。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人靠在沙发上休息。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间太小，放不下大沙发。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙发的颜色和墙很配。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "沙發", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有弹性垫子、可供多人坐靠的软座椅", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3e1b82-d785-4be0-9594-3915e54d0855') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沙发", "is_correct": true, "explanation": "沙发：可供多人坐靠的软座椅，“三人沙发”说法正确。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸是纸张，不能坐人。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是平面的纸，不能坐三个人。"}, {"text": "车票", "is_correct": false, "explanation": "搭配：车票不说“三人”，也不能坐人。"}], "explanations": {"沙发": "沙发：可供多人坐靠的软座椅，“三人沙发”说法正确。", "报纸": "语义：报纸是纸张，不能坐人。", "地图": "语义：地图是平面的纸，不能坐三个人。", "车票": "搭配：车票不说“三人”，也不能坐人。"}, "sentence_index": 0, "correct_answer": "沙发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把沙发折起来放进了口袋。", "explanation": "这里把“沙发”当成了能装进口袋的小东西。沙发是可供多人坐的大软椅，不能放进口袋。"}, {"text": "我渴了，想喝一口沙发。", "explanation": "这里把“沙发”当成了饮料。沙发是坐具，不能喝。"}, {"text": "妹妹每天骑沙发去上学。", "explanation": "这里把“沙发”当成了交通工具。沙发是放在室内供人坐靠的，不能骑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙发", "is_correct": true, "explanation": "沙发：带有可拆垫子的软座椅，符合“垫子可以拿下来洗”。"}, {"text": "书", "is_correct": false, "explanation": "语义：书没有垫子，不能说“这套书的垫子”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，没有可以拿下来洗的垫子。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本没有可以拿下来洗的垫子。"}], "explanations": {"沙发": "沙发：带有可拆垫子的软座椅，符合“垫子可以拿下来洗”。", "书": "语义：书没有垫子，不能说“这套书的垫子”。", "冰箱": "语义：冰箱是电器，没有可以拿下来洗的垫子。", "课本": "语义：课本没有可以拿下来洗的垫子。"}, "sentence_index": 6, "correct_answer": "沙发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张沙发可以放菜，当餐桌用。", "explanation": "这里把“沙发”当成了摆菜吃饭的平台来用。沙发是供人坐靠的软座椅，不能用来摆菜。"}, {"text": "这张沙发能发光，晚上当灯用。", "explanation": "这里把“沙发”说成了能发光照明的东西。沙发是软座椅，不会发光，与它供人坐靠的用途不符。"}, {"text": "这张沙发可以打开，当门用。", "explanation": "这里把“沙发”说成了能开合、供人出入的东西。沙发不能开合，与它供人坐靠的用途不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
