INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把一台沙发擦干净了。", "corrected_sentence": "妈妈把一张沙发擦干净了。", "error_description": "量词错误：“一台”应为“一张”。“台”用于机器、电器，沙发的量词是“张”或“套”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
