INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93253, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "个别是只有一两个，不是大多数。", "primary_collocate": null, "pronunciation": "gè bié", "ipa": "kɤ˥˩ pje˧˥", "syllable_count": 2, "sentences": [{"text": "班里只有个别学生没带书。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个别同学今天迟到了。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜都很好吃，只有个别太咸。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个别人不喜欢这个办法，大多数人都同意。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是个别现象，不用太担心。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班都交了作业，只有个别人没交。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个别地方下雨，大部分地方天气很好。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果大多很新鲜，个别有点坏了。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个别老人不会用手机，多数人都会。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里只有个别人知道这件事。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "個別", "label": "繁体"}], "register": "中性", "sense_fingerprint": "极少数；只有一两个，不是大多数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'add8433b-3ae1-4b98-b82a-1589f89692b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93253, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "个别", "is_correct": true, "explanation": "“个别”指只有少数，与“只有”相符，句意通顺。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”指全体，与“只有”所限定的少数矛盾。"}, {"text": "大量", "is_correct": false, "explanation": "语义：“大量”说数量多，与“只有”的少数语境矛盾。"}, {"text": "寒冷", "is_correct": false, "explanation": "搭配：“寒冷”形容温度或气候，不能修饰“学生”。"}], "explanations": {"个别": "“个别”指只有少数，与“只有”相符，句意通顺。", "全部": "语义：“全部”指全体，与“只有”所限定的少数矛盾。", "大量": "语义：“大量”说数量多，与“只有”的少数语境矛盾。", "寒冷": "搭配：“寒冷”形容温度或气候，不能修饰“学生”。"}, "sentence_index": 0, "correct_answer": "个别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地区的个别人口很多。", "explanation": "这里应该用〈总〉。个别只表示单个或极少数，不能修饰整体的人口数量，与“很多”也互相矛盾。"}, {"text": "他每天只喝个别的水。", "explanation": "这里应该用〈少量〉。个别只指单个或极少数的人或事物，不能用来说水的份量。"}, {"text": "这次考试很容易，个别同学都及格了，没有一个不及格。", "explanation": "这里应该用〈所有〉。个别只表示一两个，而“没有一个不及格”说的是全体，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93253, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "个别", "is_correct": true, "explanation": "“个别”指少数地方，与“大部分”形成对比，句意通顺。"}, {"text": "整个", "is_correct": false, "explanation": "语义：“整个”指全部，与“大部分”的说法矛盾。"}, {"text": "晴朗", "is_correct": false, "explanation": "语义：“晴朗”指天气好，与“下雨”矛盾。"}, {"text": "冰冷", "is_correct": false, "explanation": "搭配：“冰冷”形容温度或触感，不能用来表示地方的范围。"}], "explanations": {"个别": "“个别”指少数地方，与“大部分”形成对比，句意通顺。", "整个": "语义：“整个”指全部，与“大部分”的说法矛盾。", "晴朗": "语义：“晴朗”指天气好，与“下雨”矛盾。", "冰冷": "搭配：“冰冷”形容温度或触感，不能用来表示地方的范围。"}, "sentence_index": 6, "correct_answer": "个别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班个别同学都参加了比赛，一个也没缺。", "explanation": "这里应该用〈所有〉。个别只表示一两个，而“一个也没缺”说的是全体，二者矛盾。"}, {"text": "我只有个别钱了。", "explanation": "这里应该用〈一点〉。个别指单个或极少数，不能用来说钱的多少。"}, {"text": "这个学校的个别学生有一千多人。", "explanation": "这里应该用〈全体〉。个别只表示只有一两个，与“一千多人”的规模相矛盾，应说“全体学生有一千多人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93253, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "只有个别个同学没交作业。", "corrected_sentence": "只有个别同学没交作业。", "error_description": "错误在量词“个”：“个别”直接修饰名词，后面不加量词，应说“个别同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93253, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次检查只发现个别了问题。", "corrected_sentence": "这次检查只发现个别问题。", "error_description": "错误在体标：“了”不能插在“个别”和名词之间，“个别”修饰名词时后面直接接名词，应说“只发现个别问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
