INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93255, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "洗澡是用水把全身洗干净。", "primary_collocate": null, "pronunciation": "xǐ zǎo", "ipa": "ɕi²¹⁴ tsɑʊ²¹⁴", "syllable_count": 2, "sentences": [{"text": "我每天晚上睡觉前都洗澡。", "target_word": "洗澡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在洗澡，你等一下再打电话。", "target_word": "洗澡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太热了，我想回家洗澡。", "target_word": "洗澡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子身上都是泥，妈妈让他快去洗澡。", "target_word": "洗澡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我洗澡洗了半个小时。", "target_word": "洗澡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天洗澡要用热水。", "target_word": "洗澡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天跑步以后都要洗澡。", "target_word": "洗澡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢洗澡的时候唱歌。", "target_word": "洗澡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗不爱洗澡，一看到水就跑。", "target_word": "洗澡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你洗澡的时候把门关好。", "target_word": "洗澡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "洗个澡", "label": "离合"}, {"form": "洗了澡", "label": "体标"}, {"form": "洗过澡", "label": "体标"}, {"form": "洗澡水", "label": "复合"}], "register": "口语", "sense_fingerprint": "洗澡：用水把全身洗干净", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ef20229-854f-45a8-be5e-aab94d82e2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗澡", "is_correct": true, "explanation": "正确：洗澡指用水把全身洗干净，符合“睡觉前每天都做”的习惯。"}, {"text": "起床", "is_correct": false, "explanation": "语义：起床是早上的动作，与“睡觉前”的时间相反。"}, {"text": "上班", "is_correct": false, "explanation": "语义：上班在白天进行，与“每天晚上睡觉前”的时间不符。"}, {"text": "理发", "is_correct": false, "explanation": "搭配：理发一般要去理发店或找人理，不说“睡觉前都理发”这样的日常习惯。"}], "explanations": {"洗澡": "正确：洗澡指用水把全身洗干净，符合“睡觉前每天都做”的习惯。", "起床": "语义：起床是早上的动作，与“睡觉前”的时间相反。", "上班": "语义：上班在白天进行，与“每天晚上睡觉前”的时间不符。", "理发": "搭配：理发一般要去理发店或找人理，不说“睡觉前都理发”这样的日常习惯。"}, "sentence_index": 0, "correct_answer": "洗澡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很脏，要洗澡。", "explanation": "这里应该用〈洗〉。衣服不能洗澡，清洗衣物直接说洗。"}, {"text": "这辆车脏了，该洗澡了。", "explanation": "这里应该用〈洗车〉。洗澡只用于人或动物，给车清洗要说洗车。"}, {"text": "碗都脏了，快去洗澡。", "explanation": "这里应该用〈洗碗〉。洗澡只用于清洗人的身体，洗碗盘要说洗碗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗澡", "is_correct": true, "explanation": "正确：跑步以后洗澡是常见的习惯，符合句意。"}, {"text": "上学", "is_correct": false, "explanation": "语义：上学是白天去学校的事，与“跑步以后”的习惯不相关。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试与跑步后的习惯没有关系，句意不通。"}, {"text": "办公", "is_correct": false, "explanation": "搭配：办公一般指在办公室工作，不说“跑步以后都要办公”。"}], "explanations": {"洗澡": "正确：跑步以后洗澡是常见的习惯，符合句意。", "上学": "语义：上学是白天去学校的事，与“跑步以后”的习惯不相关。", "考试": "语义：考试与跑步后的习惯没有关系，句意不通。", "办公": "搭配：办公一般指在办公室工作，不说“跑步以后都要办公”。"}, "sentence_index": 6, "correct_answer": "洗澡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些苹果很脏，要洗澡。", "explanation": "这里应该用〈清洗〉。洗澡只用于人或动物，给水果清洁要说清洗。"}, {"text": "这台电脑很脏，要洗澡。", "explanation": "这里应该用〈清理〉。洗澡只用于人或动物，电脑要说清理。"}, {"text": "这双鞋很脏，要洗澡。", "explanation": "这里应该用〈刷〉。洗澡只用于人或动物，鞋子脏了要说刷鞋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天早上都洗澡个。", "corrected_sentence": "他每天早上都洗个澡。", "error_description": "“个”放错了位置。“洗澡”是离合词，量词“个”要放在“洗”和“澡”之间，应说“洗个澡”，不说“洗澡个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跑步以后已经洗澡过了。", "corrected_sentence": "他跑步以后已经洗过澡了。", "error_description": "体标位置错误：“洗澡”是离合词，“过”要放在“洗”和“澡”之间，应说“洗过澡”，不说“洗澡过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
