INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93257, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "前事是以前发生的事。", "primary_collocate": null, "pronunciation": "qián shì", "ipa": "tɕʰjɛn˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "前事已经过去，我们不要再提了。", "target_word": "前事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少对别人讲自己的前事。", "target_word": "前事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人坐在椅子上，慢慢想起前事。", "target_word": "前事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常回想前事，从中学到了很多东西。", "target_word": "前事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友笑着说：“前事就不要提了。”", "target_word": "前事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把前事都写在日记里。", "target_word": "前事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一提起前事，他就叹气。", "target_word": "前事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要记住前事，才不会再犯同样的错误。", "target_word": "前事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对前事一点也不后悔。", "target_word": "前事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前事无论多么难忘，也要向前看。", "target_word": "前事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "以前发生过的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80c6695f-4d15-45b9-91eb-7195eb7df105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93257, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前事", "is_correct": true, "explanation": "正确答案：前事（qián shì），指以前发生的事。"}, {"text": "前史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是前代的历史。"}, {"text": "强势", "is_correct": false, "explanation": "qiáng 与 qián 韵母不同（ang 与 an），意思是强硬、有气势。"}, {"text": "情势", "is_correct": false, "explanation": "qíng 与 qián 韵母不同（ing 与 an），意思是形势、局势。"}, {"text": "前十", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是排在前面的十个。"}], "explanations": {"前事": "正确答案：前事（qián shì），指以前发生的事。", "前史": "shǐ（第三声）与 shì（第四声）声调不同，意思是前代的历史。", "强势": "qiáng 与 qián 韵母不同（ang 与 an），意思是强硬、有气势。", "情势": "qíng 与 qián 韵母不同（ing 与 an），意思是形势、局势。", "前十": "shí（第二声）与 shì（第四声）声调不同，意思是排在前面的十个。"}, "sentence_index": null, "correct_answer": "前事"}, "level_3": {"options": [{"text": "前事", "is_correct": true, "explanation": "正确：“前事”指以前发生的事，与“已经过去”“不要再提了”相合。"}, {"text": "未来", "is_correct": false, "explanation": "语义：“未来”还没有到，不能说“已经过去”。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“提”后接的是事情、话题，不接“天空”这类自然景物。"}, {"text": "眼前", "is_correct": false, "explanation": "语义：“眼前”指当下，不能说“已经过去”。"}], "explanations": {"前事": "正确：“前事”指以前发生的事，与“已经过去”“不要再提了”相合。", "未来": "语义：“未来”还没有到，不能说“已经过去”。", "天空": "搭配：“提”后接的是事情、话题，不接“天空”这类自然景物。", "眼前": "语义：“眼前”指当下，不能说“已经过去”。"}, "sentence_index": 0, "correct_answer": "前事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个年轻人的前事很光明，大家都看好他。", "explanation": "这里应该用〈前途〉。前途指将来的发展，前事指以前发生的事，二者时间方向相反。"}, {"text": "只有努力，才有成功的前事。", "explanation": "这里应该用〈前提〉。前提指事情成立的条件，前事指以前发生的事，此处要说的是成功的条件。"}, {"text": "这个行业的前事很好，很多人都想进来。", "explanation": "这里应该用〈前景〉。前景指将来的发展趋势，前事指以前发生的事，不能用来说行业的发展方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93257, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "前事", "is_correct": true, "explanation": "正确答案：前事（qián shì），指以前发生的事。"}, {"text": "闲事", "is_correct": false, "explanation": "xián 与 qián 声母不同（x 与 q），意思是与自己无关的事。"}, {"text": "年事", "is_correct": false, "explanation": "nián 与 qián 声母不同（n 与 q），意思是年纪、岁数。"}, {"text": "浅视", "is_correct": false, "explanation": "qiǎn（第三声）与 qián（第二声）声调不同，意思是目光短浅。"}, {"text": "前志", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是先前的志向。"}], "explanations": {"前事": "正确答案：前事（qián shì），指以前发生的事。", "闲事": "xián 与 qián 声母不同（x 与 q），意思是与自己无关的事。", "年事": "nián 与 qián 声母不同（n 与 q），意思是年纪、岁数。", "浅视": "qiǎn（第三声）与 qián（第二声）声调不同，意思是目光短浅。", "前志": "zhì 与 shì 声母不同（zh 与 sh），意思是先前的志向。"}, "sentence_index": null, "correct_answer": "前事"}, "level_3": {"options": [{"text": "前事", "is_correct": true, "explanation": "正确：“前事”指以前发生的事，与“叹气”的感伤语境相合。"}, {"text": "喜事", "is_correct": false, "explanation": "语义：“喜事”是令人高兴的事，与“他就叹气”相矛盾。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“提起”后接的是事情、话题，不接“蛋糕”这类具体食物。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“提起”后接的是事情、话题，不接“窗户”这类具体物件。"}], "explanations": {"前事": "正确：“前事”指以前发生的事，与“叹气”的感伤语境相合。", "喜事": "语义：“喜事”是令人高兴的事，与“他就叹气”相矛盾。", "蛋糕": "搭配：“提起”后接的是事情、话题，不接“蛋糕”这类具体食物。", "窗户": "搭配：“提起”后接的是事情、话题，不接“窗户”这类具体物件。"}, "sentence_index": 6, "correct_answer": "前事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在比赛中担任前事，进了两个球。", "explanation": "这里应该用〈前锋〉。前锋指球队中负责进攻的球员，前事指以前发生的事，不能用来指担任的职务。"}, {"text": "他前事去了北京，今天才回来。", "explanation": "这里应该用〈前天〉。前天指昨天的前一天，是时间词；前事指以前发生的事，不能用来表示时间。"}, {"text": "请在前事的路口向左拐。", "explanation": "这里应该用〈前面〉。前面指位置靠前的地方；前事指以前发生的事，不能表示方位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他常常想起一只前事，心里很不安。", "corrected_sentence": "他常常想起一件前事，心里很不安。", "error_description": "量词错误：“前事”是抽象名词，应该用量词“件”，说“一件前事”；“只”用于动物等，不能用来计量“前事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该很记住前事，这样才不会再吃亏。", "corrected_sentence": "我们应该牢牢记住前事，这样才不会再吃亏。", "error_description": "错误：“很”是程度副词，不能直接修饰动词“记住”；这里应该用副词“牢牢”，说“牢牢记住前事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
