INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93260, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "陆地上被陆地包围、积水较多的洼地水域。", "primary_collocate": null, "pronunciation": "hú pō", "ipa": "xu˧˥ pʰo˥˥", "syllable_count": 2, "sentences": [{"text": "这个省有很多湖泊。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖泊的水很清，也很深。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，湖泊周围开满了花。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片湖泊是附近最大的。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着湖泊走了一圈。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天湖泊里的水结冰了。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多鸟儿住在湖泊边上。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的湖泊比南方的少。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污水让这个湖泊变脏了。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在湖泊旁边住过两天。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "陆地上被陆地包围、积水较多的洼地水域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3e1b82-d785-4be0-9594-3915e54d0855') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”是广阔的大洋，一个省里不会有很多海洋"}, {"text": "太阳", "is_correct": false, "explanation": "语义：天上只有一个太阳，也不在省里，不能说“省有很多太阳”"}, {"text": "湖泊", "is_correct": true, "explanation": "湖泊：陆地上的积水洼地，一个省里可以有很多"}, {"text": "月亮", "is_correct": false, "explanation": "语义：天上只有一个月亮，不能说“很多月亮”"}], "explanations": {"海洋": "语义：“海洋”是广阔的大洋，一个省里不会有很多海洋", "太阳": "语义：天上只有一个太阳，也不在省里，不能说“省有很多太阳”", "湖泊": "湖泊：陆地上的积水洼地，一个省里可以有很多", "月亮": "语义：天上只有一个月亮，不能说“很多月亮”"}, "sentence_index": 0, "correct_answer": "湖泊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个湖泊今天感冒了，要请假休息。", "explanation": "这里应该用〈病人〉。病人会感冒、需要休息；湖泊不会生病。"}, {"text": "这个湖泊的盖子坏了，要换一个新的。", "explanation": "这里应该用〈锅〉。锅有盖子，湖泊是露天的水域，没有盖子。"}, {"text": "这片湖泊里插满了秧苗。", "explanation": "这里应该用〈水田〉。水田是用来插秧种稻的田地；湖泊是天然积水的水域，不能插秧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书桌", "is_correct": false, "explanation": "语义：“书桌”是家具，鸟儿不会住在书桌边上"}, {"text": "湖泊", "is_correct": true, "explanation": "湖泊：鸟儿常栖息在水边，与“边上”相符"}, {"text": "灯光", "is_correct": false, "explanation": "搭配：“边上”需要有实体的地点，“灯光”不能作为鸟儿住的位置"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”是室内物品，不是鸟儿栖息的地方"}], "explanations": {"书桌": "语义：“书桌”是家具，鸟儿不会住在书桌边上", "湖泊": "湖泊：鸟儿常栖息在水边，与“边上”相符", "灯光": "搭配：“边上”需要有实体的地点，“灯光”不能作为鸟儿住的位置", "闹钟": "语义：“闹钟”是室内物品，不是鸟儿栖息的地方"}, "sentence_index": 6, "correct_answer": "湖泊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个湖泊一直向东流去。", "explanation": "这里应该用〈河流〉。湖泊是静止的积水，不会流动；流动的水要用河流"}, {"text": "湖泊从山崖上直直地落下来。", "explanation": "这里应该用〈瀑布〉。瀑布是水从高处落下，湖泊不会从高处落下"}, {"text": "湖泊弯弯曲曲地流向远方。", "explanation": "这里应该用〈小溪〉。小溪是流动的水，湖泊是静止的，不能弯弯曲曲地流向远方"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村子旁边有一棵湖泊。", "corrected_sentence": "村子旁边有一个湖泊。", "error_description": "“湖泊”前应用量词“个”或“片”，“棵”用于树木，不能用来数湖泊。正确说法：村子旁边有一个湖泊。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那些湖泊们都很大。", "corrected_sentence": "那些湖泊都很大。", "error_description": "“湖泊”是无生命的事物，不能加“们”表示复数，应直接说“那些湖泊”。正确说法：那些湖泊都很大。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
