INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93262, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到某处来。", "primary_collocate": null, "pronunciation": "qián lái", "ipa": "tɕʰjɛn˧˥ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "每年都有很多游客前来旅游。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪天里，村民们前来领取粮食。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员接到电话后马上前来救火。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多家长前来学校开会。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数百名观众前来观看比赛。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生前来检查病人的情况。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他专程前来这里祝贺我们。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不少学生前来图书馆借书。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人前来法院说明情况。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民前来参观新建的公园。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前来了", "label": "体标"}, {"form": "前来过", "label": "体标"}, {"form": "前來", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人为了某事到某个地方来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de67917-7f36-4640-ba0a-be9730ecd119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讲解", "is_correct": false, "explanation": "搭配：“讲解”用于讲述内容或景物，不能说讲解旅游。"}, {"text": "逃离", "is_correct": false, "explanation": "语义：“逃离”表示逃开，与游客前来旅游的意思相反。"}, {"text": "维修", "is_correct": false, "explanation": "搭配：“维修”的对象是设备或建筑，不能用于旅游。"}, {"text": "前来", "is_correct": true, "explanation": "前来：到某处来，与“游客”和“旅游”搭配。"}], "explanations": {"讲解": "搭配：“讲解”用于讲述内容或景物，不能说讲解旅游。", "逃离": "语义：“逃离”表示逃开，与游客前来旅游的意思相反。", "维修": "搭配：“维修”的对象是设备或建筑，不能用于旅游。", "前来": "前来：到某处来，与“游客”和“旅游”搭配。"}, "sentence_index": 0, "correct_answer": "前来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题前来了三年。", "explanation": "这里应该用〈存在〉。前来指人为某事到某处来，不能用来描述问题持续的时间，应用存在。"}, {"text": "这本书前来桌子上。", "explanation": "这里应该用〈放〉。前来指人到某处来，书不能自己走过去，把书放到桌上要用放。"}, {"text": "他的病前来了很久。", "explanation": "这里应该用〈拖〉。前来表示到某处来，病持续的时间要用拖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻视", "is_correct": false, "explanation": "语义：“轻视”表示看不起，与“专程祝贺”的态度相反。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”的对象是乐曲，不能与指向地点的“这里”搭配。"}, {"text": "游玩", "is_correct": false, "explanation": "语义：“游玩”指消遣娱乐，与“专程祝贺”的目的不符。"}, {"text": "前来", "is_correct": true, "explanation": "前来：到某处来，与“专程”和“这里”搭配，表示为祝贺而来。"}], "explanations": {"轻视": "语义：“轻视”表示看不起，与“专程祝贺”的态度相反。", "演奏": "搭配：“演奏”的对象是乐曲，不能与指向地点的“这里”搭配。", "游玩": "语义：“游玩”指消遣娱乐，与“专程祝贺”的目的不符。", "前来": "前来：到某处来，与“专程”和“这里”搭配，表示为祝贺而来。"}, "sentence_index": 6, "correct_answer": "前来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子前来房间里。", "explanation": "这里应该用〈搬〉。前来指人到某处来，椅子不能自己来，把椅子搬进房间要用搬。"}, {"text": "这位老人前来了八十岁。", "explanation": "这里应该用〈活〉。前来表示朝某处来，人的年龄要用活。"}, {"text": "这家店前来了一年。", "explanation": "这里应该用〈开〉。前来表示朝某处来，店铺营业的时间要用开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多游客被前来我们学校参观。", "corrected_sentence": "很多游客前来我们学校参观。", "error_description": "错误形式：“被前来”，“前来”是不及物动词，不能用“被”构成被动句。正确形式：“前来”。原因：“前来”后直接接处所宾语，前面加“被”后句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明年他会前来过我们学校。", "corrected_sentence": "明年他会前来我们学校。", "error_description": "错误形式：“前来过”。正确形式：“前来”。原因：“过”表示经历，句中指将来，不能用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
