INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93263, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "生动是讲得或画得特别像真的一样。", "primary_collocate": null, "pronunciation": "shēng dòng", "ipa": "ʂɤŋ˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师把这个故事讲得很生动。", "target_word": "生动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画的小猫非常生动。", "target_word": "生动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这篇文章把春天写得很生动。", "target_word": "生动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把那天的事讲得很生动，我们像看到了一样。", "target_word": "生动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画里的小鸟画得很生动。", "target_word": "生动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小说里的人物写得非常生动。", "target_word": "生动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作者用几句话就把雨夜写得很生动。", "target_word": "生动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲鬼故事讲得特别生动，孩子们都不敢睡了。", "target_word": "生动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家画的马很生动，像要跑出来一样。", "target_word": "生动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游把古城的历史讲得很生动。", "target_word": "生动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生动形象", "label": "复合"}, {"form": "生动活泼", "label": "复合"}], "register": "中性", "sense_fingerprint": "讲述或描画得像真的一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9732594-50f6-455c-99d9-7791dffce9b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93263, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的身形，不能用来修饰“讲”。"}, {"text": "生动", "is_correct": true, "explanation": "正确。“讲得很生动”指讲述得特别像真的一样，符合句意。"}, {"text": "沉默", "is_correct": false, "explanation": "搭配：“沉默”形容人的状态，不能说“讲得很沉默”。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”指体形或形象宏伟，与讲故事的方式无关。"}], "explanations": {"胖": "体貌：“胖”形容人或动物的身形，不能用来修饰“讲”。", "生动": "正确。“讲得很生动”指讲述得特别像真的一样，符合句意。", "沉默": "搭配：“沉默”形容人的状态，不能说“讲得很沉默”。", "高大": "语义：“高大”指体形或形象宏伟，与讲故事的方式无关。"}, "sentence_index": 0, "correct_answer": "生动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份药品说明书的剂量写得很生动。", "explanation": "这里应该用〈清楚〉。药品剂量要求写得清楚准确，生动用于把故事或画面讲得、画得像真的一样，不能形容剂量说明。"}, {"text": "这份财务报告里的数字列得很生动。", "explanation": "这里应该用〈准确〉。生动形容讲述或描绘鲜活，报告里的数字要求准确。"}, {"text": "这台仪器的读数报得很生动。", "explanation": "这里应该用〈精确〉。读数要求精确，生动用于描绘形象，不能用于仪器读数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冗长", "is_correct": false, "explanation": "语义：“几句话”说明篇幅很短，“冗长”与之相矛盾。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音，不能修饰“写”。"}, {"text": "生动", "is_correct": true, "explanation": "正确。“写得很生动”指描写得鲜活逼真，符合句意。"}, {"text": "迟钝", "is_correct": false, "explanation": "搭配：“迟钝”形容人的反应，不能用来形容“写”出的文字。"}], "explanations": {"冗长": "语义：“几句话”说明篇幅很短，“冗长”与之相矛盾。", "嘹亮": "搭配：“嘹亮”形容声音，不能修饰“写”。", "生动": "正确。“写得很生动”指描写得鲜活逼真，符合句意。", "迟钝": "搭配：“迟钝”形容人的反应，不能用来形容“写”出的文字。"}, "sentence_index": 6, "correct_answer": "生动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂生产的零件做得很生动。", "explanation": "这里应该用〈精密〉。零件要求精密，生动用于讲述或描绘得像真的一样，不能用来形容加工的零件。"}, {"text": "他把这份对账单核对得很生动。", "explanation": "这里应该用〈仔细〉。核对账单要求仔细，生动只用于描绘有趣的讲述或画面。"}, {"text": "这位工程师把桥梁的承重数据称得很生动。", "explanation": "这里应该用〈精确〉。称量数据要求精确，生动用于描绘讲述或画面，不能形容称量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐把童话讲很生动。", "corrected_sentence": "姐姐把童话讲得很生动。", "error_description": "“讲很生动”缺少补语标记“得”。应为“讲得很生动”，“得”引出“生动”作程度补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶说地很生动。", "corrected_sentence": "奶奶说得很生动。", "error_description": "“说地很生动”误用“地”。“地”标示状语，这里“生动”作补语，应用“得”：“说得很生动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
