INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93264, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "具有活力，能使人感受鲜明形象的。", "primary_collocate": null, "pronunciation": "shēng dòng", "ipa": "ʂɤŋ˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这节课很生动，学生们都爱听。", "target_word": "生动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的表情很生动。", "target_word": "生动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小朋友的语言很生动。", "target_word": "生动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个演员把老人演得很生动。", "target_word": "生动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用生动的例子解释了这个问题。", "target_word": "生动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇报道的语言很生动，读者很喜欢。", "target_word": "生动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师上课很生动，没有人想睡觉。", "target_word": "生动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的描述很生动，妈妈听得很开心。", "target_word": "生动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影里的人物很生动，我忘不了。", "target_word": "生动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "广告里的画面很生动，让人一下子记住了。", "target_word": "生动", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "生动形象", "label": "复合"}, {"form": "生动活泼", "label": "复合"}], "register": "中性", "sense_fingerprint": "有活力、形象鲜明，让人印象深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9732594-50f6-455c-99d9-7791dffce9b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93264, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空旷", "is_correct": false, "explanation": "语义：“空旷”指没有人或东西，与“学生们都爱听”相矛盾。"}, {"text": "害羞", "is_correct": false, "explanation": "配价：“害羞”要求有感情的人作主语，“这节课”不能害羞。"}, {"text": "生动", "is_correct": true, "explanation": "正确。“很生动”形容课堂有活力、让人印象深，符合句意。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或物的身形，不能用来形容一节课。"}], "explanations": {"空旷": "语义：“空旷”指没有人或东西，与“学生们都爱听”相矛盾。", "害羞": "配价：“害羞”要求有感情的人作主语，“这节课”不能害羞。", "生动": "正确。“很生动”形容课堂有活力、让人印象深，符合句意。", "瘦": "体貌：“瘦”形容人或物的身形，不能用来形容一节课。"}, "sentence_index": 0, "correct_answer": "生动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份财务报告的金额审得很生动。", "explanation": "这里应该用〈严格〉。审核金额要求严格，生动用于描绘讲述或画面，不能形容审核。"}, {"text": "这道数学题的答案算得很生动。", "explanation": "这里应该用〈正确〉。答案的计算要求正确，生动形容有活力、有形象的讲述，不能用来形容计算。"}, {"text": "这位工人把施工方案的图纸裁得很生动。", "explanation": "这里应该用〈整齐〉。裁切图纸要求整齐，生动用于描绘讲述或画面，不能形容裁切。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遥远", "is_correct": false, "explanation": "搭配：“遥远”形容距离或时间，不能修饰“上课”。"}, {"text": "生动", "is_correct": true, "explanation": "正确。“上课很生动”指课堂有活力，让人不想睡觉，符合句意。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”形容身材或物体的高度，不能用来形容上课。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指人少、没有生气，与“没有人想睡觉”的课堂氛围不合。"}], "explanations": {"遥远": "搭配：“遥远”形容距离或时间，不能修饰“上课”。", "生动": "正确。“上课很生动”指课堂有活力，让人不想睡觉，符合句意。", "高": "体貌：“高”形容身材或物体的高度，不能用来形容上课。", "冷清": "语义：“冷清”指人少、没有生气，与“没有人想睡觉”的课堂氛围不合。"}, "sentence_index": 6, "correct_answer": "生动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台复印机复印的文件很生动。", "explanation": "这里应该用〈清晰〉。复印件要求清晰，生动只用于描绘有活力的人或场景。"}, {"text": "这份工资单的数字算得很生动。", "explanation": "这里应该用〈准确〉。工资数字要求准确，生动不能用来形容计算。"}, {"text": "这份合同的印章盖得很生动。", "explanation": "这里应该用〈端正〉。盖印章要求端正，生动用于描绘讲述或画面，不能形容盖印。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师讲很生动。", "corrected_sentence": "这位老师讲得很生动。", "error_description": "漏用补语标记：“讲很生动”应为“讲得很生动”，动词与补语之间要用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈唱地很生动。", "corrected_sentence": "妈妈唱得很生动。", "error_description": "“唱地很生动”误用“地”。这里“生动”作补语，应用“得”：“唱得很生动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
