INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93265, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "北方是太阳升起时，左手边的方向。", "primary_collocate": null, "pronunciation": "běi fāng", "ipa": "pei̯˨˩˦ faŋ˥", "syllable_count": 2, "sentences": [{"text": "太阳从东边出来，北方在你的左手边。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，我看着北方的星星。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上，北方在上面，南方在下面。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟向北方飞去了。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路往北方走，就是学校。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手指着北方，说那里是我家。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风从北方吹来，天气变冷了。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你面对北方，后面就是南方。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指南针的一头总是指向北方。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐的车正在向北方开。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "北方人", "label": "复合"}, {"form": "北方话", "label": "复合"}], "register": "中性", "sense_fingerprint": "方位词：四个方向中的北，指方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef5a13e9-5998-47ea-85ae-a1bc01b8e6de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93265, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "北方", "is_correct": true, "explanation": "北方：四个方向之一，与南方相对。"}, {"text": "北风", "is_correct": false, "explanation": "fēng（第一声）与 fāng（第一声）韵母不同（-eng 与 -ang），意思是从北边吹来的风。"}, {"text": "北房", "is_correct": false, "explanation": "fáng（第二声）与 fāng（第一声）声调不同，意思是朝北的房屋。"}, {"text": "美方", "is_correct": false, "explanation": "měi（第三声）与 běi（第三声）声母不同（m 与 b），意思是美国一方。"}, {"text": "本方", "is_correct": false, "explanation": "běn（第三声）与 běi（第三声）韵母不同（-en 与 -ei），意思是我方、本方。"}], "explanations": {"北方": "北方：四个方向之一，与南方相对。", "北风": "fēng（第一声）与 fāng（第一声）韵母不同（-eng 与 -ang），意思是从北边吹来的风。", "北房": "fáng（第二声）与 fāng（第一声）声调不同，意思是朝北的房屋。", "美方": "měi（第三声）与 běi（第三声）声母不同（m 与 b），意思是美国一方。", "本方": "běn（第三声）与 běi（第三声）韵母不同（-en 与 -ei），意思是我方、本方。"}, "sentence_index": null, "correct_answer": "北方"}, "level_3": {"options": [{"text": "北方", "is_correct": true, "explanation": "北方：四个方向之一，与南方相对，这里指方位。"}, {"text": "早晨", "is_correct": false, "explanation": "语义：“早晨”是时间，不能用作“在你的左手边”的处所。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”指季节，表示时间，不能说它在哪一边。"}, {"text": "下午", "is_correct": false, "explanation": "语义：“下午”是时间，不能说它在你的左手边。"}], "explanations": {"北方": "北方：四个方向之一，与南方相对，这里指方位。", "早晨": "语义：“早晨”是时间，不能用作“在你的左手边”的处所。", "春天": "语义：“春天”指季节，表示时间，不能说它在哪一边。", "下午": "语义：“下午”是时间，不能说它在你的左手边。"}, "sentence_index": 0, "correct_answer": "北方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用北方喝了一杯水。", "explanation": "这里应该用〈杯子〉。北方指方向，不能用来喝水。"}, {"text": "妈妈给我买了一件新北方。", "explanation": "这里应该用〈衣服〉。北方指方向，不能穿。"}, {"text": "这间屋子的北方有一扇窗。", "explanation": "这里应该用〈北面〉。北方不用来指房间某一侧的位置，要说北面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93265, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "北方", "is_correct": true, "explanation": "北方：这里指风的来源方向，与南方相对。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”是时间，不能作风吹来的来源地点。"}, {"text": "星期三", "is_correct": false, "explanation": "语义：“星期三”是时间词，不能表示风从哪里来。"}, {"text": "北风", "is_correct": false, "explanation": "搭配：“北风”已含“风”，与“风从……吹来”重复，句中不能再作来源。"}], "explanations": {"北方": "北方：这里指风的来源方向，与南方相对。", "昨天": "语义：“昨天”是时间，不能作风吹来的来源地点。", "星期三": "语义：“星期三”是时间词，不能表示风从哪里来。", "北风": "搭配：“北风”已含“风”，与“风从……吹来”重复，句中不能再作来源。"}, "sentence_index": 6, "correct_answer": "北方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用北方写了一封信。", "explanation": "这里应该用〈笔〉。北方指方向或地区，不能作书写工具，要说笔。"}, {"text": "天冷了，我穿上北方出门。", "explanation": "这里应该用〈外套〉。北方指方向，不能穿在身上。"}, {"text": "这个北方很甜，我还想吃。", "explanation": "这里应该用〈苹果〉。北方指方向，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93265, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "船一直向北方边行驶。", "corrected_sentence": "船一直向北方行驶。", "error_description": "错误：“北方”后面多加了“边”。北方本身已表示方向，不能再加“边”。正确形式是“向北方行驶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93265, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们北方走了很远。", "corrected_sentence": "我们往北方走了很远。", "error_description": "错误：“北方”前漏掉了方向介词“往”。正确形式是“往北方走”，表示朝这个方向前进。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
