INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93266, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指国家北部地区，与南方相对。", "primary_collocate": null, "pronunciation": "běi fāng", "ipa": "pei̯˨˩˦ faŋ˥", "syllable_count": 2, "sentences": [{"text": "北方的冬天很冷，常常下雪。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家在北方，爱吃面条。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的冬天有暖气，南方没有。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的北方种很多小麦。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从南方来到北方工作。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方过年的时候，家家都吃饺子。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的夏天不太热。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市在中国的北方。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的菜比较咸，南方的菜比较甜。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的春天来得晚，风也很大。", "target_word": "北方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "北方人", "label": "复合"}, {"form": "北方话", "label": "复合"}], "register": "中性", "sense_fingerprint": "地区词：指国家北部地区，与南方相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef5a13e9-5998-47ea-85ae-a1bc01b8e6de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93266, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "北方", "is_correct": true, "explanation": "北方：指国家北部地区，与南方相对。"}, {"text": "北风", "is_correct": false, "explanation": "fēng（第一声）与 fāng（第一声）韵母不同（-eng 与 -ang），意思是从北边吹来的风。"}, {"text": "北房", "is_correct": false, "explanation": "fáng（第二声）与 fāng（第一声）声调不同，意思是朝北的房屋。"}, {"text": "美方", "is_correct": false, "explanation": "měi（第三声）与 běi（第三声）声母不同（m 与 b），意思是美国一方。"}, {"text": "本方", "is_correct": false, "explanation": "běn（第三声）与 běi（第三声）韵母不同（-en 与 -ei），意思是我方、本方。"}], "explanations": {"北方": "北方：指国家北部地区，与南方相对。", "北风": "fēng（第一声）与 fāng（第一声）韵母不同（-eng 与 -ang），意思是从北边吹来的风。", "北房": "fáng（第二声）与 fāng（第一声）声调不同，意思是朝北的房屋。", "美方": "měi（第三声）与 běi（第三声）声母不同（m 与 b），意思是美国一方。", "本方": "běn（第三声）与 běi（第三声）韵母不同（-en 与 -ei），意思是我方、本方。"}, "sentence_index": null, "correct_answer": "北方"}, "level_3": {"options": [{"text": "北方", "is_correct": true, "explanation": "北方：指国家北部地区，与南方相对，这里指地区。"}, {"text": "早晨", "is_correct": false, "explanation": "语义：“早晨”是一天中的时段，不能说“早晨的冬天”。"}, {"text": "星期一", "is_correct": false, "explanation": "语义：“星期一”是时间词，不能用作表示地区的修饰语。"}, {"text": "北", "is_correct": false, "explanation": "搭配：“北”单用时不作地区名词，要说“北方”或“北部”。"}], "explanations": {"北方": "北方：指国家北部地区，与南方相对，这里指地区。", "早晨": "语义：“早晨”是一天中的时段，不能说“早晨的冬天”。", "星期一": "语义：“星期一”是时间词，不能用作表示地区的修饰语。", "北": "搭配：“北”单用时不作地区名词，要说“北方”或“北部”。"}, "sentence_index": 0, "correct_answer": "北方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上喝一杯北方。", "explanation": "这里应该用〈牛奶〉。北方指地区，不能喝。"}, {"text": "这个北方很好吃，我想再吃一个。", "explanation": "这里应该用〈饺子〉。北方指地区，不能指食物，要说具体的食物名称。"}, {"text": "他的北方坏了，不能写字了。", "explanation": "这里应该用〈笔〉。北方指地区，不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "北方", "is_correct": true, "explanation": "北方：指国家北部地区，这里指地区。"}, {"text": "中午", "is_correct": false, "explanation": "语义：“中午”是时间，不能说“中午的夏天”。"}, {"text": "北风", "is_correct": false, "explanation": "语义：“北风”指风，不能修饰“夏天”来表示地区。"}, {"text": "南", "is_correct": false, "explanation": "搭配：“南”单用时不作地区修饰语，要说“南方”。"}], "explanations": {"北方": "北方：指国家北部地区，这里指地区。", "中午": "语义：“中午”是时间，不能说“中午的夏天”。", "北风": "语义：“北风”指风，不能修饰“夏天”来表示地区。", "南": "搭配：“南”单用时不作地区修饰语，要说“南方”。"}, "sentence_index": 6, "correct_answer": "北方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把北方放在桌子上了。", "explanation": "这里应该用〈书〉。北方指一大片地区，不能放在桌子上。"}, {"text": "我们在一只很远的北方待了一年。", "explanation": "这里不能用〈只〉。只多用于动物等，北方是地区，要用〈个〉。"}, {"text": "妹妹穿着一条红色的北方。", "explanation": "这里应该用〈裙子〉。北方指地区，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我大学毕业以后北方工作。", "corrected_sentence": "我大学毕业以后去北方工作。", "error_description": "错误：“北方”作处所时，前面漏掉了动词“去”，直接说“北方工作”不通。正确形式是“去北方工作”，表示到那个地方做事。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们全家搬北方去了。", "corrected_sentence": "我们全家搬到北方去了。", "error_description": "错误：“北方”前漏掉了介词“到”。正确形式是“搬到北方去了”，表示移动到某个地方。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
