INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93267, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "女性生下孩子（具体的生产行为）。", "primary_collocate": null, "pronunciation": "shēng yù", "ipa": "ʂɤŋ˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "她三十岁时生育了第一个孩子。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人现在不想生育。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说她还能生育。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生育孩子需要很多钱。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生育以后就辞职在家带孩子。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生育前，她每周都去医院检查。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在这家医院生育了双胞胎。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈生育我的时候很辛苦。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女性生育后要好好休息。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想太早生育。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生育了", "label": "体标"}, {"form": "生育过", "label": "体标"}], "register": "中性", "sense_fingerprint": "女性生下孩子这一具体行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c571f81-6489-4741-8a61-f863fc462a95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93267, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确：生育（shēng yù），意思是女性生下孩子。"}, {"text": "生鱼", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是没有煮熟的鱼。"}, {"text": "生意", "is_correct": false, "explanation": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。"}, {"text": "剩余", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）、yú（第二声）与 yù（第四声）声调都不同，意思是剩下的部分。"}], "explanations": {"生育": "正确：生育（shēng yù），意思是女性生下孩子。", "生鱼": "yú（第二声）与 yù（第四声）声调不同，意思是没有煮熟的鱼。", "生意": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。", "剩余": "shèng（第四声）与 shēng（第一声）、yú（第二声）与 yù（第四声）声调都不同，意思是剩下的部分。"}, "sentence_index": null, "correct_answer": "生育"}, "level_3": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确。“她三十岁时生育了第一个孩子”说的是她生下第一个孩子。"}, {"text": "出生", "is_correct": false, "explanation": "配价：“出生”是人自己降生，不能带“孩子”作宾语。"}, {"text": "长大", "is_correct": false, "explanation": "配价：“长大”是不及物动词，后面不能带“第一个孩子”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吃东西，不能用来指生孩子。"}], "explanations": {"生育": "正确。“她三十岁时生育了第一个孩子”说的是她生下第一个孩子。", "出生": "配价：“出生”是人自己降生，不能带“孩子”作宾语。", "长大": "配价：“长大”是不及物动词，后面不能带“第一个孩子”。", "吃": "语义：“吃”指吃东西，不能用来指生孩子。"}, "sentence_index": 0, "correct_answer": "生育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂每天生育上千辆汽车。", "explanation": "这里应该用〈生产〉。“生育”只用于人或动物生孩子，工厂制造汽车要用“生产”。"}, {"text": "他是1990年在北京生育的。", "explanation": "这里应该用〈出生〉。“生育”要以子女为对象，表示人自己降生要用“出生”。"}, {"text": "这家公司生育了很多员工。", "explanation": "这里应该用〈招聘〉。“生育”的对象是子女，公司招收员工要用“招聘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93267, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确：生育（shēng yù），意思是女性生下孩子。"}, {"text": "省域", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是省的范围。"}, {"text": "盛誉", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是很高的声望。"}, {"text": "生意", "is_correct": false, "explanation": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。"}], "explanations": {"生育": "正确：生育（shēng yù），意思是女性生下孩子。", "省域": "shěng（第三声）与 shēng（第一声）声调不同，意思是省的范围。", "盛誉": "shèng（第四声）与 shēng（第一声）声调不同，意思是很高的声望。", "生意": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。"}, "sentence_index": null, "correct_answer": "生育"}, "level_3": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确。“她在这家医院生育了双胞胎”说的是她在医院生下双胞胎。"}, {"text": "挂号", "is_correct": false, "explanation": "语义：“挂号”是为看病登记，不能带“双胞胎”作宾语。"}, {"text": "住院", "is_correct": false, "explanation": "配价：“住院”是不及物动词，后面不能带宾语。"}, {"text": "出院", "is_correct": false, "explanation": "配价：“出院”是不及物动词，后面不能带宾语。"}], "explanations": {"生育": "正确。“她在这家医院生育了双胞胎”说的是她在医院生下双胞胎。", "挂号": "语义：“挂号”是为看病登记，不能带“双胞胎”作宾语。", "住院": "配价：“住院”是不及物动词，后面不能带宾语。", "出院": "配价：“出院”是不及物动词，后面不能带宾语。"}, "sentence_index": 6, "correct_answer": "生育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院生育了很多病人。", "explanation": "这里应该用〈收治〉。医院接收病人要用“收治”，“生育”的对象是子女，不能用于病人。"}, {"text": "研究所生育了新的药物。", "explanation": "这里应该用〈研发〉。新药的开发要用“研发”，“生育”只指生孩子、繁衍后代。"}, {"text": "农学家生育了新的水稻品种。", "explanation": "这里应该用〈培育〉。培育新品种要用“培育”，“生育”不用于植物品种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她二十八岁时没生育了第一个孩子。", "corrected_sentence": "她二十八岁时生育了第一个孩子。", "error_description": "否定词错误。“没”与“了”不能同用：“没生育了”不成立。这里说的是已经发生的事，应去掉“没”，说“生育了第一个孩子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在这家医院生育着一对双胞胎。", "corrected_sentence": "她在这家医院生育了一对双胞胎。", "error_description": "体标错误。“着”表示动作或状态在持续，而“生育一对双胞胎”是已经完成的一次性事件，应把“着”改成“了”，说“生育了一对双胞胎”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93268, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93268, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93268, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生孩子；繁衍后代。", "primary_collocate": null, "pronunciation": "shēng yù", "ipa": "ʂɤŋ˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "生育是人类繁衍后代的方式。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多年轻人推迟生育。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想帮助家庭解决生育的困难。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生育对一个家庭来说是大事。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家都在讨论生育问题。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生育带来的责任很重。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们决定先工作，再考虑生育。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司支持员工生育，还给了假期。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大熊猫很难生育。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老一辈人觉得生育越多越好。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生育了", "label": "体标"}, {"form": "生育过", "label": "体标"}], "register": "中性", "sense_fingerprint": "泛指生孩子、繁衍后代这一社会和生物现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c571f81-6489-4741-8a61-f863fc462a95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确：生育（shēng yù），意思是生孩子、繁衍后代。"}, {"text": "生鱼", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是没有煮熟的鱼。"}, {"text": "生意", "is_correct": false, "explanation": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。"}, {"text": "剩余", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）、yú（第二声）与 yù（第四声）声调都不同，意思是剩下的部分。"}], "explanations": {"生育": "正确：生育（shēng yù），意思是生孩子、繁衍后代。", "生鱼": "yú（第二声）与 yù（第四声）声调不同，意思是没有煮熟的鱼。", "生意": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。", "剩余": "shèng（第四声）与 shēng（第一声）、yú（第二声）与 yù（第四声）声调都不同，意思是剩下的部分。"}, "sentence_index": null, "correct_answer": "生育"}, "level_3": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确。“生育是人类繁衍后代的方式”中，“生育”作主语，指生孩子这一行为。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”与繁衍后代无关，句子意思不通。"}, {"text": "成长", "is_correct": false, "explanation": "语义：“成长”指长大，不是繁衍后代的方式。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“吃饭”不能作“繁衍后代的方式”的主语。"}], "explanations": {"生育": "正确。“生育是人类繁衍后代的方式”中，“生育”作主语，指生孩子这一行为。", "生病": "语义：“生病”与繁衍后代无关，句子意思不通。", "成长": "语义：“成长”指长大，不是繁衍后代的方式。", "吃饭": "搭配：“吃饭”不能作“繁衍后代的方式”的主语。"}, "sentence_index": 0, "correct_answer": "生育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农场每年生育大量鸡蛋。", "explanation": "这里应该用〈生产〉。“生育”指生孩子、繁衍后代，鸡蛋是产品，要用“生产”。"}, {"text": "这棵小树生育得很快。", "explanation": "这里应该用〈生长〉。树木长得快要用“生长”，“生育”只指人或动物繁衍后代。"}, {"text": "学校生育了很多人才。", "explanation": "这里应该用〈培养〉。培养人才要用“培养”，“生育”指生孩子、繁衍后代，不能用于人才。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93268, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确：生育（shēng yù），意思是生孩子、繁衍后代。"}, {"text": "省域", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是省的范围。"}, {"text": "盛誉", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是很高的声望。"}, {"text": "生意", "is_correct": false, "explanation": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。"}], "explanations": {"生育": "正确：生育（shēng yù），意思是生孩子、繁衍后代。", "省域": "shěng（第三声）与 shēng（第一声）声调不同，意思是省的范围。", "盛誉": "shèng（第四声）与 shēng（第一声）声调不同，意思是很高的声望。", "生意": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。"}, "sentence_index": null, "correct_answer": "生育"}, "level_3": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确。“再考虑生育”说的是考虑要不要生孩子。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是本能，不是可以“考虑”的行为。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽不是可以“考虑”的事情，句子不通。"}, {"text": "眨眼", "is_correct": false, "explanation": "搭配：“考虑”不能与“眨眼”这类本能动作搭配。"}], "explanations": {"生育": "正确。“再考虑生育”说的是考虑要不要生孩子。", "呼吸": "语义：呼吸是本能，不是可以“考虑”的行为。", "咳嗽": "语义：咳嗽不是可以“考虑”的事情，句子不通。", "眨眼": "搭配：“考虑”不能与“眨眼”这类本能动作搭配。"}, "sentence_index": 6, "correct_answer": "生育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器每天生育上百个零件。", "explanation": "这里应该用〈生产〉。机器制造零件要用“生产”，“生育”只指人或动物生孩子、繁衍后代。"}, {"text": "她生育在一个农村家庭。", "explanation": "这里应该用〈出生〉。表示人降生要用“出生”，“生育”指生孩子，不能用于本人出生。"}, {"text": "这个城市生育了许多名人。", "explanation": "这里应该用〈涌现〉。人才大量出现要用“涌现”，“生育”只能指生孩子，不能说“生育名人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "生育了是人类延续后代的重要方式。", "corrected_sentence": "生育是人类延续后代的重要方式。", "error_description": "“了”的位置错误。“生育”作主语时后面不能带“了”，应说“生育是……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社会应该支持女性很生育。", "corrected_sentence": "社会应该支持女性生育。", "error_description": "副词错误。“很”是程度副词，不能直接修饰动词“生育”，“很生育”不成立；应去掉“很”，说“支持女性生育”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
