INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93270, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "供口头呼喊的、有宣传鼓动作用的简短句子。", "primary_collocate": null, "pronunciation": "kǒu hào", "ipa": "kʰoʊ˨˩˦ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "街上贴着宣传口号，提醒大家注意安全。", "target_word": "口号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的口号是“让生活更简单”。", "target_word": "口号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校提出了一个新口号，鼓励大家爱读书。", "target_word": "口号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环保口号很多，但重要的是行动。", "target_word": "口号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条口号写在墙上，路过的人都能看到。", "target_word": "口号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用口号来宣传节约用水。", "target_word": "口号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个口号不只是说说，大家真的在做。", "target_word": "口号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路边的牌子上有一句口号：安全第一。", "target_word": "口号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告里的口号短短几个字，却让人记得很清楚。", "target_word": "口号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的口号是“好好学习，天天向上”。", "target_word": "口号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一句口号", "label": "量词"}, {"form": "一个口号", "label": "量词"}], "register": "中性", "sense_fingerprint": "用来宣传、鼓动人的简短句子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5cbcac1-4e17-487d-bba3-6efb4b2cfcde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93270, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "口号", "is_correct": true, "explanation": "正确答案：口号（kǒu hào），指供口头呼喊、用来宣传鼓动的简短句子。"}, {"text": "考号", "is_correct": false, "explanation": "kǎo hào 与 kǒu hào 韵母不同（ao / ou），意思是考试的编号，不是宣传语。"}, {"text": "口哨", "is_correct": false, "explanation": "kǒu shào 中 shào 与 hào 声母不同（sh / h），意思是用嘴吹的哨子。"}, {"text": "口罩", "is_correct": false, "explanation": "kǒu zhào 中 zhào 与 hào 声母不同（zh / h），意思是遮住口鼻的罩子。"}], "explanations": {"口号": "正确答案：口号（kǒu hào），指供口头呼喊、用来宣传鼓动的简短句子。", "考号": "kǎo hào 与 kǒu hào 韵母不同（ao / ou），意思是考试的编号，不是宣传语。", "口哨": "kǒu shào 中 shào 与 hào 声母不同（sh / h），意思是用嘴吹的哨子。", "口罩": "kǒu zhào 中 zhào 与 hào 声母不同（zh / h），意思是遮住口鼻的罩子。"}, "sentence_index": null, "correct_answer": "口号"}, "level_3": {"options": [{"text": "口号", "is_correct": true, "explanation": "正确：“宣传口号”指用来宣传的简短句子，贴在街上提醒大家，符合句意。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“贴”用于纸张等平面物，音乐不能“贴着”，应说“放”或“播”。"}, {"text": "米饭", "is_correct": false, "explanation": "语义：米饭不能贴在街上宣传，“贴着宣传米饭”说不通。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能贴在街上宣传，“贴着宣传玩具”的画面说不通。"}], "explanations": {"口号": "正确：“宣传口号”指用来宣传的简短句子，贴在街上提醒大家，符合句意。", "音乐": "搭配：“贴”用于纸张等平面物，音乐不能“贴着”，应说“放”或“播”。", "米饭": "语义：米饭不能贴在街上宣传，“贴着宣传米饭”说不通。", "玩具": "语义：玩具不能贴在街上宣传，“贴着宣传玩具”的画面说不通。"}, "sentence_index": 0, "correct_answer": "口号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的口号写得很动人，我常常哼。", "explanation": "这里应该用〈歌词〉。口号是为宣传鼓动而喊的简短句子，不用来指歌曲的唱词。"}, {"text": "这封信的口号写得很优美，我读了很感动。", "explanation": "这里应该用〈开头语〉。口号是为宣传鼓动而喊的简短语句，信件的开头不叫口号。"}, {"text": "这首诗里有一句很美的口号。", "explanation": "这里应该用〈诗句〉。口号是用来喊的宣传语，不用来指诗中的句子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口号", "is_correct": true, "explanation": "正确：“这个口号”指前面说的宣传语，“不只是说说，大家真的在做”符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被“做”，“大家真的在做天气”说不通。"}, {"text": "风景", "is_correct": false, "explanation": "搭配：“做风景”不成搭配，风景要说“看”或“欣赏”。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不能被“做”，这句话读起来不通。"}], "explanations": {"口号": "正确：“这个口号”指前面说的宣传语，“不只是说说，大家真的在做”符合句意。", "天气": "语义：天气不能被“做”，“大家真的在做天气”说不通。", "风景": "搭配：“做风景”不成搭配，风景要说“看”或“欣赏”。", "影子": "语义：影子不能被“做”，这句话读起来不通。"}, "sentence_index": 6, "correct_answer": "口号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校门口挂着一朵口号。", "explanation": "这里量词应该用〈句〉。“朵”用于花、云等，口号不用“朵”计数。"}, {"text": "老师在台上念了一双口号。", "explanation": "这里量词应该用〈句〉。“双”指成对的东西，口号不用“双”。"}, {"text": "墙上贴着一首口号，很醒目。", "explanation": "这里量词应该用〈句〉。“首”多用于诗歌、歌曲，口号不用“首”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们一起拿口号。", "corrected_sentence": "同学们一起喊口号。", "error_description": "错误形式：“拿口号”。正确形式：“喊口号”。“口号”要用动词“喊”来搭配，“拿”不能用于口头喊出的话。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们在台上念了一颗口号。", "corrected_sentence": "同学们在台上念了一句口号。", "error_description": "错误形式：“一颗口号”。正确形式：“一句口号”。“颗”用于小而圆的东西，口号按句计数，量词应用“句”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
