INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93273, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可靠是可以相信，不会出错。", "primary_collocate": null, "pronunciation": "kě kào", "ipa": "kʰɤ˨˩˦ kʰɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这个方法很简单，也很可靠。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车很旧，但是特别可靠。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数字不可靠，你再算一次。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这本书里的资料很可靠。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器几年都没坏，非常可靠。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手机地图找路，不太可靠。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药已经用了很多年，可靠又安全。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的记忆不可靠，常常记错日期。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的信息不都可靠，要多看几个地方。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个锁很可靠，小偷打不开。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可靠", "label": "复合"}, {"form": "可靠性", "label": "派生"}], "register": "中性", "sense_fingerprint": "形容事物、方法、资料等可以相信，不会出错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef5a13e9-5998-47ea-85ae-a1bc01b8e6de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93273, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可靠", "is_correct": true, "explanation": "可靠：可以相信，不会出错。"}, {"text": "科考", "is_correct": false, "explanation": "kē kǎo（第一、三声）与 kě kào 声调均不同，意思是科学考察。"}, {"text": "可看", "is_correct": false, "explanation": "kàn（第四声）与 kào（第四声）韵母不同（-an 与 -ao），声调相同，意思是值得看。"}, {"text": "可考", "is_correct": false, "explanation": "kǎo（第三声）与 kào（第四声）声调不同，意思是可以考证。"}], "explanations": {"可靠": "可靠：可以相信，不会出错。", "科考": "kē kǎo（第一、三声）与 kě kào 声调均不同，意思是科学考察。", "可看": "kàn（第四声）与 kào（第四声）韵母不同（-an 与 -ao），声调相同，意思是值得看。", "可考": "kǎo（第三声）与 kào（第四声）声调不同，意思是可以考证。"}, "sentence_index": null, "correct_answer": "可靠"}, "level_3": {"options": [{"text": "可靠", "is_correct": true, "explanation": "可靠：可以相信，不会出错，这里形容方法靠得住。"}, {"text": "复杂", "is_correct": false, "explanation": "语义：“复杂”与前面的“很简单”相反，句子自相矛盾。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的态度，不能用来形容方法。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”形容物体坚固，一般不用来形容方法。"}], "explanations": {"可靠": "可靠：可以相信，不会出错，这里形容方法靠得住。", "复杂": "语义：“复杂”与前面的“很简单”相反，句子自相矛盾。", "热情": "语义：“热情”形容人的态度，不能用来形容方法。", "结实": "搭配：“结实”形容物体坚固，一般不用来形容方法。"}, "sentence_index": 0, "correct_answer": "可靠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗面很可靠，吃完很饱。", "explanation": "这里应该用〈好吃〉。可靠指值得依靠、不出错，形容面的味道要说好吃。"}, {"text": "今天天气很可靠，我们去爬山吧。", "explanation": "这里应该用〈晴朗〉。可靠指人或事物值得依靠，形容天气要说晴朗。"}, {"text": "这朵花很可靠，开了整整一个月。", "explanation": "这里应该用〈漂亮〉。可靠用于事物能依靠、不出错，形容花的样子好看要说漂亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可靠", "is_correct": true, "explanation": "可靠：可以相信，不会出错，这里指药品长期使用没有问题。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来形容药。"}, {"text": "新鲜", "is_correct": false, "explanation": "语义：“新鲜”指刚出现或没有变质，与“用了很多年”矛盾。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能用来形容药的性质。"}], "explanations": {"可靠": "可靠：可以相信，不会出错，这里指药品长期使用没有问题。", "聪明": "语义：“聪明”形容人的智力，不能用来形容药。", "新鲜": "语义：“新鲜”指刚出现或没有变质，与“用了很多年”矛盾。", "明亮": "搭配：“明亮”形容光线或颜色，不能用来形容药的性质。"}, "sentence_index": 6, "correct_answer": "可靠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "街上很可靠，到处都是人。", "explanation": "这里应该用〈热闹〉。可靠指事物能依靠、不出错，形容街上人多、喧闹要说热闹。"}, {"text": "他的心情很可靠，今天一直很高兴。", "explanation": "这里应该用〈稳定〉。可靠指事物或人值得依靠，形容心情的变化要说稳定。"}, {"text": "这个笑话很可靠，大家都笑了。", "explanation": "这里应该用〈好笑〉。可靠指值得依靠，形容笑话让人发笑要说好笑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆车很的可靠，用了五年也没坏。", "corrected_sentence": "这辆车很可靠，用了五年也没坏。", "error_description": "错误：“很”和“可靠”之间多了“的”。程度副词“很”后面直接接形容词，不能再加“的”。正确形式是“很可靠”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个很可靠软件，很少出问题。", "corrected_sentence": "这是一个很可靠的软件，很少出问题。", "error_description": "错误：“可靠”修饰名词“软件”时后面要加“的”。正确形式是“很可靠的软件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
