INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93274, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "值得信赖；确实。", "primary_collocate": null, "pronunciation": "kě kào", "ipa": "kʰɤ˨˩˦ kʰɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "小王做事认真，是个可靠的人。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最可靠的朋友住在北京。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把孩子交给他，我很放心，他很可靠。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是按时来，大家都说他可靠。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一个可靠的人帮我看家。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息可靠吗？是谁告诉你的？", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据可靠消息，明天公司会放假。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话不可靠，别太相信他。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟年纪小，但是做事很可靠。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从可靠的人那里听到了这件事。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可靠", "label": "复合"}, {"form": "可靠性", "label": "派生"}], "register": "中性", "sense_fingerprint": "形容人值得信赖，或消息确实、真实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef5a13e9-5998-47ea-85ae-a1bc01b8e6de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93274, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可靠", "is_correct": true, "explanation": "可靠：值得信赖，做事让人放心。"}, {"text": "可看", "is_correct": false, "explanation": "kàn（第四声）与 kào（第四声）韵母不同（-an 与 -ao），声调相同，意思是值得看。"}, {"text": "可考", "is_correct": false, "explanation": "kǎo（第三声）与 kào（第四声）声调不同，意思是可以考证。"}, {"text": "可笑", "is_correct": false, "explanation": "kě xiào 与 kě kào 只差第二个字的声母（x 与 k），声调相同，意思是让人发笑。"}, {"text": "可口", "is_correct": false, "explanation": "kě kǒu 与 kě kào 声母相同，韵母和声调不同（ǒu 与 ào），意思是味道好。"}], "explanations": {"可靠": "可靠：值得信赖，做事让人放心。", "可看": "kàn（第四声）与 kào（第四声）韵母不同（-an 与 -ao），声调相同，意思是值得看。", "可考": "kǎo（第三声）与 kào（第四声）声调不同，意思是可以考证。", "可笑": "kě xiào 与 kě kào 只差第二个字的声母（x 与 k），声调相同，意思是让人发笑。", "可口": "kě kǒu 与 kě kào 声母相同，韵母和声调不同（ǒu 与 ào），意思是味道好。"}, "sentence_index": null, "correct_answer": "可靠"}, "level_3": {"options": [{"text": "可靠", "is_correct": true, "explanation": "可靠：值得信赖，做事让人放心，这里形容人的品行。"}, {"text": "马虎", "is_correct": false, "explanation": "语义：“马虎”指做事不认真，与“做事认真”矛盾。"}, {"text": "懒", "is_correct": false, "explanation": "语义：“懒”指不愿做事，与“做事认真”矛盾。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：“窄”形容空间或宽度，不能用来形容人的品性。"}], "explanations": {"可靠": "可靠：值得信赖，做事让人放心，这里形容人的品行。", "马虎": "语义：“马虎”指做事不认真，与“做事认真”矛盾。", "懒": "语义：“懒”指不愿做事，与“做事认真”矛盾。", "窄": "搭配：“窄”形容空间或宽度，不能用来形容人的品性。"}, "sentence_index": 0, "correct_answer": "可靠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身体很可靠，每天跑步十公里。", "explanation": "这里应该用〈结实〉。可靠用于人的品行或消息的真实，形容身体强壮要说结实。"}, {"text": "他的房间很可靠，收拾得很整洁。", "explanation": "这里应该用〈整洁〉。可靠不用来形容房间的样子，房间干净利落要说整洁。"}, {"text": "他今天精神很可靠。", "explanation": "这里应该用〈好〉。可靠指人值得信赖，不用来描述精神状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可靠", "is_correct": true, "explanation": "可靠：确实、真实，这里形容消息值得相信。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容环境没有声音，不能修饰“消息”。"}, {"text": "香", "is_correct": false, "explanation": "语义：“香”形容气味或味道，不能用来修饰“消息”。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”形容速度，不能用来说消息的真假。"}], "explanations": {"可靠": "可靠：确实、真实，这里形容消息值得相信。", "安静": "语义：“安静”形容环境没有声音，不能修饰“消息”。", "香": "语义：“香”形容气味或味道，不能用来修饰“消息”。", "慢": "语义：“慢”形容速度，不能用来说消息的真假。"}, "sentence_index": 6, "correct_answer": "可靠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌很可靠，我每天都听。", "explanation": "这里应该用〈好听〉。可靠形容人值得信赖或消息确实，不用来形容歌好听。"}, {"text": "他跑得很可靠，一下子就到了。", "explanation": "这里应该用〈快〉。可靠不用来形容跑步的速度，跑得快要说快。"}, {"text": "这块蛋糕很可靠，大家都吃光了。", "explanation": "这里应该用〈甜〉。可靠不用来形容味道，蛋糕味道甜要说甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他总是可靠的完成任务。", "corrected_sentence": "他总是可靠地完成任务。", "error_description": "错误：“可靠”修饰动词“完成”时要用“地”，不能用“的”。正确形式是“可靠地完成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个很可靠老师。", "corrected_sentence": "他是一个很可靠的老师。", "error_description": "错误：“可靠”修饰名词“老师”时后面要加“的”。正确形式是“很可靠的老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93276, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "释放", "is_correct": true, "explanation": "反义：“释放”指把被关押的人放出来，与“监禁”意思相反。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”指使损坏的东西恢复正常，与“监禁”没有反义关系。"}, {"text": "种植", "is_correct": false, "explanation": "无关：“种植”指栽培植物，与“监禁”没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：“搬运”指把物品从一处移到另一处，与“监禁”没有反义关系。"}], "correct_answer": "释放", "explanations": {"释放": "反义：“释放”指把被关押的人放出来，与“监禁”意思相反。", "修理": "无关：“修理”指使损坏的东西恢复正常，与“监禁”没有反义关系。", "种植": "无关：“种植”指栽培植物，与“监禁”没有反义关系。", "搬运": "无关：“搬运”指把物品从一处移到另一处，与“监禁”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93276, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "释放", "is_correct": true, "explanation": "反义：“释放”与“监禁”意思相反，指把被关押的人放出来。"}, {"text": "清洗", "is_correct": false, "explanation": "无关：“清洗”指把脏东西弄干净，与“监禁”没有反义关系。"}, {"text": "煮", "is_correct": false, "explanation": "无关：“煮”指用水加热做熟食物，与“监禁”没有反义关系。"}, {"text": "翻译", "is_correct": false, "explanation": "无关：“翻译”指转换语言，与“监禁”没有反义关系。"}], "correct_answer": "释放", "explanations": {"释放": "反义：“释放”与“监禁”意思相反，指把被关押的人放出来。", "清洗": "无关：“清洗”指把脏东西弄干净，与“监禁”没有反义关系。", "煮": "无关：“煮”指用水加热做熟食物，与“监禁”没有反义关系。", "翻译": "无关：“翻译”指转换语言，与“监禁”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93276, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把犯罪者关押在监狱，限制其自由。", "primary_collocate": null, "pronunciation": "jiān jìn", "ipa": "tɕjɛn⁵⁵ tɕin⁵¹", "syllable_count": 2, "sentences": [{"text": "法院决定监禁他五年。", "target_word": "监禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律可以监禁犯罪的人，让他们失去自由。", "target_word": "监禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院监禁罪犯，是为了保护社会。", "target_word": "监禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犯了大罪，法院监禁了他二十年。", "target_word": "监禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院依法监禁了这个骗子半年。", "target_word": "监禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家有权监禁犯了罪的人。", "target_word": "监禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家很少监禁年轻人。", "target_word": "监禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官没有监禁他，只让他交了钱。", "target_word": "监禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院曾经监禁过他两次。", "target_word": "监禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这名组织者被判监禁十五年。", "target_word": "监禁", "complexity_tier": "T3", "furigana": "jiān jìn", "sentence_source": "generated"}], "morphological_forms": [{"form": "监禁了", "label": "体标"}, {"form": "监禁过", "label": "体标"}, {"form": "监禁着", "label": "体标"}, {"form": "監禁", "label": "繁体"}], "register": "书面", "sense_fingerprint": "监禁：依法把罪犯关进监狱、限制自由", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ef20229-854f-45a8-be5e-aab94d82e2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "监禁", "is_correct": true, "explanation": "正确：“监禁”指依法关押罪犯，与“五年”搭配，符合判决语境。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是给人好处，法院不会因此“奖励他五年”。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞好的表现，不能说“表扬他五年”，也不符合判罪语境。"}, {"text": "聘请", "is_correct": false, "explanation": "语义：“聘请”是请人工作，与法院对罪犯的判决语境不符。"}], "explanations": {"监禁": "正确：“监禁”指依法关押罪犯，与“五年”搭配，符合判决语境。", "奖励": "语义：“奖励”是给人好处，法院不会因此“奖励他五年”。", "表扬": "语义：“表扬”是称赞好的表现，不能说“表扬他五年”，也不符合判罪语境。", "聘请": "语义：“聘请”是请人工作，与法院对罪犯的判决语境不符。"}, "sentence_index": 0, "correct_answer": "监禁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法院监禁了他所有的财产。", "explanation": "这里应该用〈没收〉。“没收”指收走财产；“监禁”指关押人，不能用于财产。"}, {"text": "法院监禁了他一万块钱。", "explanation": "这里应该用〈罚〉。罚款的对象是金钱；“监禁”指关押，不能用于金钱。"}, {"text": "法律监禁酒后开车。", "explanation": "这里应该用〈禁止〉。“禁止”表示不许做某事；“监禁”指关押人，不能表示不许做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "监禁", "is_correct": true, "explanation": "正确：“很少监禁年轻人”说明较少关押年轻人，符合语境。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：“修剪”指剪去多余的枝叶或头发，不能用于描述对年轻人的处理。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”的对象是语言文字，不能用于年轻人。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”多用于婴幼儿或动物，不说喂养年轻人。"}], "explanations": {"监禁": "正确：“很少监禁年轻人”说明较少关押年轻人，符合语境。", "修剪": "语义：“修剪”指剪去多余的枝叶或头发，不能用于描述对年轻人的处理。", "翻译": "语义：“翻译”的对象是语言文字，不能用于年轻人。", "喂养": "搭配：“喂养”多用于婴幼儿或动物，不说喂养年轻人。"}, "sentence_index": 6, "correct_answer": "监禁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天监禁生病的孩子。", "explanation": "这里应该用〈照顾〉。照顾孩子是关心和看护；“监禁”是强制关押，不能用于孩子。"}, {"text": "摄影师监禁了美丽的风景。", "explanation": "这里应该用〈拍摄〉。“拍摄”指用镜头记录；“监禁”是关押人，不能用于风景。"}, {"text": "医生监禁了病人的心跳。", "explanation": "这里应该用〈监测〉。“监测”指观察并记录数据，如心跳；“监禁”是把人关起来，不能用于心跳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院把这个小偷监禁下来了。", "corrected_sentence": "法院把这个小偷监禁起来了。", "error_description": "补语错误：表示把人关进去的动作要用“起来”，不能用“下来”，应说“监禁起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法院从来没有监禁了年轻人。", "corrected_sentence": "法院从来没有监禁过年轻人。", "error_description": "体标错误：“从来没有”后用“过”表示未曾发生，不能用“了”，应说“没有监禁过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
