INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93279, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "目标市场是公司想把东西卖给的那一群人。", "primary_collocate": null, "pronunciation": "mù biāo shì chǎng", "ipa": "mu˥˩ pjɑʊ˥ ʂɻ̩˥˩ ʈʂʰɑŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "这家公司的目标市场是年轻人。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的目标市场是喜欢运动的人。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卖东西以前，要先弄清楚目标市场是哪些人。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手机的目标市场在城市里。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们先找到目标市场，再做广告。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的目标市场不是小孩，而是老人。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想进入一个新的目标市场。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做面包以前，要先想好目标市场。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子把学生当作目标市场。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的目标市场很小，只有几千人。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个目标市场", "label": "量词搭配"}, {"form": "目標市場", "label": "繁体"}], "register": "书面", "sense_fingerprint": "公司想把商品卖给的那一群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e91c0d-146f-4be2-97f8-2129581fbe82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93279, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "利润", "is_correct": false, "explanation": "语义：利润是企业的收益数额，不是一群人，不能说“是年轻人”。"}, {"text": "目标市场", "is_correct": true, "explanation": "正确：指公司想卖给的那一群顾客，此处是年轻人。"}, {"text": "成本", "is_correct": false, "explanation": "搭配：“成本”指花费的钱，常与“高”“低”搭配，不能与“是年轻人”组成描述。"}, {"text": "股价", "is_correct": false, "explanation": "语义：股价是股票的价格，不指消费的人群。"}], "explanations": {"利润": "语义：利润是企业的收益数额，不是一群人，不能说“是年轻人”。", "目标市场": "正确：指公司想卖给的那一群顾客，此处是年轻人。", "成本": "搭配：“成本”指花费的钱，常与“高”“低”搭配，不能与“是年轻人”组成描述。", "股价": "语义：股价是股票的价格，不指消费的人群。"}, "sentence_index": 0, "correct_answer": "目标市场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的目标市场扩大到了百分之三十。", "explanation": "这里应该用〈市场份额〉。市场份额才用百分比衡量，目标市场指一群顾客，不能用百分比扩大。"}, {"text": "我们正在研发目标市场。", "explanation": "这里应该用〈产品〉。研发的对象是产品或技术，目标市场要说“开拓”或“选定”。"}, {"text": "我们在电视上做目标市场。", "explanation": "这里应该用〈广告〉。做的是广告，目标市场不是可以“做”出来的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93279, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竞争对手", "is_correct": false, "explanation": "语义：竞争对手指对手企业或个人，“进入”的对象应是市场或领域。"}, {"text": "销量", "is_correct": false, "explanation": "搭配：“进入”后面接市场、领域，不接“销量”。"}, {"text": "目标市场", "is_correct": true, "explanation": "正确：“进入”的对象是市场，此处指公司想争取的新顾客群。"}, {"text": "股东", "is_correct": false, "explanation": "语义：股东指持有股份的人，不是可以“进入”的市场或领域。"}], "explanations": {"竞争对手": "语义：竞争对手指对手企业或个人，“进入”的对象应是市场或领域。", "销量": "搭配：“进入”后面接市场、领域，不接“销量”。", "目标市场": "正确：“进入”的对象是市场，此处指公司想争取的新顾客群。", "股东": "语义：股东指持有股份的人，不是可以“进入”的市场或领域。"}, "sentence_index": 6, "correct_answer": "目标市场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们写了一个目标市场。", "explanation": "这里应该用〈文章〉。写的对象是文章、信件，目标市场不能被写。"}, {"text": "这家店开设了一个目标市场。", "explanation": "这里应该用〈分店〉。开设的是店铺、课程，目标市场要说“开拓”。"}, {"text": "我们发出了这次的目标市场。", "explanation": "这里应该用〈问卷〉。发出的是问卷、传单，目标市场不能被“发出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司找到了三只目标市场。", "corrected_sentence": "这家公司找到了三个目标市场。", "error_description": "量词错误：“目标市场”的量词应用“个”，不用“只”（“只”用于动物和小件物品）。应改为“三个目标市场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "广告要投放目标市场上。", "corrected_sentence": "广告要投放在目标市场上。", "error_description": "介词缺失：“投放”后表示地点要用“在……上”，漏掉了“在”。应为“投放在目标市场上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
