INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93280, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "企业选定作为营销对象的特定顾客群体或市场。", "primary_collocate": null, "pronunciation": "mù biāo shì chǎng", "ipa": "mu˥˩ pjɑʊ˥ ʂɻ̩˥˩ ʈʂʰɑŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "企业需要根据产品特点选定目标市场。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家企业把中老年人选为目标市场。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目标市场不同，广告的做法也不同。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的目标市场是高收入的城市家庭。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司通过调查确定了目标市场的需求。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小企业最好先集中力量做好一个目标市场。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款产品的目标市场包括大学生和上班族。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选错目标市场，会让企业白白花钱。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在研究目标市场的消费习惯。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目标市场的变化让企业调整了价格。", "target_word": "目标市场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个目标市场", "label": "量词搭配"}, {"form": "目標市場", "label": "繁体"}], "register": "书面", "sense_fingerprint": "企业经过选择确定的营销对象与顾客群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e91c0d-146f-4be2-97f8-2129581fbe82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "利润", "is_correct": false, "explanation": "语义：利润是收益，不是可以“选定”的对象。"}, {"text": "成本", "is_correct": false, "explanation": "搭配：“选定”的对象是方案、地点、市场等，“成本”不能被选定。"}, {"text": "目标市场", "is_correct": true, "explanation": "正确：指企业选定的营销对象，即要营销的顾客群体。"}, {"text": "股价", "is_correct": false, "explanation": "语义：股价是价格数字，不能根据产品特点选定。"}], "explanations": {"利润": "语义：利润是收益，不是可以“选定”的对象。", "成本": "搭配：“选定”的对象是方案、地点、市场等，“成本”不能被选定。", "目标市场": "正确：指企业选定的营销对象，即要营销的顾客群体。", "股价": "语义：股价是价格数字，不能根据产品特点选定。"}, "sentence_index": 0, "correct_answer": "目标市场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店今天收到了三十个目标市场。", "explanation": "这里应该用〈订单〉。收到的是订单，目标市场不能被“收到”。"}, {"text": "这家公司申请了一个目标市场。", "explanation": "这里应该用〈专利〉。申请的是专利，目标市场不能被申请。"}, {"text": "这款产品的目标市场是一百块钱。", "explanation": "这里应该用〈价格〉。价格是金额，目标市场指顾客群体，不能用钱数表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竞争对手", "is_correct": false, "explanation": "语义：竞争对手指对手，不是大学生和上班族这样的群体。"}, {"text": "销售额", "is_correct": false, "explanation": "搭配：“包括”后接人群时，中心语应是群体，“销售额”不能包括人。"}, {"text": "目标市场", "is_correct": true, "explanation": "正确：“包括”后列出的是顾客群体，即大学生和上班族。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是数额，不是人群，不能包括大学生和上班族。"}], "explanations": {"竞争对手": "语义：竞争对手指对手，不是大学生和上班族这样的群体。", "销售额": "搭配：“包括”后接人群时，中心语应是群体，“销售额”不能包括人。", "目标市场": "正确：“包括”后列出的是顾客群体，即大学生和上班族。", "价格": "语义：价格是数额，不是人群，不能包括大学生和上班族。"}, "sentence_index": 6, "correct_answer": "目标市场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他报名了这个目标市场。", "explanation": "这里应该用〈课程〉。报名的是课程、比赛，目标市场不能报名。"}, {"text": "妈妈把这个目标市场煮熟了。", "explanation": "这里应该用〈米饭〉。煮的是米饭、饺子等食物，目标市场不能被煮。"}, {"text": "他把这个目标市场送进了博物馆。", "explanation": "这里应该用〈文物〉。送进博物馆的是文物，目标市场指顾客群体，不能被送进博物馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "企业想把产品卖给两只目标市场。", "corrected_sentence": "企业想把产品卖给两个目标市场。", "error_description": "量词错误：“目标市场”的量词应用“个”，不用“只”。应改为“两个目标市场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "产品要推目标市场。", "corrected_sentence": "产品要推向目标市场。", "error_description": "介词缺失：“推”后接市场，要用“推向”，漏掉了“向”。应为“推向目标市场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
