INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93282, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "property", "definition": "各种类别。", "primary_collocate": null, "pronunciation": "gè lèi", "ipa": "kɤ˥˩ leɪ˥˩", "syllable_count": 2, "sentences": [{"text": "图书馆里有各类书。", "target_word": "各类", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "商店里卖各类水果。", "target_word": "各类", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次会议请来了各类专家。", "target_word": "各类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里各类食品都很便宜。", "target_word": "各类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校有各类社团，你可以参加。", "target_word": "各类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢看各类电影，也喜欢听音乐。", "target_word": "各类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的各类蛋糕都很新鲜。", "target_word": "各类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院为老人提供各类帮助。", "target_word": "各类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书店里的各类杂志整齐地放着。", "target_word": "各类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛有各类奖项，每个人都有机会。", "target_word": "各类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "各类：各种类别，放在名词前，指所有不同的种类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4de93c19-9eac-449b-96e7-31ed056a2812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各类", "is_correct": true, "explanation": "正确。句中说“图书馆里有……书”，需要表示多种类别的“各类”。"}, {"text": "唯一", "is_correct": false, "explanation": "语义：“唯一”表示只有一个，与“各类”指多种类别相反。"}, {"text": "独特", "is_correct": false, "explanation": "搭配：“独特”形容事物的特色，不用来修饰书的种类。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列的样子，不用来说书的种类。"}], "explanations": {"各类": "正确。句中说“图书馆里有……书”，需要表示多种类别的“各类”。", "唯一": "语义：“唯一”表示只有一个，与“各类”指多种类别相反。", "独特": "搭配：“独特”形容事物的特色，不用来修饰书的种类。", "整齐": "搭配：“整齐”形容排列的样子，不用来说书的种类。"}, "sentence_index": 0, "correct_answer": "各类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一个各类的蛋糕。", "explanation": "这里应该用〈一种〉。“各类”指多种不同的类别，只买一样东西要用“一种”。"}, {"text": "他一个月只看一个各类的电影。", "explanation": "这里应该用〈一部〉。“各类”指多种不同的类别，只看一部电影要用“一部”。"}, {"text": "我们班只有一名各类的同学。", "explanation": "这里应该用〈一个〉。“各类”指多种不同的类别，只说一个人时不能用“各类”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各类", "is_correct": true, "explanation": "正确。句中说“这家店的……蛋糕”，需要表示多种类别的“各类”。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”指只有一种，与“各类”指多种类别相反。"}, {"text": "单调", "is_correct": false, "explanation": "搭配：“单调”形容款式或生活，不用来形容蛋糕的种类。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容场所，不用来修饰蛋糕。"}], "explanations": {"各类": "正确。句中说“这家店的……蛋糕”，需要表示多种类别的“各类”。", "单一": "语义：“单一”指只有一种，与“各类”指多种类别相反。", "单调": "搭配：“单调”形容款式或生活，不用来形容蛋糕的种类。", "冷清": "搭配：“冷清”形容场所，不用来修饰蛋糕。"}, "sentence_index": 6, "correct_answer": "各类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的各类奖项都一样，每个人都有机会。", "explanation": "这里应该用〈不同〉。“各类”强调种类不同，说奖项“都一样”与之矛盾。"}, {"text": "这次比赛只有一名各类的选手，每个人都很紧张。", "explanation": "这里应该用〈一位〉。“各类”指多种不同的类别，只说一个选手时不能用“各类”。"}, {"text": "这次比赛的各类奖项，我们都拿到了同一个。", "explanation": "这里应该用〈不同的〉。“各类”指不同种类，说都拿到“同一个”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "超市的货架上摆着商品各类。", "corrected_sentence": "超市的货架上摆着各类商品。", "error_description": "错误形式：「商品各类」；正确形式：「各类商品」。「各类」要放在名词前面修饰名词，不能放在名词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的图书馆有各类个小说。", "corrected_sentence": "学校的图书馆有各类小说。", "error_description": "错误形式：「各类个小说」；正确形式：「各类小说」。「各类」后面直接接名词，中间不能加「个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
