INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93284, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "目不转睛地注视。", "primary_collocate": null, "pronunciation": "dīng", "ipa": "tiŋ˥", "syllable_count": 1, "sentences": [{"text": "妈妈盯着孩子写作业。", "target_word": "盯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察一直盯着那个人。", "target_word": "盯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，大家都盯着球。", "target_word": "盯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他两眼盯着对手，一点儿也不放松。", "target_word": "盯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我盯着屏幕，怕错过消息。", "target_word": "盯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "守门员盯着球，准备接住。", "target_word": "盯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士盯着机器上的数字。", "target_word": "盯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他盯了那个女孩好一会儿。", "target_word": "盯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫盯着老鼠洞，等老鼠出来。", "target_word": "盯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她盯着门口，等朋友来。", "target_word": "盯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "盯着", "label": "体标"}, {"form": "盯了", "label": "体标"}, {"form": "盯过", "label": "体标"}], "register": "中性", "sense_fingerprint": "目不转睛地注视、紧紧看住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3e1b82-d785-4be0-9594-3915e54d0855') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93284, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盯", "is_correct": true, "explanation": "盯（dīng）：目不转睛地注视。"}, {"text": "订", "is_correct": false, "explanation": "订（dìng）与 dīng 声调不同（第四声），意思是预订。"}, {"text": "兵", "is_correct": false, "explanation": "兵（bīng）与 dīng 声母不同（b/d），意思是士兵。"}, {"text": "厅", "is_correct": false, "explanation": "厅（tīng）与 dīng 声母不同（t/d），意思是大厅。"}, {"text": "顶", "is_correct": false, "explanation": "顶（dǐng）与 dīng 声调不同（第三声），意思是顶住、顶替。"}], "explanations": {"盯": "盯（dīng）：目不转睛地注视。", "订": "订（dìng）与 dīng 声调不同（第四声），意思是预订。", "兵": "兵（bīng）与 dīng 声母不同（b/d），意思是士兵。", "厅": "厅（tīng）与 dīng 声母不同（t/d），意思是大厅。", "顶": "顶（dǐng）与 dīng 声调不同（第三声），意思是顶住、顶替。"}, "sentence_index": null, "correct_answer": "盯"}, "level_3": {"options": [{"text": "盯", "is_correct": true, "explanation": "盯：妈妈目不转睛地看着孩子写作业。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗的对象不是孩子写作业，此处说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不与“写作业”搭配。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦的动作与“写作业”无关，句意不通。"}], "explanations": {"盯": "盯：妈妈目不转睛地看着孩子写作业。", "洗": "语义：洗的对象不是孩子写作业，此处说不通。", "吃": "搭配：“吃”不与“写作业”搭配。", "擦": "语义：擦的动作与“写作业”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "盯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他两眼盯着对手的叫声，一点儿也不放松。", "explanation": "这里应该用〈听〉。“盯”只能用于看得见的目标，叫声只能听。"}, {"text": "他随便盯了对手一眼，就转过头去。", "explanation": "这里应该用〈瞥〉。“盯”表示目不转睛地注视，“随便一眼”是随意地看，应用“瞥”。"}, {"text": "他盯着屋里飘来的香味，一动不动。", "explanation": "这里应该用〈闻〉。“盯”只能用于看得见的目标，香味只能闻，不能盯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93284, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "盯", "is_correct": true, "explanation": "盯（dīng）：目不转睛地注视。"}, {"text": "冰", "is_correct": false, "explanation": "冰（bīng）与 dīng 声母不同（b/d），意思是冰块。"}, {"text": "定", "is_correct": false, "explanation": "定（dìng）与 dīng 声调不同（第四声），意思是决定。"}, {"text": "听", "is_correct": false, "explanation": "听（tīng）与 dīng 声母不同（t/d），意思是用耳朵接收声音。"}, {"text": "顶", "is_correct": false, "explanation": "顶（dǐng）与 dīng 声调不同（第三声），意思是头顶、顶住。"}], "explanations": {"盯": "盯（dīng）：目不转睛地注视。", "冰": "冰（bīng）与 dīng 声母不同（b/d），意思是冰块。", "定": "定（dìng）与 dīng 声调不同（第四声），意思是决定。", "听": "听（tīng）与 dīng 声母不同（t/d），意思是用耳朵接收声音。", "顶": "顶（dǐng）与 dīng 声调不同（第三声），意思是头顶、顶住。"}, "sentence_index": null, "correct_answer": "盯"}, "level_3": {"options": [{"text": "盯", "is_correct": true, "explanation": "盯：护士目不转睛地看着机器上的数字。"}, {"text": "抱", "is_correct": false, "explanation": "语义：数字是显示在机器上的符号，抱不住，句意不通。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”不与“数字”搭配。"}, {"text": "砸", "is_correct": false, "explanation": "语义：砸机器上的数字说不通，与“看”也矛盾。"}], "explanations": {"盯": "盯：护士目不转睛地看着机器上的数字。", "抱": "语义：数字是显示在机器上的符号，抱不住，句意不通。", "踢": "搭配：“踢”不与“数字”搭配。", "砸": "语义：砸机器上的数字说不通，与“看”也矛盾。"}, "sentence_index": 6, "correct_answer": "盯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她盯着门口的味道，等朋友来。", "explanation": "这里应该用〈闻〉。“盯”要看得见的目标，味道看不见，只能闻。"}, {"text": "她盯着门口，一会儿望窗外，一会儿看天花板，等朋友来。", "explanation": "这里的“盯”要求目光固定不动，与“一会儿望窗外，一会儿看天花板”的目光移动矛盾。"}, {"text": "她盯着门口的时间，等朋友来。", "explanation": "“盯”的对象必须是看得见的具体事物，时间看不见，不能盯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他了盯我一会儿。", "corrected_sentence": "他盯了我一会儿。", "error_description": "体标错误：“了”应放在动词后，应为“盯了”，不能放在动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他盯着窗外的雨，一直没说话着。", "corrected_sentence": "他盯着窗外的雨，一直没说话。", "error_description": "体标错误：句末多出“着”。“着”表示动作的持续，不能接在否定的“没说话”之后，应删去句末的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
