INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93286, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "真实诚恳，没有虚假。", "primary_collocate": null, "pronunciation": "zhēn chéng", "ipa": "ʈʂən˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他真诚地向大家道歉。", "target_word": "真诚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的笑容很真诚，没有一点假。", "target_word": "真诚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你真诚的帮助。", "target_word": "真诚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对客人非常真诚。", "target_word": "真诚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该真诚地对待每一个人。", "target_word": "真诚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用真诚的话打动了大家。", "target_word": "真诚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼神很真诚。", "target_word": "真诚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份礼物表达了我真诚的心意。", "target_word": "真诚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我真诚地希望你能快乐。", "target_word": "真诚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对老人要有真诚的关心。", "target_word": "真诚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "真诚地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "态度真实诚恳，没有虚假", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3e1b82-d785-4be0-9594-3915e54d0855') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93286, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”形容颜色，不能用来修饰道歉这一动作"}, {"text": "欢快", "is_correct": false, "explanation": "语义：“欢快”表示高兴，与道歉时的歉意相矛盾"}, {"text": "真诚", "is_correct": true, "explanation": "真诚：出于真心地道歉，与句意相符"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能用来修饰道歉这一动作"}], "explanations": {"雪白": "搭配：“雪白”形容颜色，不能用来修饰道歉这一动作", "欢快": "语义：“欢快”表示高兴，与道歉时的歉意相矛盾", "真诚": "真诚：出于真心地道歉，与句意相符", "高大": "体貌：“高大”形容身材，不能用来修饰道歉这一动作"}, "sentence_index": 0, "correct_answer": "真诚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份资料记录的是真诚的情况。", "explanation": "这里应该用〈真实〉。真实指符合事实，记录的情况要用真实；真诚只形容人的为人和态度"}, {"text": "这套家具的质量很真诚。", "explanation": "这里应该用〈实在〉。实在形容东西质量好、实用，真诚不能用来形容东西"}, {"text": "他解题时非常真诚。", "explanation": "这里应该用〈认真〉。认真形容做事专心，解题要用认真；真诚形容人的为人和态度"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，与眼神无关"}, {"text": "光滑", "is_correct": false, "explanation": "搭配：“光滑”形容物体表面，不能用来形容眼神"}, {"text": "真诚", "is_correct": true, "explanation": "真诚：眼神里透出真心，与“很”搭配自然"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音，眼神没有声音，不能用它来形容"}], "explanations": {"咸": "语义：“咸”指味道，与眼神无关", "光滑": "搭配：“光滑”形容物体表面，不能用来形容眼神", "真诚": "真诚：眼神里透出真心，与“很”搭配自然", "响亮": "语义：“响亮”形容声音，眼神没有声音，不能用它来形容"}, "sentence_index": 6, "correct_answer": "真诚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头很真诚。", "explanation": "这里把〈真诚〉误用成了“坚硬、结实”的意思。真诚只指人说真话、没有虚假，不能用来形容石头的质地。"}, {"text": "窗户真诚地关上了。", "explanation": "这里把〈真诚〉误用成了“轻轻、慢慢”的意思。真诚指人对待他人的态度，不能修饰窗户的动作。"}, {"text": "那片云很真诚。", "explanation": "这里把〈真诚〉误用成了“洁白、漂亮”的意思。真诚只用于人，不能形容云的颜色和样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板真诚的向员工表示感谢。", "corrected_sentence": "老板真诚地向员工表示感谢。", "error_description": "“真诚”修饰动词“表示”时应用“地”，不能用“的”。正确说法：老板真诚地向员工表示感谢。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都希望他能真诚的道歉。", "corrected_sentence": "我们都希望他能真诚地道歉。", "error_description": "“真诚”修饰动词“道歉”时应用“地”，不能用“的”；“真诚的道歉”是名词短语，不能直接放在“能”后面作动词的状语。正确说法：我们都希望他能真诚地道歉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
