INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一定的格式或规程。", "primary_collocate": null, "pronunciation": "chéng shì", "ipa": "tʂʰɤŋ˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "办这件事要按照一定的程式。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种文章有固定的程式，写起来不难。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，写信有一定的程式。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事都有固定的程式，一点也不乱。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼的程式很复杂，大家要听司仪的。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "京剧的动作有固定的程式，演员要多年练习。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在学习公文的程式。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲话总是那一套程式，没有新意。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前有一套固定的程式，每个人都要做。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种公文有固定的程式，不能随便改。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套程式", "label": "量词：套"}, {"form": "程式化", "label": "复合词"}], "register": "中性", "sense_fingerprint": "固定的格式、规程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6f10e89-3216-45ca-a1f0-6c5d9749bac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93290, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "程式", "is_correct": true, "explanation": "正确答案。程式指一定的格式或规程。"}, {"text": "诚实", "is_correct": false, "explanation": "诚实 chéngshí 与 chéngshì 只有第二个音节声调不同，意思是真实、不说谎。"}, {"text": "诚挚", "is_correct": false, "explanation": "诚挚 chéngzhì 与 chéngshì 声母不同（zh 与 sh），意思是真诚恳切。"}, {"text": "尘世", "is_correct": false, "explanation": "尘世 chénshì 与 chéngshì 韵母不同（n 与 ng），意思是人间、世间。"}], "explanations": {"程式": "正确答案。程式指一定的格式或规程。", "诚实": "诚实 chéngshí 与 chéngshì 只有第二个音节声调不同，意思是真实、不说谎。", "诚挚": "诚挚 chéngzhì 与 chéngshì 声母不同（zh 与 sh），意思是真诚恳切。", "尘世": "尘世 chénshì 与 chéngshì 韵母不同（n 与 ng），意思是人间、世间。"}, "sentence_index": null, "correct_answer": "程式"}, "level_3": {"options": [{"text": "程式", "is_correct": true, "explanation": "正确。“按照一定的程式”指固定的规程，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：办事要按规程，颜色与办事的方式无关。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味是气味，不能用来说明办事的规程。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“按照”后面不接“音量”，办事不说按照音量。"}], "explanations": {"程式": "正确。“按照一定的程式”指固定的规程，符合句意。", "颜色": "语义：办事要按规程，颜色与办事的方式无关。", "香味": "语义：香味是气味，不能用来说明办事的规程。", "音量": "搭配：“按照”后面不接“音量”，办事不说按照音量。"}, "sentence_index": 0, "correct_answer": "程式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把程式放进冰箱里了。", "explanation": "用法错误：程式是抽象的格式或规程，不是东西，不能放进冰箱。"}, {"text": "这篇文章的程式很甜。", "explanation": "用法错误：“甜”是味道，程式没有味道，不能这样形容。"}, {"text": "他把程式喝掉了一大半。", "explanation": "用法错误：“喝”的对象应是液体，程式不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93290, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "程式", "is_correct": true, "explanation": "正确答案。程式指一定的格式或规程。"}, {"text": "成熟", "is_correct": false, "explanation": "成熟 chéngshú 与 chéngshì 第二音节的韵母（ú 与 ì）和声调都不同，意思是发育完全。"}, {"text": "惩治", "is_correct": false, "explanation": "惩治 chéngzhì 与 chéngshì 声母不同（zh 与 sh），意思是惩罚、治理。"}, {"text": "成日", "is_correct": false, "explanation": "成日 chéngrì 与 chéngshì 声母不同（r 与 sh），意思是整天。"}], "explanations": {"程式": "正确答案。程式指一定的格式或规程。", "成熟": "成熟 chéngshú 与 chéngshì 第二音节的韵母（ú 与 ì）和声调都不同，意思是发育完全。", "惩治": "惩治 chéngzhì 与 chéngshì 声母不同（zh 与 sh），意思是惩罚、治理。", "成日": "成日 chéngrì 与 chéngshì 声母不同（r 与 sh），意思是整天。"}, "sentence_index": null, "correct_answer": "程式"}, "level_3": {"options": [{"text": "程式", "is_correct": true, "explanation": "正确。“公文的程式”指公文的固定格式，符合句意。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是烹饪用的，与公文格式无关。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：歌词是歌曲的文字，与公文无关。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱属于音乐，与公文无关。"}], "explanations": {"程式": "正确。“公文的程式”指公文的固定格式，符合句意。", "食谱": "语义：食谱是烹饪用的，与公文格式无关。", "歌词": "语义：歌词是歌曲的文字，与公文无关。", "乐谱": "语义：乐谱属于音乐，与公文无关。"}, "sentence_index": 6, "correct_answer": "程式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在窗台上种了一盆程式。", "explanation": "用法错误：“种”的对象是植物，程式不能种。"}, {"text": "那个孩子的程式长得很高。", "explanation": "用法错误：“长高”只用于人和植物，程式没有身高。"}, {"text": "他把程式擦干净了。", "explanation": "用法错误：“擦”的对象是有形的物体表面，程式是抽象的规程，不能擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师讲课有一只固定的程式。", "corrected_sentence": "老师讲课有一套固定的程式。", "error_description": "量词错误：“程式”应该用量词“套”，“只”不能用于程式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份公文有一套固定地程式。", "corrected_sentence": "这份公文有一套固定的程式。", "error_description": "结构助词错误：“固定”修饰名词“程式”，应用“的”，不能用“地”（“地”用于动词前）。应说“固定的程式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93291, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放任", "is_correct": true, "explanation": "正确：“放任”指任其自由发展、不加管束，与“用规矩管着”正相反，是反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指动脑子想问题，与约束、限制的意思没有反义关系。"}, {"text": "生长", "is_correct": false, "explanation": "“生长”指生物成长，与约束管制无关。"}, {"text": "传递", "is_correct": false, "explanation": "“传递”指由一方送到另一方，与约束管制无关。"}], "correct_answer": "放任", "explanations": {"放任": "正确：“放任”指任其自由发展、不加管束，与“用规矩管着”正相反，是反义关系。", "思考": "“思考”指动脑子想问题，与约束、限制的意思没有反义关系。", "生长": "“生长”指生物成长，与约束管制无关。", "传递": "“传递”指由一方送到另一方，与约束管制无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93291, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放纵", "is_correct": true, "explanation": "正确：“放纵”指不加约束、任其胡来，与“用规矩管着”正相反，是反义关系。"}, {"text": "建造", "is_correct": false, "explanation": "“建造”指修建房屋、桥梁等，与约束管制无关。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看，与约束管制无关。"}, {"text": "运输", "is_correct": false, "explanation": "“运输”指把货物运走，与约束管制无关。"}], "correct_answer": "放纵", "explanations": {"放纵": "正确：“放纵”指不加约束、任其胡来，与“用规矩管着”正相反，是反义关系。", "建造": "“建造”指修建房屋、桥梁等，与约束管制无关。", "观察": "“观察”指仔细看，与约束管制无关。", "运输": "“运输”指把货物运走，与约束管制无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93291, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "约制是用规矩管着，不让乱来。", "primary_collocate": null, "pronunciation": "yuē zhì", "ipa": "ɥɛ˥ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "学校用规定约制学生，不让他们乱来。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母应该约制孩子过度玩手机的行为。", "target_word": "约制", "complexity_tier": "T3", "furigana": "fùmǔ yīnggāi yuēzhì háizi guòdù wán shǒujī de xíngwéi", "sentence_source": "generated"}, {"text": "没有人约制他，他就越来越随便。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的制度约制着每个员工。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很难接受别人约制自己。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的规则能约制大家的行为。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师约制过班里爱吵闹的同学。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子太小，需要大人约制。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢有人约制他。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里有规矩，爸爸约制得很严。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "约制了", "label": "体标"}, {"form": "约制着", "label": "体标"}, {"form": "约制过", "label": "体标"}, {"form": "約制", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用规矩管着，不让乱来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0806fb53-8715-4a01-946f-96193aca6881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93291, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约制", "is_correct": true, "explanation": "正确：“约制”指用规矩管住，不让乱来，与句意“用规定管学生”一致。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：“帮助”是给予支持，与后半句“不让他们乱来”的限制意思冲突。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”的对象应是问题或事情，不能直接以“学生”作宾语。"}, {"text": "鼓励", "is_correct": false, "explanation": "语义：“鼓励”是肯定和支持，与“不让他们乱来”的约束意思相反。"}], "explanations": {"约制": "正确：“约制”指用规矩管住，不让乱来，与句意“用规定管学生”一致。", "帮助": "语义：“帮助”是给予支持，与后半句“不让他们乱来”的限制意思冲突。", "讨论": "配价：“讨论”的对象应是问题或事情，不能直接以“学生”作宾语。", "鼓励": "语义：“鼓励”是肯定和支持，与“不让他们乱来”的约束意思相反。"}, "sentence_index": 0, "correct_answer": "约制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的财务约制得很好，每一笔钱都有记录。", "explanation": "这里应该用〈管理〉。约制侧重用规矩管住、不让乱来；说财务条理清楚，要用“管理”。"}, {"text": "我们约制了明天见面的时间。", "explanation": "这句的“约”是订立约定的意思，“约制”没有这个用法，不能用来说约定时间。"}, {"text": "妈妈约制生病的孩子，还给他端水喝。", "explanation": "这里应该用〈照顾〉。约制是管束、限制，不能用来指照料病人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93291, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约制", "is_correct": true, "explanation": "正确：“约制”指管束、限制，符合“老师管住吵闹的同学”的语境。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”指用火烤制面包、点心等食物，与管束学生毫不相干。"}, {"text": "解剖", "is_correct": false, "explanation": "语义：“解剖”指剖开尸体或标本研究，与管束学生毫无关系。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”多用于花草、枝叶或头发，不能用来说修剪同学。"}], "explanations": {"约制": "正确：“约制”指管束、限制，符合“老师管住吵闹的同学”的语境。", "烘焙": "语义：“烘焙”指用火烤制面包、点心等食物，与管束学生毫不相干。", "解剖": "语义：“解剖”指剖开尸体或标本研究，与管束学生毫无关系。", "修剪": "搭配：“修剪”多用于花草、枝叶或头发，不能用来说修剪同学。"}, "sentence_index": 6, "correct_answer": "约制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员约制客人，态度很热情。", "explanation": "这里应该用〈招待〉。约制是管住、限制，不能用来指接待客人。"}, {"text": "这座楼约制有五十米高。", "explanation": "这句的“约”是大约的意思，“约制”没有这个用法，不能用来说高度大概多少。"}, {"text": "妈妈约制了一件新衣服送给我。", "explanation": "这里应该用〈定制〉。约制是用规矩管束人的行为，不能指按要求专门做衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93291, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宿舍的规定约制了着每个学生的晚归时间。", "corrected_sentence": "宿舍的规定约制着每个学生的晚归时间。", "error_description": "错误在“约制”之后：“了”与“着”不能同时出现。表示持续的约束状态只用“着”，应改为“约制着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93291, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸从来没有约制着孩子玩手机。", "corrected_sentence": "爸爸从来没有约制过孩子玩手机。", "error_description": "错误在“约制”之后：“从来没有”否定过去的经历，要用“过”，不能用表示持续的“着”，应改为“约制过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93292, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放纵", "is_correct": true, "explanation": "正确：“放纵”指不加约束、任其胡来，与“约束限制”是反义关系。"}, {"text": "尊重", "is_correct": false, "explanation": "“尊重”指敬重他人，与约束限制没有反义关系。"}, {"text": "挖掘", "is_correct": false, "explanation": "“挖掘”指从地下取出或深入发掘，与约束无关。"}, {"text": "保存", "is_correct": false, "explanation": "“保存”指保持原样、不使损坏，与约束无关。"}], "correct_answer": "放纵", "explanations": {"放纵": "正确：“放纵”指不加约束、任其胡来，与“约束限制”是反义关系。", "尊重": "“尊重”指敬重他人，与约束限制没有反义关系。", "挖掘": "“挖掘”指从地下取出或深入发掘，与约束无关。", "保存": "“保存”指保持原样、不使损坏，与约束无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93292, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "纵容", "is_correct": true, "explanation": "正确：“纵容”指一味宽容、不加约束，与“约束限制”是反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指把坏的东西修好，与约束限制无关。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指深入探讨问题，与约束限制无关。"}, {"text": "运送", "is_correct": false, "explanation": "“运送”指把人或物运到别处，与约束限制无关。"}], "correct_answer": "纵容", "explanations": {"纵容": "正确：“纵容”指一味宽容、不加约束，与“约束限制”是反义关系。", "修理": "“修理”指把坏的东西修好，与约束限制无关。", "研究": "“研究”指深入探讨问题，与约束限制无关。", "运送": "“运送”指把人或物运到别处，与约束限制无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93292, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "约束限制；管束。", "primary_collocate": null, "pronunciation": "yuē zhì", "ipa": "ɥɛ˥ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "法律约制每个人的行为。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同约制了双方的行为。", "target_word": "约制", "complexity_tier": "T3", "furigana": "hétong yuēzhì le shuāngfāng de xíngwéi", "sentence_source": "generated"}, {"text": "他很难约制自己的脾气。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些规定是用来约制司机的。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校约制学生带手机来上课。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有规则约制，比赛会很乱。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用制度约制员工上班时的行为。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规定约制着大家的行动。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲用规矩约制他晚上玩手机的时间。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的规则约制了养狗的人。", "target_word": "约制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "约制了", "label": "体标"}, {"form": "约制着", "label": "体标"}, {"form": "约制过", "label": "体标"}, {"form": "約制", "label": "繁体"}], "register": "书面", "sense_fingerprint": "约束限制；管束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0806fb53-8715-4a01-946f-96193aca6881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约制", "is_correct": true, "explanation": "正确：“约制”指约束限制，符合“法律约束每个人行为”的意思。"}, {"text": "帮助", "is_correct": false, "explanation": "搭配：“帮助”的对象通常是人，不能说帮助“行为”，也与句中的限制意思不合。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是喜爱、赞许，与“法律约束行为”的限制意思相反。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”是美化外表，与约束人的行为无关。"}], "explanations": {"约制": "正确：“约制”指约束限制，符合“法律约束每个人行为”的意思。", "帮助": "搭配：“帮助”的对象通常是人，不能说帮助“行为”，也与句中的限制意思不合。", "欣赏": "语义：“欣赏”是喜爱、赞许，与“法律约束行为”的限制意思相反。", "装饰": "语义：“装饰”是美化外表，与约束人的行为无关。"}, "sentence_index": 0, "correct_answer": "约制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工程师约制了一座桥。", "explanation": "这里应该用〈设计〉。约制是约束限制，不能用于设计或建造桥梁。"}, {"text": "那个湖约制有三公里长。", "explanation": "这句的“约”是大约的意思，“约制”没有这个用法，不能用来说长度大概多少。"}, {"text": "学校约制学生的写作能力。", "explanation": "这里应该用〈培养〉。约制是限制、管束，不能用来指培养能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约制", "is_correct": true, "explanation": "正确：“约制”指约束限制，符合“公司用制度管住员工上班时的行为”的语境。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，与“用制度”管住行为的限制意思不合。"}, {"text": "陪伴", "is_correct": false, "explanation": "搭配：“陪伴”的对象是人，不能说“陪伴行为”，也不能“用制度”陪伴。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是夸奖，与“用制度”约束行为的意思不协调。"}], "explanations": {"约制": "正确：“约制”指约束限制，符合“公司用制度管住员工上班时的行为”的语境。", "表扬": "语义：“表扬”是称赞，与“用制度”管住行为的限制意思不合。", "陪伴": "搭配：“陪伴”的对象是人，不能说“陪伴行为”，也不能“用制度”陪伴。", "赞美": "语义：“赞美”是夸奖，与“用制度”约束行为的意思不协调。"}, "sentence_index": 6, "correct_answer": "约制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家热烈约制新来的同学。", "explanation": "这里应该用〈欢迎〉。约制是约束限制，不能表示热情迎接。"}, {"text": "他们约制了周末一起爬山。", "explanation": "这句的“约”是约定的意思，“约制”没有这个用法，不能用来说约好的事。"}, {"text": "他在超市里约制水果。", "explanation": "这里应该用〈挑选〉。约制用于约束人的行为，不能用于挑选东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校规约制了着学生的作息时间。", "corrected_sentence": "校规约制着学生的作息时间。", "error_description": "错误在“约制”之后：“了”与“着”不能同时出现。表示持续的约束状态只用“着”，应改为“约制着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
