INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "掌握国家政权、支配和管理国家的人。", "primary_collocate": null, "pronunciation": "tǒng zhì zhě", "ipa": "tʰʊŋ˨˩˦ ʈʂɨ˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "殖民地的统治者制定了严格的法律。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，许多统治者重视教育。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位统治者掌握着国家的权力。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "统治者的决定会影响整个国家。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的统治者上台后，改变了税法。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "统治者需要得到人民的支持。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个王朝的最后一位统治者年纪很小。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "统治者通过法律管理国家。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多国家的统治者曾经是军人。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中写了一位聪明的统治者。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "统治者们", "label": "复数"}, {"form": "統治者", "label": "繁体"}], "register": "书面", "sense_fingerprint": "统治者：掌握国家政权并支配、管理国家的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59bfadb7-bca0-4e03-be83-d192fc022fe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "统治者", "is_correct": true, "explanation": "统治者掌握国家政权，能够制定法律，符合「殖民地的___制定了严格的法律」的句意。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民没有制定法律的权力，与句意不符。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：「制定」要求有意志的施事，桌子不能制定法律。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生不掌握国家政权，不能制定法律。"}], "explanations": {"统治者": "统治者掌握国家政权，能够制定法律，符合「殖民地的___制定了严格的法律」的句意。", "农民": "语义：农民没有制定法律的权力，与句意不符。", "桌子": "配价：「制定」要求有意志的施事，桌子不能制定法律。", "学生": "语义：学生不掌握国家政权，不能制定法律。"}, "sentence_index": 0, "correct_answer": "统治者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的统治者掌握着公司的权力。", "explanation": "这里应该用〈经理〉。统治者掌握的是国家政权，公司的负责人应说「经理」。"}, {"text": "这支球队的统治者负责安排球员。", "explanation": "这里应该用〈教练〉。统治者指掌握国家政权的人，负责安排球员的一般说「教练」。"}, {"text": "我发烧了，医院的统治者给我看了病。", "explanation": "这里应该用〈医生〉。统治者指掌握国家政权的人，给病人看病的应说「医生」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "统治者", "is_correct": true, "explanation": "统治者指掌握国家政权的人，「年纪很小」符合王朝末代君主的句意。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：量词「位」只用于人，不能用于「猫」。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有年纪，也不能是王朝的统治者，句子不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是王朝的统治者，「年纪很小」也不能用来形容河流。"}], "explanations": {"统治者": "统治者指掌握国家政权的人，「年纪很小」符合王朝末代君主的句意。", "猫": "搭配：量词「位」只用于人，不能用于「猫」。", "石头": "语义：石头没有年纪，也不能是王朝的统治者，句子不通。", "河流": "语义：河流不是王朝的统治者，「年纪很小」也不能用来形容河流。"}, "sentence_index": 6, "correct_answer": "统治者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台节目的统治者掌握着节目的走向。", "explanation": "这里应该用〈主持人〉。统治者掌握的是国家政权，节目主持人不能称为统治者。"}, {"text": "我们班的统治者每天给我们上数学课。", "explanation": "这里应该用〈老师〉。统治者指掌握国家政权的人，给学生上课的应说「老师」。"}, {"text": "我昨天在车站买票，那位统治者很热情。", "explanation": "这里应该用〈售票员〉。统治者指掌握国家政权的人，车站卖票的应说「售票员」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只统治者掌握着国家的大权。", "corrected_sentence": "那位统治者掌握着国家的大权。", "error_description": "「统治者」指人，量词应用「位」，这里把「位」错成「只」，「只」用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条统治者统治着整个国家。", "corrected_sentence": "那位统治者统治着整个国家。", "error_description": "「统治者」指人，应用量词「位」，这里把「位」错成「条」，「条」用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
