INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93299, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "管理下属各分局的上级机关。", "primary_collocate": null, "pronunciation": "zǒng jú", "ipa": "tsʊŋ˨˩˦ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "总局在北京，分局在各个城市。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事要先报告总局。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总局管着全市的二十个分局。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在总局工作了十年。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各分局都要听总局的安排。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总局的大楼就在河边。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分局把材料送到了总局。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总局下个月会派人来检查。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叔叔是总局的一名职员。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总局的决定，分局必须执行。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "总局长", "label": "复合"}], "register": "中性", "sense_fingerprint": "上级机关；总局与分局；向总局汇报", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3e1b82-d785-4be0-9594-3915e54d0855') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93299, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总局", "is_correct": true, "explanation": "正确：“总局”是管理各分局的上级机关，设在北京，与“分局在各个城市”相对应。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是时间，不能作“在北京”的处所主语。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“在北京”需要机构或地点作主语，“友谊”不能这样搭配。"}, {"text": "乐趣", "is_correct": false, "explanation": "语义：“乐趣”是抽象概念，不能存在于某个城市。"}], "explanations": {"总局": "正确：“总局”是管理各分局的上级机关，设在北京，与“分局在各个城市”相对应。", "生日": "语义：“生日”是时间，不能作“在北京”的处所主语。", "友谊": "搭配：“在北京”需要机构或地点作主语，“友谊”不能这样搭配。", "乐趣": "语义：“乐趣”是抽象概念，不能存在于某个城市。"}, "sentence_index": 0, "correct_answer": "总局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的总局在上海。", "explanation": "这里应该用〈老家〉。“总局”是行政机关，不能指家乡，“我家的总局”不成立。"}, {"text": "我的孩子每天在总局读书。", "explanation": "这里应该用〈学校〉。“总局”是行政机关，不是学习的地方，不能说“在总局读书”。"}, {"text": "他在总局吃了一顿很好吃的晚饭。", "explanation": "这里应该用〈饭馆〉。“总局”是行政机关，不是吃饭的地方，不能用来指餐馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93299, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总局", "is_correct": true, "explanation": "正确：“送到了”的终点是机构，“总局”与“材料”“分局把”相合。"}, {"text": "早上", "is_correct": false, "explanation": "语义：“早上”是时间，不能作“送到”的终点，“材料”不能送到时间里。"}, {"text": "思想", "is_correct": false, "explanation": "搭配：“送到”的终点应是地点或人，“思想”不能作终点。"}, {"text": "星期三", "is_correct": false, "explanation": "语义：“星期三”是时间词，不能接受材料，句子不成立。"}], "explanations": {"总局": "正确：“送到了”的终点是机构，“总局”与“材料”“分局把”相合。", "早上": "语义：“早上”是时间，不能作“送到”的终点，“材料”不能送到时间里。", "思想": "搭配：“送到”的终点应是地点或人，“思想”不能作终点。", "星期三": "语义：“星期三”是时间词，不能接受材料，句子不成立。"}, "sentence_index": 6, "correct_answer": "总局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去总局买东西。", "explanation": "这里应该用〈商场〉。“总局”是行政机关，不是售货的地方，不能用来指购物的场所。"}, {"text": "总局每天生产很多零件。", "explanation": "这里应该用〈工厂〉。“总局”是管理机关，不生产产品，不能说“总局生产零件”。"}, {"text": "总局的校长今天开会。", "explanation": "这里应该用〈局长〉。“总局”是管理机关，它的负责人是局长，不是学校的校长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93299, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "总局到省会，分局在各个县。", "corrected_sentence": "总局在省会，分局在各个县。", "error_description": "介词误用：表示“总局”所在地时应用“在”，“到”表示动作的终点，不能说“总局到省会”，应为“总局在省会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93299, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "各地分局每月要总局交报告。", "corrected_sentence": "各地分局每月要向总局交报告。", "error_description": "漏掉介词“向”。“交报告”的接受者“总局”需要用“向”引出，应为“向总局交报告”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
