INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93300, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "管理下属各分局的上级机关。", "primary_collocate": null, "pronunciation": "zǒng jú", "ipa": "tsʊŋ˨˩˦ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "这个总局管理全国的分局。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总局的局长今天开会。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地方分局要向总局汇报工作。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他调到总局工作了。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总局发来了一份新通知。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总局的办公楼设在市中心。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总局每年都会检查各分局。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题只有总局能解决。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总局里有很多部门。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天坐地铁去总局上班。", "target_word": "总局", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "总局长", "label": "复合"}], "register": "中性", "sense_fingerprint": "管理下属各分局的上级机关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3e1b82-d785-4be0-9594-3915e54d0855') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93300, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总局", "is_correct": true, "explanation": "正确：“总局”是管理下属分局的上级机关，与“管理全国的分局”相合。"}, {"text": "分局", "is_correct": false, "explanation": "语义：“分局”只管辖一个地区，不是管理全国分局的上级，与“全国”的范围不合。"}, {"text": "书店", "is_correct": false, "explanation": "语义：“书店”是卖书的商店，不是机关，不能管理分局。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“管理”的主语应是机关或单位，“食堂”不能作“管理”的主语。"}], "explanations": {"总局": "正确：“总局”是管理下属分局的上级机关，与“管理全国的分局”相合。", "分局": "语义：“分局”只管辖一个地区，不是管理全国分局的上级，与“全国”的范围不合。", "书店": "语义：“书店”是卖书的商店，不是机关，不能管理分局。", "食堂": "搭配：“管理”的主语应是机关或单位，“食堂”不能作“管理”的主语。"}, "sentence_index": 0, "correct_answer": "总局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他调到总局当厂长了。", "explanation": "这里应该用〈局长〉。“总局”是管理机关，它的负责人是局长，不能说“当厂长”。"}, {"text": "他调到总局当了一名小学老师。", "explanation": "这里应该用〈学校〉。“总局”是行政机关，小学老师应在学校任教，不能调到总局任职。"}, {"text": "他调到总局去种水稻了。", "explanation": "这里应该用〈农村〉。“总局”是行政机关，不是种地的地方，不能在总局种水稻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总局", "is_correct": true, "explanation": "正确：“总局”是有管理权的上级机关，可以每年检查各分局，与“各分局”相合。"}, {"text": "面包", "is_correct": false, "explanation": "语义：“面包”是食物，不能检查各分局，句子不成立。"}, {"text": "河", "is_correct": false, "explanation": "搭配：“检查”的施事应是有管理权的机关或人，“河”不能作施事。"}, {"text": "小时", "is_correct": false, "explanation": "语义：“小时”是时间单位，不能作“检查”的施事。"}], "explanations": {"总局": "正确：“总局”是有管理权的上级机关，可以每年检查各分局，与“各分局”相合。", "面包": "语义：“面包”是食物，不能检查各分局，句子不成立。", "河": "搭配：“检查”的施事应是有管理权的机关或人，“河”不能作施事。", "小时": "语义：“小时”是时间单位，不能作“检查”的施事。"}, "sentence_index": 6, "correct_answer": "总局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "总局的医生每天很忙。", "explanation": "这里应该用〈医院〉。“总局”是管理机关，没有医生，医生应属于医院。"}, {"text": "他是我们的总局，大家都很敬佩他。", "explanation": "这里应该用〈领导〉。“总局”指机关，不能用来指人；称呼人应说〈领导〉，不能说“他是我们的总局”。"}, {"text": "这个总局今年招了一千名学生。", "explanation": "这里应该用〈大学〉。“总局”是管理机关，不招收学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只总局负责全国的分局。", "corrected_sentence": "这个总局负责全国的分局。", "error_description": "量词错误：“总局”是机构，量词应用“个”，“只”用于动物等，不能用于“总局”，应为“这个总局”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天总局上班。", "corrected_sentence": "他每天在总局上班。", "error_description": "漏掉介词“在”。表示工作地点的“总局”前要加“在”，应为“在总局上班”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca976a8-a763-4e6b-830d-0660857ffdbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
